% copies of the Software, and to permit persons to whom the Software is
% furnished to do so, subject to the following conditions:
% 
% The above copyright notice and this permission notice shall be included in all
% copies or substantial portions of the Software.
% 
% THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
% IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
% FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
% AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
% LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
% OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
% SOFTWARE.

% ============

% set global variables
global selpath saveCTdata treeDir gen X ha3 UserFig fileOpen row col
global userRings userRings2 coreIn hpxS layers pxS titleName
global treeName currentSections saveName xs ys
global slabDraw areWeDone jump2ring insertThisRing ring2delete tree
global densityWholeCore extension densityTotal colorsTotal volume cracks crackLayers
global bottomCore topCore h2 h3 h3_width h3_std LDBdata totRings2 thisSectionName
global h_drive dirRow thisTreeName ring2erase subRegionName ldbDraw2
global p_axial p_arc p_box b_points p_degrees t_degrees flipCore x1 y1
global collectionYear collectionMonth moveOn dataOwner serverChoice xrayPos
global xrayDPI smoothed_on dataOwners currentLoadingTitle doingSeasonal

% settings for colors of buttons
moonriseColors = [214,146,156; 158,174,76; 244,167,49; 255,200,29; 216,184,124]/256;
butCols = [interp1(1:5,moonriseColors(:,1),linspace(1,5,100))',...
    interp1(1:5,moonriseColors(:,2),linspace(1,5,100))',...
    interp1(1:5,moonriseColors(:,3),linspace(1,5,100))'];

% hide standard figures
set(0,'DefaultFigureVisible','off');

% window size;
this_screen = get(0,'screensize');
this_screen(4) = this_screen(4)-120; % for menu bar
figscale = this_screen(4)/800;
textscale = figscale-0.2337;

TreeTracerversion = 1.23;
if ismac
    TreeTracerFormat = 'mchips'; % 'mchips' (Mac)
elseif ispc
    TreeTracerFormat = 'windows'; % 'windows'
end

% colors for various features
themeColor1 = [0.10, 0.83, 0.45];
themeColor2 = [0.89, 0.95, 0.95];
themeColor3 = [0.0824, 0.45, 0.25];

% initialize some defaults
flipCore = 0; % flip core toggle
n_loading_vids = 1; % loading videos of coring
n_loading_vidsCT = 1; % loading videos of cores
ct = 1; % CT or 2-D image toggle
smoothed_on = 0; % rings smoothed or "as-clicked" toggle
HU2dens = []; % density calibration equation, in form of HU = m*density + b
crackTol = 1; % pixels in "gap" to define cracks in core. See L&O Methods publication
thresh = []; % initialize, this is for defining tree vs surrounding air space
saveLocal = []; % toggle to remember working directory
unsaveLocal = []; % toggle to stop remembering working directory
coastlon = [];
coastlat = [];
interp_segments = [];
line_segments = [];
ringMarks1D = [NaN,NaN];
ringMarks1D2 = [NaN,NaN]; % for ring bottoms
returnSlabPos = [];
detectMode = 'gradient';
missingRings = [];
missingRingsList = {'';''};
treeROI = [];
measArea = [];
yrTog = 0;
inputTopYear = 0;
breaksRings = [];
skipsRings = [];
breaksRingsCumSum = [];
textClick2 = 'Currently working on top of late-wood rings';
ringType = 1; % main rings

% admin name
admin = 'TomDeCarlo';

% initialize figure, set visibility Off until finished setting up
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    UserFig0 = uifigure('Visible','off','Position',[50,100,600,850],'units','normalized','Color','w');
    UserFig = uifigure('Units','pixels','Position',[(this_screen(3)-1112*figscale)/2,(this_screen(4)-800*figscale)/2,1112*figscale,800*figscale],'Color',themeColor2,'Visible','off');
    checksize = get(UserFig,'Position');
    while checksize(2) < 10
        figscale = figscale*0.975;
        close(UserFig);
        UserFig = uifigure('Units','pixels','Position',[(this_screen(3)-1112*figscale)/2,(this_screen(4)-800*figscale)/2,1112*figscale,800*figscale],'Color',themeColor2,'Visible','off');
        checksize = get(UserFig,'Position');
    end
    set(UserFig,'units','normalized')
else
    UserFig = figure('Visible','off','Position',figscale*[400,400,600,200],'units','normalized','Color',themeColor2);
end
UserFig.HandleVisibility = 'callback';
iptPointerManager(UserFig, 'enable');

% locate where files are stored
refPath0 = which('ref_file.mat');
refPath0split = strsplit(refPath0,'ref_file.mat');
refPath = refPath0split{1};

ftp_ip1 = 'sftp.hidrive.ionos.com'; % could use different server for login info if desired
ftp_ip2 = 'sftp.hidrive.ionos.com'; % main data location
ftp_user1 = 'treetracer';
ftp_user2 = 'treetracer';
ftp_password = 'We<3dendro';

% loading vid at intro
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    dispVidCT = uihtml(UserFig0);
    dispVidCT.Position = [100,140,400,650];
    
    rng('shuffle')
    rand_vidCT = round(rand(1)*(n_loading_vidsCT-1))+1;
    dispVidCT.HTMLSource = (fullfile('loading_movies',strcat('ct_movie',num2str(rand_vidCT),'.html')));

    lblWelcome = uicontrol(UserFig0,'Style','text','String','Welcome to TreeTracer',...
        'Position',[170,815,280,35],'Units','normalized','FontSize',textscale*20,'FontName','Fanta','Visible','on',...
        'BackgroundColor','w');
end

% label for connection error
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    lblFTPerror = uicontrol(UserFig0,'Style','text','String',...
        {'Cannot connect to TreeTrove server.';...
        'You may not be connected to the internet, or the server may be temporarily down.';...
        'Please try again later or email us at support@TreeTracer.org for help.'},...
        'units','pixel','Position',[30,200,550,80],'ForegroundColor','r',...
        'units','normalized','BackgroundColor',themeColor2,...
        'FontSize',textscale*11,'FontName','Arial','Units','normalized','Visible','off');
else
    lblFTPerror = uicontrol(UserFig,'Style','text','String',...
        {'Cannot connect to TreeTrove server.';...
        'You may not be connected to the internet, or the server may be temporarily down.';...
        'Please try again later or email us at support@TreeTracer.org for help.'},...
        'units','pixel','Position',[30,200,550,80],'ForegroundColor','r',...
        'units','normalized','BackgroundColor',themeColor2,...
        'FontSize',textscale*11,'FontName','Arial','Units','normalized','Visible','off');
end

% create options for remembering local path
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    saveLocal = uicheckbox(UserFig0,'Text','Save selection for next time?','Value',0,'Position',[150,20,200,25],...
        'FontSize',textscale*14,'FontName','Arial');

    unsaveLocal = uicheckbox(UserFig0,'Text','Stop remembering location','Value',0,'Position',[50,10,300,25],...
        'FontSize',textscale*14,'FontName','Arial','Visible','off');
end

% if cannot find the saved path file, create one with a not real path
try load('saved_path.mat','issavedpath','saved_selpath')
catch
    issavedpath = 0;
    saved_selpath = 'fake_path';
    refPath0 = which('ref_file.mat');
    refPath0split = strsplit(refPath0,'ref_file.mat');
    refPath = refPath0split{1};
    save(fullfile(refPath,'saved_path'),'issavedpath','saved_selpath')
end

% button for saving local path
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    lblSavedPath = uicontrol(UserFig0,'Style','text','String',...
        ' ',...
        'units','pixel','Position',[50,70,500,50],...
        'units','normalized','BackgroundColor','w',...
        'FontSize',textscale*11,'FontName','Arial','Units','normalized','Visible','off',...
        'horizontalAlignment','left');
else
    lblSavedPath = uicontrol(UserFig,'Style','text','String',...
        ' ',...
        'units','pixel','Position',figscale*[50,70,500,50],...
        'units','normalized','BackgroundColor','w',...
        'FontSize',textscale*11,'FontName','Arial','Units','normalized','Visible','off',...
        'horizontalAlignment','left');
end

% button for launching main program
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    proceedIn = uicontrol(UserFig0,'Style','pushbutton',...
        'String',{'Go!'},'Visible','on',...
        'Position',[520,60,70,70],'Units','normalized','BackgroundColor',[0.61,0.86,0.57],'ForegroundColor',[0,0,0],'FontSize',textscale*18,'FontName','Arial','Callback',@proceed_fun);
else
    proceedIn = uicontrol(UserFig,'Style','pushbutton',...
        'String',{'Go!'},'Visible','on',...
        'Position',[520,60,70,70],'Units','normalized','BackgroundColor',[0.61,0.86,0.57],'ForegroundColor',[0,0,0],'FontSize',textscale*18,'FontName','Arial','Callback',@proceed_fun);
end

% if the local path has been saved, use that
if issavedpath == 1
    selpath = saved_selpath;

    set(lblSavedPath,'Visible','on','String',...
        sprintf('Local directory is:\n %s',selpath))

    chooseDirIn = uicontrol(UserFig0,'Style','pushbutton',...
        'String',{'Change path'},'Visible','on',...
        'Position',[50,40,200,30],'Units','normalized','BackgroundColor',[0.7 0.7 0.7],'ForegroundColor',[0,0,0],'FontSize',textscale*12,'FontName','Arial','Callback',@chooseDir_fun);

    set(saveLocal,'Visible','off')
    set(unsaveLocal,'Visible','on')
    set(proceedIn,'Visible','on')

else % otherwise, create button to choose the local path

    set(proceedIn,'Visible','off')

    if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
        chooseDirIn = uicontrol(UserFig0,'Style','pushbutton',...
            'String',{'Choose local working directory'},'Visible','on',...
            'Position',[150,60,300,60],'Units','normalized','BackgroundColor',[0.61,0.86,0.57],'ForegroundColor',[0,0,0],'FontSize',textscale*14,'FontName','Arial','Callback',@chooseDir_fun);
    else
        chooseDirIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'Choose local working directory'},'Visible','on',...
            'Position',[150,60,300,60],'Units','normalized','BackgroundColor',[0.61,0.86,0.57],'ForegroundColor',[0,0,0],'FontSize',textscale*14,'FontName','Arial','Callback',@chooseDir_fun);
    end
end

% start the main program
    function proceed_fun(src,event)
        uiresume(UserFig0)
    end

% set local path function
    function chooseDir_fun(src,event)
        set(chooseDirIn,'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(UserFig0,'Visible','off')
        end
        selpath = uigetdir([],'Choose your local working folder');
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            uiresume(UserFig0)
        else
            uiresume(UserFig)
            set(UserFig,'Units','Pixels','Position',figscale*[54,339,1112,800],'Units','normalized')
        end
    end

% make sure we can connect to sftp server 1
try cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
catch
    if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
        set(UserFig0,'Visible','on')
        set(lblFTPerror,'Visible','on')
    end
end

% make sure we can access TreeTrove folder of sftp server 1
try cd(cache1,'tdecarlo19/public/TreeTrove');
catch
    if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
        set(UserFig0,'Visible','on')
        set(lblFTPerror,'Visible','on')
    end
end


% button to see explanation of local path
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    selectDirHelpIn = uicontrol(UserFig0,'Style','pushbutton',...
        'String',{'Help'},'Visible','on',...
        'Position',[540,10,50,30],'Units','normalized','BackgroundColor',[255, 189, 68]/256,'ForegroundColor',[0,0,0],'FontSize',textscale*11,'FontName','Arial','Callback',@selectDirHelp_fun);
    htextLink1 = uihyperlink(UserFig0,'URL','https://www.reeflab.science/TreeTracer.html','Text','www.TreeTracer.org',...
        'FontSize',textscale*14,'FontName','Arial','Visible','on','Position',[390,10,140,30]);
else
    selectDirHelpIn = uicontrol(UserFig,'Style','pushbutton',...
        'String',{'Help'},'Visible','off',...
        'Position',figscale*[540,10,50,30],'Units','normalized','BackgroundColor',[255, 189, 68]/256,'ForegroundColor',[0,0,0],'FontSize',textscale*11,'FontName','Arial','Callback',@selectDirHelp_fun);
end

% explanation of local path
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    lblselectDirHelp = uicontrol(UserFig0,'Style','text','String',...
        {'Please select a folder on your computer where TreeTracer files will be stored.';...
        'Files including core metadata, map data, image data, and any downloaded datasets';...
        'will be stored in this folder.'},...
        'units','pixel','Position',[30,150,550,60],'ForegroundColor','k',...
        'units','normalized','BackgroundColor','w',...
        'FontSize',textscale*11,'FontName','Arial','Units','normalized','Visible','off');
else
    lblselectDirHelp = uicontrol(UserFig,'Style','text','String','','Visible','off');
end

% turn on help label
function selectDirHelp_fun(src,event)
    set(lblselectDirHelp,'Visible','on')
end

% Pause while we wait for decision on local directory
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    uiwait(UserFig0)
else
    uiwait(UserFig)
end

% if decided to newly save local path, do that now
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    if saveLocal.Value == 1
        issavedpath = 1;
        saved_selpath = selpath;
        refPath0 = which('ref_file.mat');
        refPath0split = strsplit(refPath0,'ref_file.mat');
        refPath = refPath0split{1};
        save(fullfile(refPath,'saved_path'),'issavedpath','saved_selpath')
    end

    try % if chose to stop remembering local path, remove that now
        if unsaveLocal.Value == 1
            issavedpath = 0;
            saved_selpath = 'fake_path';
            refPath0 = which('ref_file.mat');
            refPath0split = strsplit(refPath0,'ref_file.mat');
            refPath = refPath0split{1};
            save(fullfile(refPath,'saved_path'),'issavedpath','saved_selpath')
        end
    catch
    end
end

% turn off features of first figure (we will just close it later)
set(chooseDirIn,'Visible','off')
set(proceedIn,'Visible','off')
set(lblselectDirHelp,'Visible','off')
set(selectDirHelpIn,'Visible','off')
set(htextLink1,'Visible','off')
set(unsaveLocal,'Visible','off')
set(saveLocal,'Visible','off')
set(unsaveLocal,'Visible','off')
set(lblSavedPath,'Visible','off')

% loading text while we set up main figure
if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
    lblLoadingIntro = uicontrol(UserFig0,'Style','text','String',...
        {'Loading, please wait'},...
        'units','pixel','Position',[100,50,400,60],'ForegroundColor','k',...
        'units','normalized','BackgroundColor','none',...
        'FontSize',textscale*16,'FontName','Arial','Units','normalized','Visible','on');
else
    lblLoadingIntro = uicontrol(UserFig,'Style','text','String',...
        {'Loading, please wait'},...
        'units','pixel','Position',figscale*[100,50,400,60],'ForegroundColor','k',...
        'units','normalized','BackgroundColor','none',...
        'FontSize',textscale*16,'FontName','Arial','Units','normalized','Visible','off');
end

pause(0.01) % to ensure refreshed figures

% download the core master directory from the sftp server and save it on the
% local driver in a folder called "my_trees"
try mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
catch
    cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password); % make sure we can connect to sftp server 1
    cd(cache1,'tdecarlo19/public/TreeTrove');
    mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
end

% import master directory into this session
treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));

% button for checking latest version
latestVersionIn = uicontrol(UserFig,'Style','pushbutton',...
    'String',{'Check for updates'},'Visible','off',...
    'Position',figscale*[180,10,180,40],'Units','normalized','BackgroundColor',[255, 189+50, 68+20]/256,'ForegroundColor',[0,0,0],'FontSize',textscale*14,'FontName','Arial','Callback',@checkVersion_fun);

keepLatestLabel = 0; % toggle for which message to show
latest_version = []; % to display latest version number
    function checkVersion_fun(src,event)
        set(latestVersionIn,'Visible','off')
        set(lblCheckingUpdates,'Visible','on')
        pause(0.01)
    end

lblCheckingUpdates = uicontrol(UserFig,'Style','text','String','Checking for updates, please wait...',...
    'Position',figscale*[100,95,400,20],'Units','normalized','FontSize',textscale*11,'FontName','Arial','Visible','off');

lblUp2date = uicontrol(UserFig,'Style','text','String','You have the latest version of TreeTracer',...
    'Position',figscale*[100,110,280,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

lblneed2Update = uicontrol(UserFig,'Style','text','String',' ',...
    'Position',figscale*[100,145,215,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

gettingUserGuide = uicontrol(UserFig,'Style','text','String','Check your downloads',...
    'Position',figscale*[780,710,200,60],'Units','normalized','FontSize',textscale*11,'FontName','Arial','Visible','off');

gettingUserGuideFail = uicontrol(UserFig,'Style','text','String',{'Something went wrong.';'Download user guide from';'www.TreeTracer.org'},...
    'Position',figscale*[780,710,200,60],'Units','normalized','FontSize',textscale*11,'FontName','Arial','Visible','off');

getUserGuideIn = uicontrol(UserFig,'Style','pushbutton',...
    'String',{'Download';'User-Guide'},'Visible','on',...
    'Position',figscale*[780,710,160,60],'Units','normalized','BackgroundColor',[255, 189+50, 68+20]/256,'ForegroundColor',[0,0,0],'FontSize',textscale*14,'FontName','Arial','Callback',@downloadguide_fun);

% download current user guide
    function downloadguide_fun(src,event)
        set(getUserGuideIn,'Visible','off')
        pause(0.01)
        mget22(cache1,'latest_userguide_link.csv',refPath);
        latest_url = importdata(fullfile(refPath,'latest_userguide_link.csv'));
        delete(fullfile(refPath,'latest_userguide_link.csv'))
        try
            if strcmp('MACI64',computer)
                dlDir = fullfile('/Users',char(java.lang.System.getProperty('user.name')), 'Downloads');
                websave(fullfile(dlDir,'TreeTracer-UserGuide'),latest_url{1});
            else
                dlDir = fullfile(getenv('USERPROFILE'), 'Downloads');
                websave(fullfile(dlDir,'TreeTracer-UserGuide'),latest_url{1});
            end
        catch
            set(gettingUserGuideFail,'Visible','on')
        end
        set(gettingUserGuide,'Visible','on')
    end

% Get the list of "regions" (column 3)
% Note we skip row 1 because it's the header information
regionList = unique(treeDir.textdata(2:end,3));

% Print text on figure to say we will check registration
lblVerifying = uicontrol(UserFig,'Style','text','String','We will email you soon once your registration is confirmed',...
    'Position',figscale*[150,590,700,30],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

% cancel register function
    function cancel_register_user(src,event)

        set(passwordIn,'Visible','on')
        set(htextPassword,'Visible','on')
        set(lblduplicateUser,'Visible','off')
        set(lblduplicateEmail,'Visible','off')
        set(emailIn,'Visible','off')
        set(htextEmail,'Visible','off')
        %set(htextPasswordConfirm,'Visible','off')
        %set(passwordInConfirm,'Visible','off')
        set(loginIn,'Visible','on')
        set(lblcheckEmail,'Visible','off')
        set(verifySetIn,'Visible','off')
        set(htextVerify,'Visible','off')
        set(htextFirstName,'Visible','off')
        set(htextLastName,'Visible','off')
        set(firstNameIn,'Visible','off')
        set(lastNameIn,'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(saveLogin,'Visible','on')
        end
        set(getUserGuideIn,'Visible','on')
        set(gettingUserGuideFail,'Visible','off')
        set(gettingUserGuide,'Visible','off')

    end

lblcheckEmail = uicontrol(UserFig,'Style','text','String','Please check your email and enter your code below',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

lblduplicateUser = uicontrol(UserFig,'Style','text','String','This username is already taken',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

lblOnlyChars = uicontrol(UserFig,'Style','text','String','Username must contain only letters or numbers',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

lblduplicateEmail = uicontrol(UserFig,'Style','text','String','A username is already registered to this email',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

register_response = [];

% Print text on figure to type in username
htextVerify = uicontrol(UserFig,'Style','text','String','Verification code:','Visible','off',...
    'Position',figscale*[320,550,150,25],'Units','normalized','BackgroundColor',themeColor1,'ForegroundColor',[0,0,0],'FontSize',textscale*12,'FontName','Arial');

% Create edit bar for user to type username
verifySetIn = uicontrol(UserFig,'Style','Edit','Visible','off',...
    'Position',figscale*[475,550,100,25],'Units','normalized','Callback', @verify_Callback);

loginIn = uicontrol(UserFig,'Style','pushbutton',...
    'String',{'Login'},'Visible','on',...
    'Position',figscale*[600,710,160,60],'Units','normalized','FontSize',textscale*14,'FontName','Arial','BackgroundColor',themeColor1,'Callback',@login);

noSuchUser = uicontrol(UserFig,'Style','text','String','Username does not exist',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

wrongPassword = uicontrol(UserFig,'Style','text','String','Incorrect password',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

unmatchedPassword = uicontrol(UserFig,'Style','text','String','Passwords do not match',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

missingName = uicontrol(UserFig,'Style','text','String','Need to provide first and last name',...
    'Position',figscale*[250,600,500,20],'Units','normalized','FontSize',textscale*12,'FontName','Arial','Visible','off');

htextHelp = uicontrol(UserFig,'Style','text','String','Email us at support@TreeTracer.org for assistance',...
    'Position',figscale*[650,15,500,20],'Units','normalized','FontSize',textscale*10,'FontName','Arial','Visible','on');

htextLink2 = uihyperlink(UserFig,'URL','https://www.reeflab.science/TreeTracer.html','Text','www.TreeTracer.org',...
    'Position',figscale*[575,15,500,20],'FontSize',textscale*14,'FontName','Arial','Visible','on');

