    function about_callback(src,event)

        about_text_label = sprintf(['TreeTracer is a software program for analysis of computed tomography ' ...
            '(CT) scans or 2-D images of trees. This version of TreeTracer is linked with TreeTrove, which is ' ...
            'a repository of tree images collected around the world. For more information about how to use TreeTracer, please ' ...
            'visit www.TreeTracer.org. TreeTracer and TreeTrove were developed by Dr. Tom DeCarlo, with contributions ' ...
            'from Julia Sousa Lima Blas, and funding support from the National Science Foundation (award 2444864).\n\n' ...
            'TreeTracer is a shared community resource. We encourage submissions of any available tree core images. We also ' ...
            'welcome new analyses of growth rates based on the datasets stored in TreeTrove. Tree cores that have ' ...
            'been used in publications should be shared openly. However, we also encourage submissions of unpublished images, ' ...
            'and we are able to restrict access to data from certain cores at the request of the submitter. Please note that ' ...
            'TreeTracer can only be used with cores that are stored on TreeTrove. When using data from TreeTrove, please be careful to cite ' ...
            'appropriate publications or acknowledge those who collected the cores. The appropriate citations and/or '...
            'acknowledgements are displayed in the output .csv file of each core.\n\nEmail us at support@TreeTracer.org with questions ' ...
            'or for assistance with submitting datasets.']);

        set(htextAbout,'String',about_text_label)

        about_text_wrapped = textwrap(htextAbout,{htextAbout.String});

        %set(htextAbout,'String',about_text_wrapped,'Visible','on','Units','pixels',...
        %    'Position',figscale*[200,200,800,400],'Units','normalized','HorizontalAlignment', 'left')

        set(htextAbout,'String',about_text_label,'Visible','on','Units','pixels',...
            'Position',figscale*[200,200,800,400],'Units','normalized','HorizontalAlignment', 'left')

        set(h_map_cover,'Visible','off')
        set(loginIn,'Visible','off')
        set(UserSetIn,'Visible','off')
        set(htextUser,'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(saveLogin, 'Visible','off')
        end
        set(htextPassword,'Visible','off')
        set(passwordIn,'Visible','off')
        set(noSuchUser,'Visible','off')
        set(wrongPassword,'Visible','off')
        set(lblcheckEmail2,'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(htextLeaders,'Visible','off')
            set(htextLeadersYTD,'Visible','off')
            set(htextTotalCores,'Visible','off')
            set(leaderBoard,'Visible','off')
            set(leaderBoard_2,'Visible','off')
        end
        set(latestVersionIn,'Visible','off')
        set(gettingUserGuideFail,'Visible','off')
        set(getUserGuideIn,'Visible','off')
        set(gettingUserGuide,'Visible','off')
        set(lblneed2Update,'Visible','off')
        set(lblUp2date,'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(saveLogin,'Visible','off')
        end
        set(uiAboutCancel,'Visible','off')
        set(uiAbout,'Visible','off')

        set(uiAboutCancel,'Visible','on')
        set(uiAbout,'Visible','off')

    end

