    htextLeaders = uicontrol(UserFig,'Style','text','String','Overall Leaderboard','Visible','on',...
        'Position',figscale*[200,490,250,30],'Units','normalized','BackgroundColor','none',...
        'ForegroundColor',themeColor1,'FontSize',textscale*16,'FontName','Arial');

