% Function for returning to main menu
    function mainMenu(src,event)

        try set(h_map_cover,'Visible','off','Color',themeColor2,...
                'xcolor',themeColor2,'ycolor',themeColor2)
        catch
        end

        try
            delete(calibPlot)
            delete(calibLine)
        catch
        end

        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            try delete(dispVidCT)
                set(lblGracious,'Visible','off')
            catch
            end
        end

        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            try set(userTable1,'Visible','off')
                set(userTable2,'Visible','off')
            catch
            end
        end

        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            try set(userTable3,'Visible','off')
            catch
            end
        end

        set(UserFig,'Color',themeColor2)

        dataMode = 0;
        view_only = 0;
        coreIn.Value = 1;
        regionIn.Value = 1;
        subRegionIn.Value = 1;
        sectionIn.Value = 1;
        flipCore = 0;
        sectionName = '';

        set(mainMenuIn, 'Visible','off')
        set(openChooseIn, 'Visible','on')
        dispName = 'none';
        try
            foundMeta = 0;
            try coreInfo = importdata(fullfile(selpath,'my_trees','current_image','dicoms','CoreMetaData.csv'));
                ct = 1;
                foundMeta = 1;
            catch
                try coreInfo = importdata(fullfile(selpath,'my_trees','current_image','image','CoreMetaData.csv'));
                    ct = 0;
                    foundMeta = 1;
                catch
                end
            end
            if foundMeta == 1
                % Load metadata
                hasDataPart = 0;
                try checkInfo = coreInfo.data;
                    hasDataPart = 1;
                catch
                end
                if hasDataPart == 1
                    treeName = coreInfo.textdata{1};
                    sectionName = num2str(coreInfo.data);
                else
                    treeName = coreInfo{1};
                    if length(coreInfo)>1
                        sectionName = coreInfo{2};
                    else
                        sectionName = ''; % default
                    end
                end
                if strcmp(sectionName,'')
                    dispName = strcat(treeName);
                else
                    dispName = strcat(treeName,'/',sectionName);
                end
            end
        catch
        end
        
        % set open last button text
        if ~strcmp(dispName,'none')
            set(openLastIn, 'Visible','on')
            set(openLastIn, 'String',{'Open last scan';strcat('(',dispName,')')})
        end
        set(getDataIn, 'Visible','on')
        set(saveDataIn, 'Visible','on')
        set(htextUser, 'Visible','off')
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            set(saveLogin, 'Visible','off')
            set(userProfileIn,'Visible','on')
            set(coreDirIn,'Visible','on')
