    citeList = {''};
    function addCoreCiteTable(src,event)

        validCore = 0;
        try coreFound = find(strcmp(treeDir.textdata(:,1),coreCiteAddIn.String));
            if length(coreFound)
                validCore = 1;
                set(lblCoreAddStatus,'Visible','off');
            end
        catch
            set(lblCoreAddStatus,'String','Invalid core name','Visible','on');
        end

        if validCore == 1
            if length(citeList) == 1
                citeList{1} = coreCiteIn.String;
                citeList{2} = coreCiteAddIn.String;
            else
                if any(strcmp(citeList,coreCiteAddIn.String)) % remove from list
                    citeList{find(strcmp(citeList,coreCiteAddIn.String))} = [];
                else % add to list
                    citeList{length(citeList)+1} = coreCiteAddIn.String;
                end
            end
        end
        coreCiteAddIn.String = '';
        coreCiteApplyListIn.Items = citeList;

    end

