            thisRow = find(strcmp(treeDirHold.textdata(:,1),citeList{iikk}));
            this_cite = treeDirHold.textdata(:,8);
            if length(doiUrl2)>1
                this_cite{thisRow} = doiUrl2;
            end
            this_bib = treeDirHold.textdata(:,10);
            if length(bibTexStringNew)>1
                this_bib{thisRow} = bibTexStringNew;
            end
            treeDirStruct = struct('name',treeDirHold.textdata(:,1),...
                'piece',treeDirHold.textdata(:,2),...
                'region',treeDirHold.textdata(:,3),...
                'sub_region',treeDirHold.textdata(:,4),...
                'genus',treeDirHold.textdata(:,5),...
                'owner',treeDirHold.textdata(:,6),...
                'notes',treeDirHold.textdata(:,7),...
                'citation',this_cite,...
                'acknowledgement',treeDirHold.textdata(:,9),...
                'bibtex',this_bib,...
                'hard_drive',treeDirHold.data(1,1),...
                'flip',treeDirHold.data(1,2),...
                'lat',treeDirHold.data(1,3),...
                'lon',treeDirHold.data(1,4),...
                'elevation',treeDirHold.data(1,5),...
                'month',treeDirHold.data(1,6),...
                'year',treeDirHold.data(1,7),...
                'file_size',treeDirHold.data(1,8),...
                'unlocked',treeDirHold.data(1,9),...
                'denslope',treeDirHold.data(1,10),...
                'denintercept',treeDirHold.data(1,11),...
                'ct',treeDirHold.data(1,12),...
                'imageinvert',treeDirHold.data(1,13),...
                'dpi',treeDirHold.data(1,14));
            for ic = 1:length(treeDirHold.data(:,1))
                treeDirStruct(ic).hard_drive = treeDirHold.data(ic,1);
                treeDirStruct(ic).flip = treeDirHold.data(ic,2);
                treeDirStruct(ic).lat = treeDirHold.data(ic,3);
                treeDirStruct(ic).lon = treeDirHold.data(ic,4);
                treeDirStruct(ic).elevation = treeDirHold.data(ic,5);
                treeDirStruct(ic).month = treeDirHold.data(ic,6);
                treeDirStruct(ic).year = treeDirHold.data(ic,7);
                treeDirStruct(ic).file_size = treeDirHold.data(ic,8);
                treeDirStruct(ic).unlocked = treeDirHold.data(ic,9);
                treeDirStruct(ic).denslope = treeDirHold.data(ic,10);
                treeDirStruct(ic).denintercept = treeDirHold.data(ic,11);
                treeDirStruct(ic).ct = treeDirHold.data(ic,12);
                treeDirStruct(ic).imageinvert = treeDirHold.data(ic,13);
                treeDirStruct(ic).dpi = treeDirHold.data(ic,14);
            end

            if makeLiPDIn2.Value == 1
                try
                    try close(cache3)
                    catch
                    end
                    cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                    server_path = strcat('tdecarlo19/public/hd1/',treeDirHold.textdata{thisRow,3},'/',treeDirHold.textdata{thisRow,4},'/',...
                        treeDirHold.textdata{thisRow,1},'/',treeDirHold.textdata{thisRow,2});
                    server_path(double(server_path)==32) = 95; % converts spaces to _
                    cd(cache3,server_path);
                    dirOut = findRingFiles(treeDirHold.textdata{thisRow,1},treeDirHold.textdata{thisRow,2});
                    % get most recent file
                    if length(dirOut) > 1
                        these_dates = [];
                        for jjkki = 1:length(dirOut)
                            str1 = strsplit(dirOut{jjkki},'_');
                            if strcmp(str1{1},saveFileName)
                                these_dates(jjkki) = datenum(str1{2});
                            end
                        end
                    end
                    if length(these_dates)
                        dirOut = dirOut(find(these_dates==max(these_dates)));
                        currentRegion = treeDirHold.textdata{thisRow,3};
                        treeName = treeDirHold.textdata{thisRow,1};
                        sectionName = treeDirHold.textdata{thisRow,2};
                        getRingFile(treeDirHold.textdata{thisRow,1},treeDirHold.textdata{thisRow,2},dirOut{1})
                        region_text = currentRegion;
                        %region_text(double(region_text)==32) = 95;
                        thisFile = readtable(fullfile(selpath,'my_trees','datasets',region_text,treeDirHold.textdata{thisRow,1},treeDirHold.textdata{thisRow,2},strcat('ringwidth_output_',dirOut{1},'.csv')));

                        % rows for annual data
                        rowTop = find(thisFile{:,1}==1);
                        rowBot = find(thisFile{:,1}==nanmax(thisFile{:,1}));

                        this_file_yrs = thisFile{rowTop:rowBot,2};
                        this_file_extension = thisFile{rowTop:rowBot,3};
                        this_file_extension_err = thisFile{rowTop:rowBot,4};

                        % count = 0;
                        % 
                        % % upate annual data
                        % for kkj = rowTop:rowBot
                        % 
                        %     count = count+1;
                        % 
                        %     this_file_yrs(count) = str2num(thisFile.textdata{kkj,2});
                        %     this_file_extension(count) = str2num(thisFile.textdata{kkj,3});
                        %     this_file_extension_err(count) = str2num(thisFile.textdata{kkj,4});
                        % 
                        % end

                        travelTotal = flipud(this_file_extension);
                        travelTotal_std = flipud(this_file_extension_err);
                        inputTopYear = this_file_yrs(1);
                        this_year = collectionYear;
                        try this_month = datestr(datetime(1,collectionMonth,1),'mmmm');
                        catch
                            this_month = '';
                        end

                        dataOwner = treeDirHold.textdata(thisRow,6);
                        dataOwners = {''};
                        for jjj = 1:length(dataOwner)
                            dataOwners(jjj,1:length(strsplit(strcat(dataOwner{jjj},'//',admin),'//'))) = strsplit(strcat(dataOwner{jjj},'//',admin),'//');
                        end

                        makeLiPD(this_bib{thisRow},this_cite{thisRow},travelTotal,travelTotal_std,inputTopYear,this_year,this_month)
                    end

                catch
                end
            end
            %treeDirHold0 = treeDirHold;
            writetable(struct2table(treeDirStruct),fullfile(selpath,'my_trees','tree_directory_master.txt'),'Delimiter','\t')
        end
        try close(cache3)
        catch
        end
        
        try
            cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
            cd(cache3,'tdecarlo19/public/TreeTrove')
            mput(cache3,fullfile(selpath,'my_trees','tree_directory_master.txt'))
        catch
            set(lblCoreSearchStatus,'String','Upload failed');
        end
        pause(5)
        
        % load new version into this session:
        treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));
        set(lblCoreSearchStatus,'Visible','off');
    end

doiUrl2 = '';
bibTexString = '';
    function coreCiteSearch(src,event)

        doiUrl2 = '';
        bibTexString = '';
        coreInput = coreCiteIn.String;
        set(lblCiteTitleEdit,'String','')
        set(lblCiteAuthorEdit,'String','')
        set(lblCiteJournalEdit,'String','')
        set(lblCiteVolumeEdit,'String','')
        set(lblCiteNumberEdit,'String','')
        set(lblCitePageEdit,'String','')
        set(lblCiteYearEdit,'String','')
        bibtab = [];
        hasbib = 0;
        try coreFound = find(strcmp(treeDir.textdata(:,1),coreInput));
            if searchingByDOIinput == 0
                this_cite = treeDir.textdata{coreFound,8};
                set(lblCiteDOIEdit,'String','')
            end
            try
                if searchingByDOIinput == 1
                    if iscell(lblCiteDOIEdit.String)
                        this_cite = lblCiteDOIEdit.String{1};
                    else
                        this_cite = lblCiteDOIEdit.String;
                    end
                end
                if length(this_cite)<2
                    set(lblCoreSearchStatus,'Visible','on','String','No DOI found for this core')
                else
                    this_bib = treeDir.textdata{coreFound,10};
                    if length(this_bib)<3 || searchingByDOIinput == 1
                        doi = this_cite;
                        checkFront = strsplit(doi,'https://');
                        if length(checkFront)==2
                            doi = checkFront{2};
                        end
                        checkFront2 = strsplit(doi,'http://');
                        if length(checkFront2)==2
                            doi = checkFront2{2};
                        end
                        checkFront3 = strsplit(doi,'dx.doi.org/');
                        if length(checkFront3)==2
                            doi = checkFront3{2};
                        end
                        checkFront4 = strsplit(doi,'doi.org/');
                        if length(checkFront4)==2
                            doi = checkFront4{2};
                        end
                        % Construct the URL
                        doiUrl = ['https://dx.doi.org/', doi];
                        doiUrl2 = ['https://doi.org/', doi];

                        % Define the options to set the 'Accept' header for BibTeX format
                        options = weboptions('HeaderFields', {'Accept', 'text/bibliography; style=bibtex'});
                    else
                        hasbib = 1;
                    end

                    try
                        % Read the web content with the specified options
                        if length(this_bib)<3 || searchingByDOIinput == 1
                            bibtexEntry = webread(doiUrl, options);
                        else
                            bibtexEntry = this_bib;
                        end

                        % for directory file
                        bibTexString = bibtexEntry;

                        % Regular expression to capture key-value pairs
                        % This pattern looks for 'key = {value}' or 'key = value' structures
                        pattern = '\s*(?<key>\w+)\s*=\s*\{?(?<value>[^}]+)\}?';

                        % Use regexp to find all matches and return them as a structure array
                        matches = regexp(bibtexEntry, pattern, 'names');

                        pattern2 = '\s*pages\s*=\s*\{?(?<value>[^}]+)\}?';
                        matches2 = regexp(bibtexEntry, pattern2, 'names');
                        
                        temptab = struct2table(matches);
                        if length(matches2) && length(find(strcmp(temptab{:,1},'pages')))==0
                            matches(length(matches)+1).key = 'pages';
                            matches(length(matches)).value = matches2.value;
                        end

                        try bibtab = struct2table(matches);
                        catch
                        end
                    catch
                        set(lblCoreSearchStatus,'Visible','on','String','Error retrieving BibTeX entry for DOI');
                        %set(coreCiteSearchByDOIIn,'Visible','on')
                    end
                end
            catch
                set(lblCoreSearchStatus,'Visible','on','String','DOI look-up failed')
            end
            citeList = {''};
            citeList{1} = coreCiteIn.String;
            coreCiteAddIn.String = '';
            coreCiteApplyListIn.Items = citeList;
            set(lblCoreSearchStatus,'Visible','off')
        catch
            set(lblCoreSearchStatus,'Visible','on','String','Could not match core name')
        end

        set(coreCiteSearchByDOIIn,'Visible','on')
        set(lblCiteDOI,'Visible','on')
        set(lblCiteDOIEdit,'Visible','on')
        set(lblCiteTitle,'Visible','on')
        set(lblCiteTitleEdit,'Visible','on')
        set(lblCiteAuthor,'Visible','on')
        set(lblCiteAuthorEdit,'Visible','on')
        set(lblCiteJournal,'Visible','on')
        set(lblCiteJournalEdit,'Visible','on')
        set(lblCiteVolume,'Visible','on')
        set(lblCiteVolumeEdit,'Visible','on')
        set(lblCiteNumber,'Visible','on')
        set(lblCiteNumberEdit,'Visible','on')
        set(lblCitePage,'Visible','on')
        set(lblCitePageEdit,'Visible','on')
        set(lblCiteYear,'Visible','on')
        set(lblCiteYearEdit,'Visible','on')
        set(coreCiteApplyListIn,'Visible','on')
        set(lblCoreCiteAdd,'Visible','on')
        set(coreCiteAddIn,'Visible','on')
        set(coreCiteAddApplyIn,'Visible','on')
        set(lblCoreAddStatus,'Visible','on')

        if size(bibtab,1)>1
            doi_idx = find(strcmp(bibtab{:,1},'DOI'));
            if length(doi_idx)
                set(lblCiteDOIEdit,'String',bibtab{doi_idx,2})
            end
            if searchingByDOIinput == 1 || hasbib == 1
                title_idx = find(strcmp(bibtab{:,1},'title'));
                if length(title_idx)
                    set(lblCiteTitleEdit,'String',bibtab{title_idx,2})
                end
                author_idx = find(strcmp(bibtab{:,1},'author'));
                if length(author_idx)
                    set(lblCiteAuthorEdit,'String',bibtab{author_idx,2})
                end
                journal_idx = find(strcmp(bibtab{:,1},'journal'));
                if length(journal_idx)
                    set(lblCiteJournalEdit,'String',bibtab{journal_idx,2})
                end
                volume_idx = find(strcmp(bibtab{:,1},'volume'));
                if length(volume_idx)
                    set(lblCiteVolumeEdit,'String',bibtab{volume_idx,2})
                end
                number_idx = find(strcmp(bibtab{:,1},'number'));
                if length(number_idx)
                    set(lblCiteNumberEdit,'String',bibtab{number_idx,2})
                end
                page_idx = find(strcmp(bibtab{:,1},'pages'));
                if length(page_idx)
                    set(lblCitePageEdit,'String',bibtab{page_idx,2})
                end
                year_idx = find(strcmp(bibtab{:,1},'year'));
                if length(year_idx)
                    set(lblCiteYearEdit,'String',bibtab{year_idx,2})
                end
            end
        end
        set(coreCiteApplyIn,'Visible','on')
        set(makeLiPDIn2,'Visible','on')

