    function directSubmitData(src,event)

        set(UserFig,'Visible','off')
        pause(0.001)

        [datafile2send,selpathdata] = uigetfile({'*.zip;*.tiff'},'Choose 2-D image or CT scan');
        set(UserFig,'Visible','on')

        set(directSubmitDataIn,'Enable','off')
        set(directEditMetaIn,'Enable','off')
        set(directEditCiteIn,'Enable','off')
        set(makeMapIn0,'Enable','off')
        haveData = 1;
        if haveMeta == 1
            set(directSubmitGoIn,'Enable','on')
        end

    end

lblSendingDirect = [];
    function directSubmitGo(src,event)

        haveMeta = 0;
        haveData = 0;

        try

            set(directSubmitGoIn,'Enable','off')
            set(editDataCancelIn,'Enable','off')
            set(uiAbout3,'Enable','off')

            try delete(lblSendingDirect)
            catch
            end
            lblSendingDirect = uicontrol(UserFig,'Style','text','String','Sending data...','Position',figscale*[720,80,250,40],...
                'BackgroundColor','none','FontSize',textscale*12,'FontName','Arial','Units','normalized','Visible','on');

            pause(0.1)
            % read metadata
            [newmeta_num,newmeta_text,raw] = xlsread(fullfile(selpathmeta,metafile2send))

            successDirect = 0;
            for jji = 1:length(newmeta_text(:,1))-1 % only read top one

                if length(newmeta_num(jji,:)) < 14
                    directSubmitErrorMsg = sprintf('Missing numeric metadata');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_text(jji,:)) < 24
                    directSubmitErrorMsg = sprintf('Outdated metadata template');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                submittedCoreName = newmeta_text{jji+1,1};
                submittedSectionName = newmeta_text{jji+1,2};
                submittedRegionName = newmeta_text{jji+1,3};
                submittedSubregionName = newmeta_text{jji+1,4};
                submittedGenus = newmeta_text{jji+1,5};
                submittedOwner = newmeta_text{jji+1,6};
                submittedNotes = newmeta_text{jji+1,7};
                submittedIsCT = newmeta_num(jji,12);

                if length(submittedCoreName) == 0 
                    directSubmitErrorMsg = sprintf('Missing core name');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(submittedRegionName) == 0 
                    directSubmitErrorMsg = sprintf('Missing region name');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(submittedSubregionName) == 0 
                    directSubmitErrorMsg = sprintf('Missing subregion name');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(submittedGenus) == 0 
                    directSubmitErrorMsg = sprintf('Missing genus');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(submittedOwner) == 0 
                    directSubmitErrorMsg = sprintf('Missing core owner');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(submittedIsCT) == 0 
                    directSubmitErrorMsg = sprintf('Missing image toggle');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,1)) == 0 
                    directSubmitErrorMsg = sprintf('Missing hard drive column');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,2)) == 0 
                    directSubmitErrorMsg = sprintf('Missing flip-core toggle');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,3)) == 0 
                    directSubmitErrorMsg = sprintf('Missing latitude');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,4)) == 0 
                    directSubmitErrorMsg = sprintf('Missing longitude');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,5)) == 0 
                    directSubmitErrorMsg = sprintf('Missing elevation');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,7)) == 0 
                    directSubmitErrorMsg = sprintf('Missing collection year');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,9)) == 0 
                    directSubmitErrorMsg = sprintf('Missing unlocked toggle');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,10)) == 0 
                    directSubmitErrorMsg = sprintf('Missing density calibration slope');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,11)) == 0 
                    directSubmitErrorMsg = sprintf('Missing density calibration intercept');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,13)) == 0 
                    directSubmitErrorMsg = sprintf('Missing image color invert toggle');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                if length(newmeta_num(jji,14)) == 0 
                    directSubmitErrorMsg = sprintf('Missing image dpi');
                    set(lblSendingDirect,'String',directSubmitErrorMsg)
                    break
                end

                % replace spaces with underscores
                submittedRegionName(submittedRegionName==32) = 95;
                submittedSubregionName(submittedSubregionName==32) = 95;

                submittedCitation = newmeta_text{jji+1,8};
                submittedAcknowledge = newmeta_text{jji+1,9};

                if editingMetaRow == 0
                    if max(strcmp(submittedCoreName,treeDir.textdata(:,1))) == 1 && strcmp(submittedSectionName,'') && ~strcmp(submittedRegionName,'standards')
                        directSubmitErrorMsg = sprintf('Core %s name already taken',submittedCoreName);
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end

                    theseRows = find(strcmp(submittedCoreName,treeDir.textdata(:,1)));
                    if max(strcmp(submittedCoreName,treeDir.textdata(:,1))) == 1 && max(strcmp(submittedSectionName,treeDir.textdata(theseRows,2)))
                        directSubmitErrorMsg = sprintf('Core/section %s name already taken',submittedCoreName);
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end
                else
                    editingMetaRowNum = find(strcmp(submittedCoreName,treeDir.textdata(:,1)) & strcmp(submittedSectionName,treeDir.textdata(:,2)));
                    if length(editingMetaRowNum) == 0
                        directSubmitErrorMsg = sprintf('Core %s not found',submittedCoreName);
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end
                end

                % connect
                try
                    cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                catch
                    try
                        connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                        connectionEstablished = 0;
                        for ij = 1:length(connectTimes)
                            if connectionEstablished == 0
                                if connectTimes(ij) == 1
                                    waitText = [' ',num2str(connectTimes(ij)),' minute.']
                                else
                                    waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                                end
                                set(lblSendingDirect,'Units','Pixels','Visible','on',...
                                    'String',{'Error connecting to server.';strcat('Trying again in',waitText)})
                                pause(connectTimes(ij)*60)
                                try
                                    cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                                    connectionEstablished = 1;
                                    set(lblSendingDirect,'String','Sending data...')
                                catch
                                end
                            end
                        end
                        if connectionEstablished == 0
                            zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                        end
                    catch
                        set(lblSendingDirect,'Visible','on',...
                            'String',{'Error connecting to server. (code 035)';'Please try again later.'})
                        while 1==1
                            pause
                        end
                    end
                end

                if editingMetaRow == 0
                    
                else
                    % find matches
                    all_owners = strsplit(submittedOwner,'//');
                    if max(strcmp(all_owners,saveFileName)) == 0
                        directSubmitErrorMsg = 'Submitted core owner does not match username';
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end
                    if max(strcmp(treeDir.textdata(editingMetaRowNum,6),saveFileName)) == 0
                        directSubmitErrorMsg = 'You do not have permission to edit this core';
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end
                end

                if editingMetaRow == 0
                    % creating folders and placing dicoms
                    close(cache3)
                    cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                    cd(cache3,'tdecarlo19/public/hd1')
                    current_regions = dir(cache3);
                    region_list = {''};
                    for iij = 1:length(current_regions)
                        region_list{iij} = char(current_regions(iij).name);
                    end
                    if max(strcmp(submittedRegionName,region_list)) == 0
                        mkdir21(cache3,submittedRegionName)
                    end
                    cd(cache3,submittedRegionName)

                    current_subregions = dir(cache3);
                    subregion_list = {''};
                    for iij = 1:length(current_subregions)
                        subregion_list{iij} = char(current_subregions(iij).name);
                    end
                    if max(strcmp(submittedSubregionName,subregion_list)) == 0
                        mkdir21(cache3,submittedSubregionName)
                    end
                    cd(cache3,submittedSubregionName)

                    if submittedIsCT==1 && ~strcmp(datafile2send,'dicoms.zip')
                        directSubmitErrorMsg = 'Data file not named dicoms.zip';
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end

                    if submittedIsCT==0 && length(strsplit(datafile2send,'.tiff')) <= 1 %~strcmp(datafile2send,'xray.tiff')
                        directSubmitErrorMsg = 'Data file not a .tiff image';
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    end

                    current_cores = dir(cache3);
                    cores_list = {''};
                    for iij = 1:length(current_cores)
                        cores_list{iij} = char(current_cores(iij).name);
                    end
                    if max(strcmp(submittedCoreName,cores_list)) == 1 && strcmp(submittedSectionName,'')
                        directSubmitErrorMsg = sprintf('Core %s folder already exists',submittedCoreName);
                        set(lblSendingDirect,'String',directSubmitErrorMsg)
                        break
                    elseif max(strcmp(submittedCoreName,cores_list)) == 0
                        mkdir21(cache3,submittedCoreName)
                    end
                    cd(cache3,submittedCoreName)

                    % check for sections
                    if ~strcmp(submittedSectionName,'') % there are sections
                        current_sections = dir(cache3);
                        sections_list = {''};
                        for iij = 1:length(current_sections)
                            sections_list{iij} = char(current_sections(iij).name);
                        end
                        if max(strcmp(submittedSectionName,sections_list)) == 1
                            directSubmitErrorMsg = sprintf('Section %s folder already exists',submittedSectionName);
                            set(lblSendingDirect,'String',directSubmitErrorMsg)
                            break
                        else max(strcmp(submittedCoreName,cores_list))
                            mkdir21(cache3,submittedSectionName)
                        end
                        cd(cache3,submittedSectionName)

                        % place data
                        if submittedIsCT==1
                            mput(cache3,fullfile(selpathdata,'dicoms.zip'))
                        elseif submittedIsCT==0
                            mput(cache3,fullfile(selpathdata,datafile2send))
                        end

                    else % no sections, just add core
                        if submittedIsCT==1
                            mput(cache3,fullfile(selpathdata,'dicoms.zip'))
                        elseif submittedIsCT==0
                            mput(cache3,fullfile(selpathdata,datafile2send))
                        end
                    end
                end

                % don't add to directory for standards submissions

                % import master directory list into this session (so as to
                % make sure we have latest version from server)
                try mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                    treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));
                    %close(cache3);
                catch
                    cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password); % make sure we can connect to sftp server 1
                    cd(cache1,'tdecarlo19/public/TreeTrove');
                    mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                    %close(cache3);
                    treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));
                    try
                        mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                        treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));
                    catch
                    end
                end


                if ~strcmp(submittedRegionName,'standards')
                    % add to metadata
                    if editingMetaRow == 0
                        treeDir.textdata(end+1,1:10) = newmeta_text(jji+1,1:10);
                        treeDir.data(end+1,:) = newmeta_num(jji,:);
                    else
                        treeDir.textdata(editingMetaRowNum,1:10) = newmeta_text(jji+1,1:10);
                        treeDir.data(editingMetaRowNum-1,:) = newmeta_num(jji,:);
                    end

                    treeDirHold = treeDir;
                    treeDirHold.textdata = treeDirHold.textdata(2:end,:);
                    treeDirStruct = struct('name',treeDirHold.textdata(:,1),...
                        'piece',treeDirHold.textdata(:,2),...
                        'region',treeDirHold.textdata(:,3),...
                        'sub_region',treeDirHold.textdata(:,4),...
                        'genus',treeDirHold.textdata(:,5),...
                        'owner',treeDirHold.textdata(:,6),...
                        'notes',treeDirHold.textdata(:,7),...
                        'citation',treeDirHold.textdata(:,8),...
                        'acknowledgement',treeDirHold.textdata(:,9),...
                        'bibtex',treeDirHold.textdata(:,10),...
                        'hard_drive',treeDirHold.data(1,1),...
                        'flip',treeDirHold.data(1,2),...
                        'lat',treeDirHold.data(1,3),...
                        'lon',treeDirHold.data(1,4),...
                        'elevation',treeDirHold.data(1,5),...
                        'month',treeDirHold.data(1,6),...
                        'year',treeDirHold.data(1,7),...
                        'file_size',treeDirHold.data(1,8),...
                        'unlocked',treeDirHold.data(1,9),...
                        'denslope',treeDirHold.data(1,10),...
                        'denintercept',treeDirHold.data(1,11),...
                        'ct',treeDirHold.data(1,12),...
                        'imageinvert',treeDirHold.data(1,13),...
                        'dpi',treeDirHold.data(1,14));
                    for ic = 1:length(treeDirHold.data(:,1))
                        treeDirStruct(ic).hard_drive = treeDirHold.data(ic,1);
                        treeDirStruct(ic).flip = treeDirHold.data(ic,2);
                        treeDirStruct(ic).lat = treeDirHold.data(ic,3);
                        treeDirStruct(ic).lon = treeDirHold.data(ic,4);
                        treeDirStruct(ic).elevation = treeDirHold.data(ic,5);
                        treeDirStruct(ic).month = treeDirHold.data(ic,6);
                        treeDirStruct(ic).year = treeDirHold.data(ic,7);
                        treeDirStruct(ic).file_size = treeDirHold.data(ic,8);
                        treeDirStruct(ic).unlocked = treeDirHold.data(ic,9);
                        treeDirStruct(ic).denslope = treeDirHold.data(ic,10);
                        treeDirStruct(ic).denintercept = treeDirHold.data(ic,11);
                        treeDirStruct(ic).ct = treeDirHold.data(ic,12);
                        treeDirStruct(ic).imageinvert = treeDirHold.data(ic,13);
                        treeDirStruct(ic).dpi = treeDirHold.data(ic,14);
                    end
                    writetable(struct2table(treeDirStruct),fullfile(selpath,'my_trees','tree_directory_master.txt'),'Delimiter','\t')
                    close(cache3)
                    cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                    cd(cache3,'tdecarlo19/public/TreeTrove')
                    mput(cache3,fullfile(selpath,'my_trees','tree_directory_master.txt'))
                    % load new version into this session:
                    treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));

                    % add to citation list
                    % import master citation list into this session
                    % try mget22(cache3,'tree_directory_citations.txt',fullfile(selpath,'my_trees'));
                    %     citationDir = importdata(fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     %close(cache3);
                    % catch
                    %     cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password); % make sure we can connect to sftp server 1
                    %     cd(cache3,'/TreeTrove');
                    %     mget22(cache3,'tree_directory_citations.txt',fullfile(selpath,'my_trees'));
                    %     %close(cache3);
                    %     citationDir = importdata(fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     try
                    %         mget22(cache1,'tree_directory_citations.txt',fullfile(selpath,'my_trees'));
                    %         citationDir = importdata(fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     catch
                    %     end
                    % end

                    % if editingMetaRow == 0
                    %     citationDir.textdata(end+1,1:2) = newmeta_text(jji+1,1:2);
                    %     citationDir.textdata(end,3:4) = newmeta_text(jji+1,8:9);
                    %     citationDir.data(end+1,1) = 1;
                    % else
                    %     citationDir.textdata(editingMetaRowNum,1:2) = newmeta_text(jji+1,1:2);
                    %     citationDir.textdata(editingMetaRowNum,3:4) = newmeta_text(jji+1,8:9);
                    % end
                    % 
                    % citationDirHold = citationDir;
                    % citationDirHold.textdata = citationDirHold.textdata(2:end,:);
                    % citationDirStruct = struct('name',citationDirHold.textdata(:,1),...
                    %     'piece',citationDirHold.textdata(:,2),...
                    %     'citation',citationDirHold.textdata(:,3),...
                    %     'acknowledgement',citationDirHold.textdata(:,4));
                    % for ic = 1:length(citationDirHold.data(:,1))
                    %     citationDirStruct(ic).num = citationDirHold.data(ic,1);
                    % end
                    % writetable(struct2table(citationDirStruct),fullfile(selpath,'my_trees','tree_directory_citations.txt'),'Delimiter','\t')
                    % try mput(cache3,fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     close(cache3);
                    % catch
                    %     cache3 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password); % make sure we can connect to sftp server 1
                    %     cd(cache3,'/TreeTrove');
                    %     mput(cache3,fullfile(selpath,'my_trees','tree_directory_citations.txt'));close(cache3);
                    %     citationDir = importdata(fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     try
                    %         mput(cache1,fullfile(selpath,'my_trees','tree_directory_citations.txt'));
                    %     catch
                    %     end
                    % end
                end
                successDirect = 1;
                if editingMetaRow == 0
                    break % can only do one at a time if submitting data
                end
            end

            set(editDataCancelIn,'Enable','on')
            set(directSubmitGoIn,'Enable','off')
            set(directSubmitMetaIn,'Enable','on')
            set(directSubmitDataIn,'Enable','on')
            set(directEditMetaIn,'Enable','on')
            set(directEditCiteIn,'Enable','on')
            set(makeMapIn0,'Enable','on')
            haveMeta = 0;
            haveData = 0;
            if successDirect == 1
                set(lblSendingDirect,'Visible','off')
            end
            set(uiAbout3,'Enable','on')
        catch
            set(lblSendingDirect,'String','Unknown error, try again')
            set(editDataCancelIn,'Enable','on')
        end

        editingMetaRow = 0;
    end


