            catch
            end
            delete(fullfile(refPath,strcat('new_submission_attempt_',submission_text,'.csv')));
        catch
        end

        thisWorked = 0;
        if noDuplicate == 1
            try mput(cache1,fullfile(selpath3,file2send));
