                    try loadXray
                    catch
                        set(lblOpeningError,'Visible','on','String','Error in image dataset (code 008)')
                        pause
                        while 1 ~= 2
                            pause
                        end
                    end
                end
            end

            % Choose core filter, which is based on the genus
            chooseCoreFilter

            % turn off loading bar once all image data in Matlab
            set(ha3,'Visible','off')
            delete(p1)
            delete(ha3)
            if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
                delete(dispVid)
                delete(lblVideo)
            end

            % launch the main GUI for interacting with the scan
            areDataUnlocked = 1;
            core_run
        else
            resetAxes
            mainMenu
        end
    end

