% Function to interpret user's core selection
    function chosenCore(src,event)

        % if file size already displayed, delete it
        set(fileSizePreview,'Visible','off')
        set(downloadTimePreview,'Visible','off')
        set(downloadDataIn,'Visible','off')
        set(view3DRingsIn,'Visible','off')
        set(previewIn,'Visible','off') % allow user to preview core
        set(htextRings,'Visible','off')
        set(htextNoRings,'Visible','off')
        set(ringsMapsIn,'Visible','off')
        try set(sectionIn,'Visible','off')
            set(htextSection,'Visible','off')
        catch
        end

        sectionName = ''; % default

        % If a core is already selected, delete its plot from the map
        if length(treeName)>0
            delete(pCore);
        end

        if dataMode == 0
            treeNum = coreIn.Value; % user's input (number in dropdown list)
            treeName = currentCores(treeNum); % text of user's selection
            treeName = treeName{1}; % convert to string format
        elseif dataMode == 1 && coreIn.Value > 1
            treeNum = coreIn.Value; % user's input (number in dropdown list)
            treeName = currentCores(treeNum-1); % text of user's selection
            treeName = treeName{1}; % convert to string format
        elseif dataMode == 1
            treeName = 'Download all';
            sectionName = ''; % default
            set(downloadDataIn,'Visible','on')
            downloadAllCoresToggle = 1;
            % else
            %     set(downloadDataIn,'Visible','on')
            %     downloadAllCoresToggle = 1;
        end

        % search for sections within this core (first column of directory)
        theseSections = find(strcmp(treeDir.textdata(2:end,1),treeName));

        % Determine whether there are multiple sections or not
        if length(theseSections) == 1 % not multiple sections
            % Save to 'FileOpen' the location on local drive where data
            % will be stored once downloaded from server:
            ct = treeDir.data(theseSections,12);
            if saveCTdata == 1 && dataMode == 0% && dataMode == 0
                if ct == 1
                    fileOpen = fullfile(selpath,'my_trees',treeName,'dicoms');
                else
                    fileOpen = fullfile(selpath,'my_trees',treeName,'image');
                end
            elseif dataMode >= 0
                if dataMode == 0
                    if ct == 1
                        fileOpen = fullfile(selpath,'my_trees','current_image','dicoms');
                    else
                        fileOpen = fullfile(selpath,'my_trees','current_image','image');
                    end
                elseif dataMode == 1
                    if ct == 1
                        fileOpen = fullfile(selpath,'my_trees','current_image_view_only','dicoms');
                    else
                        fileOpen = fullfile(selpath,'my_trees','current_image_view_only','image');
                    end
                end
            end
            set(previewIn,'String',{'Preview Core'})
            set(previewIn,'Visible','on') % allow user to preview core
            preview_failed = 0;

            areDataUnlocked = -treeDir.data(theseSections,9)+2;
            dataOwner = treeDir.textdata(theseSections+1,6);
            dataOwners = {''};
            for jjj = 1:length(dataOwner)
                dataOwners(jjj,1:length(strsplit(dataOwner{jjj},'//'))) = strsplit(dataOwner{jjj},'//');
            end
            if any(strcmp(saveFileName,dataOwners),2)
                areDataUnlocked = 1; % master user identified
            end
            if areDataUnlocked < 0
                saveDataIn.Value = 1;
                saveCTdata = 0;
            end

            if dataMode == 1
                if coreIn.Value ~= 1
                    dirOut = findRingFiles(treeName,sectionName);
                    if length(dirOut) > 0 && areDataUnlocked == 1
                        ringsMapsIn.Value = 1;
                        ringsMapsIn.String = [{'Download all'};dirOut'];
                        set(ringsMapsIn,'Visible','on')
                        set(htextRings,'Visible','on')
                        set(htextNoRings,'Visible','off')
                        set(htextRingsLocked,'Visible','off')
                    elseif length(dirOut) > 0 && areDataUnlocked ~= 1
                        set(ringsMapsIn,'Visible','off')
                        set(htextRings,'Visible','off')
                        set(htextNoRings,'Visible','off')
                        set(htextRingsLocked,'Visible','on')
                    else
                        set(ringsMapsIn,'Visible','off')
                        set(htextNoRings,'Visible','on')
                        set(htextRings,'Visible','on')
                        set(htextRingsLocked,'Visible','off')
                    end
                end
            else
                if treeDir.data(theseSections,12) == 1
                    set(startIn,'Visible','on','String','Open CT scan') % allow user to press "Go"
                else
                    set(startIn,'Visible','on','String','Open 2D image') % allow user to press "Go"
                end
                if (areDataUnlocked==0||areDataUnlocked==2)
                    set(htextLocked,'Visible','on','String','output data are blocked for this core');
                elseif (areDataUnlocked==-1||areDataUnlocked==3)
                    set(htextLocked,'Visible','on','String',{'output data and raw images are blocked for this core'});
                end
                set(checkSpeedIn,'Visible','on')
                thisFileSize = treeDir.data(theseSections,8);
                thisFileSizeText = sprintf('File Size: %i MB', thisFileSize);
                set(fileSizePreview,'String',thisFileSizeText)
                set(fileSizePreview,'Visible','on')
                %preview_printed = 1;
            end

        elseif length(theseSections) > 1 % multiple sections exist
            % Get unique list of sections
            
            currentSections = unique(treeDir.textdata(theseSections+1,2));

            if dataMode == 1

                % Create drop-down menu to select section
                sectionIn = uicontrol(UserFig,'Style','popupmenu',...
                    'Position',figscale*[720,320,250,30],'Units','normalized',...
                    'String',['Download all';currentSections],...
                    'Callback',@chosenSection);
                sectionMenuExists = 1;
            else
                % Create drop-down menu to select section
                sectionIn = uicontrol(UserFig,'Style','popupmenu',...
                    'Position',figscale*[720,320,250,30],'Units','normalized',...
                    'String',currentSections,...
                    'Callback',@chosenSection);
                sectionMenuExists = 1;
            end
            set(htextSection,'Visible','on')
            set(startIn,'Visible','off')
            set(htextLocked,'Visible','off')
            set(checkSpeedIn,'Visible','off')
        end

        choosingCore = 1;
        updateMap
        choosingCore = 0;

    end

    function downloadAllCoresDataInRegion

        treeNameHold = treeName;
        sectionNameHold = sectionName;

        for ii = 1:length(currentCores)
            theseSections = find(strcmp(treeDir.textdata(2:end,1),currentCores{ii}));
            for jj = 1:length(theseSections)
                dataOwner = treeDir.textdata(theseSections+1,6);
                dataOwners = {''};
                for jjj = 1:length(dataOwner)
                    dataOwners(jjj,1:length(strsplit(dataOwner{jjj},'//'))) = strsplit(dataOwner{jjj},'//');
                end
                if treeDir.data(theseSections(jj),9) == 1 || any(strcmp(saveFileName,dataOwners),2) 
                    treeName = treeDir.textdata{theseSections(jj)+1,1};
                    sectionName = treeDir.textdata{theseSections(jj)+1,2};
                    dirOut = findRingFiles(treeName,sectionName);
                    for kk = 1:length(dirOut)
                        getRingFile(treeName,sectionName,dirOut{kk})
                    end
                end
            end
        end

        treeName = treeNameHold;
        sectionName = sectionNameHold;
        set(downloadDataIn,'Visible','off')

    end

    function downloadAllSectionsDataInCore

        sectionNameHold = sectionName;

        theseSections = find(strcmp(treeDir.textdata(2:end,1),treeName));
        for jj = 1:length(theseSections)
            sectionName = treeDir.textdata{theseSections(jj)+1,2};
            dirOut = findRingFiles(treeName,sectionName);
            for kk = 1:length(dirOut)
                getRingFile(treeName,sectionName,dirOut{kk})
            end
        end

        sectionName = sectionNameHold;

    end

    function downloadAllDataInACore

        dirOut = findRingFiles(treeName,sectionName);
        for kk = 1:length(dirOut)
            getRingFile(treeName,sectionName,dirOut{kk})
        end

    end

speedCheck = 1; % to estimate download time
thisFileSize = 1;
speedCheck_printed = 0;
checkSpeedIn = uicontrol(UserFig,'Style','pushbutton',...
    'Position',figscale*[860,20,160,35],'Units','normalized',...
    'String','Check download speed','Visible','off',...
    'Callback',@checkSpeed);

% Function to test download speed
    function checkSpeed(src,event)

        set(downloadTimePreview,'Visible','off')
        lblCheckSpeed = uicontrol(UserFig,'Style','text','String','Checking connection speed...','Position',figscale*[860,15,180,40],...
            'BackgroundColor',themeColor2,'FontSize',textscale*10,'FontName','Arial','Units','normalized');

        pause(0.01)

        h_drive = 'tdecarlo19/public/hd1/';

        thisTreeName = 'F53B';
        test_row = find(strcmp(treeDir.textdata(:,1),thisTreeName));

        try cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password) %
        catch
            set(lblFTPerror,'Visible','on')
        end
        tic
        server_path = strcat(h_drive,'/',treeDir.textdata{test_row,3},'/',...
            treeDir.textdata{test_row,4},'/',thisTreeName);

        server_path(double(server_path)==32) = 95;

        cd(cache2,server_path)

        mget22(cache2,'dicoms.zip',fullfile(selpath,'my_trees','current_image'));
        close(cache2)
        download_time = toc;
        speedCheck = 30/download_time;

        thisDownloadTimeText = sprintf('Estimated download time: %i seconds', round((thisFileSize/speedCheck)*1.05));
        set(downloadTimePreview,'String',thisDownloadTimeText)
        set(downloadTimePreview,'Visible','on')
        set(lblCheckSpeed,'Visible','off')

        %speedCheck_printed = 1;

    end

