% Function to interpret user's choice of section
    function chosenSection(src,event)

        if dataMode == 0
            sectionNum = sectionIn.Value; % user's input (number in dropdown list)
            sectionName = currentSections(sectionNum); % store as text
            sectionName = sectionName{1}; % convert to string
        elseif dataMode == 1 && sectionIn.Value > 1
            sectionNum = sectionIn.Value; % user's input (number in dropdown list)
            sectionName = currentSections(sectionNum-1); % store as text
            sectionName = sectionName{1}; % convert to string
        else
            set(downloadDataIn,'Visible','on')
            downloadAllSectionsToggle = 1;
        end

        % Save to 'FileOpen' the location on local drive where data
        % will be stored once downloaded from server:

        thisSection = find(strcmp(treeDir.textdata(2:end,1),treeName)...
            & strcmp(treeDir.textdata(2:end,2),sectionName));

        ct = treeDir.data(thisSection,12);
        if saveCTdata == 1 && dataMode == 0
            if ct == 1
                fileOpen = fullfile(selpath,'my_trees',treeName,sectionName,'dicoms');
            else
                fileOpen = fullfile(selpath,'my_trees',treeName,sectionName,'image');
            end
        elseif dataMode >= 0
            if dataMode == 0
                if ct == 1
                    fileOpen = fullfile(selpath,'my_trees','current_image','dicoms');
                else
                    fileOpen = fullfile(selpath,'my_trees','current_image','image');
                end
            elseif dataMode == 1
                if ct == 1
                    fileOpen = fullfile(selpath,'my_trees','current_image_view_only','dicoms');
                else
                    fileOpen = fullfile(selpath,'my_trees','current_image_view_only','image');
                end
            end
        end

        set(previewIn,'String',{'Preview Core'})
        set(previewIn,'Visible','on') % allow user to preview core
        preview_failed = 0;

        areDataUnlocked = -treeDir.data(thisSection,9)+2;
        dataOwner = treeDir.textdata(thisSection+1,6);
            dataOwners = {''};
            for jjj = 1:length(dataOwner)
                dataOwners(jjj,1:length(strsplit(dataOwner{jjj},'//'))) = strsplit(dataOwner{jjj},'//');
            end
        if any(strcmp(saveFileName,dataOwners),2)
            areDataUnlocked = 1; % master user identified
        end
        if areDataUnlocked < 0
            saveDataIn.Value = 1;
            saveCTdata = 0;
        end

        if dataMode == 1
            if downloadAllSectionsToggle == 1
                tempDirRow = find(strcmp(treeDir.textdata(2:end,1),treeName));
                areDataUnlocked = -treeDir.data(tempDirRow(1),9)+2;
            end
            if coreIn.Value ~= 1
                dirOut = findRingFiles(treeName,sectionName);
                if length(dirOut) > 0 && areDataUnlocked == 1
                    ringsMapsIn.Value = 1;
                    ringsMapsIn.String = [{'Download all'};dirOut'];
                    set(ringsMapsIn,'Visible','on')
                    set(htextRings,'Visible','on')
                    set(htextNoRings,'Visible','off')
                    set(htextRingsLocked,'Visible','off')
                elseif length(dirOut) > 0 && (areDataUnlocked==0||areDataUnlocked==2)
                    set(ringsMapsIn,'Visible','off')
                    set(htextRings,'Visible','off')
                    set(htextNoRings,'Visible','off')
                    set(htextRingsLocked,'Visible','on')
                elseif downloadAllSectionsToggle == 1 && areDataUnlocked == 1
                    set(ringsMapsIn,'Visible','off')
                    set(htextNoRings,'Visible','off')
                    set(htextRings,'Visible','off')
                    set(downloadDataIn,'Visible','on')
                else
                    set(ringsMapsIn,'Visible','off')
                    set(htextNoRings,'Visible','on')
                    set(htextRings,'Visible','off')
                    set(htextRingsLocked,'Visible','off')
                end
            end
        else
            if treeDir.data(thisSection,12) == 1
                set(startIn,'Visible','on','String','Open CT scan') % allow user to press "Go"
            else
                set(startIn,'Visible','on','String','Open 2D image') % allow user to press "Go"
            end
            if (areDataUnlocked==0||areDataUnlocked==2)
                set(htextLocked,'Visible','on','String','output data are blocked for this core');
            elseif (areDataUnlocked==-1||areDataUnlocked==3)
                set(htextLocked,'Visible','on','String',{'output data and raw images are blocked for this core'});
            end
            set(checkSpeedIn,'Visible','on')
            thisFileSize = treeDir.data(thisSection,8);
            thisFileSizeText = sprintf('File Size: %i MB', thisFileSize);
