areWeGoingBack = 0;
Rotate2dIn = [];

% Function for interacting with scans:
    function core_run

        % try delete(lblMapClick)
        % catch
        % end
        set(UserFig,'Color','k')

        areWeEditing = 0; % toggle for whether an existing file for this core was found
        startingRotation = 0; % can use this to define initial rotation, just 0 for now...
        x_ang = 0; % this stores the rotation angle of the scan
        totRings = 0; % this stores total number of defined rings
        xIntersect = [];
        yIntersect = [];
        

        % check if we find an existing, work-in-progress file for this core
        if strcmp(sectionName,'')
            name2search = strcat(saveName,treeName);
        else
            name2search = strcat(saveName,treeName,'_',sectionName);
        end
        if exist(fullfile(fileOpen,strcat(name2search,'.mat')),'file')
            if areWeGoingBack == 0
                load(fullfile(fileOpen,strcat(name2search,'.mat')),'userRings','x_ang','contra','proj','thick')
                try load(fullfile(fileOpen,strcat(name2search,'.mat')),'h3_width','h3_std','h3_defined','line_segments','ringMarks1D','missingRings','detectMode','ringMarks1D2','userRings2','treeROI','inputTopYear','breaksRings','skipsRings')
                    if size(line_segments,1)>1
                        interp_segments = [interp1(1:length(line_segments(:,1)),line_segments(:,1),linspace(1,length(line_segments(:,1)),length(line_segments(:,1))*1e4))',...
                            interp1(1:length(line_segments(:,2)),line_segments(:,2),linspace(1,length(line_segments(:,2)),length(line_segments(:,2))*1e4))'];
                    end
                catch
                end
            end
            areWeEditing = 1;
            if ct == 1
                totRings = length(find(max(max(userRings)))>0);
            else
                totRings = length(find(max(userRings))>0);
            end
            updatebreaksNumbering
            % rotate rings to match the core data
            if ct == 1
                if abs(x_ang)>0 && totRings>0 && areWeGoingBack == 0
                    hold_rings = zeros(length(userRings(:,1,1)),length(userRings(1,:,1)),totRings+1);
                    hold_rings(:,:,2:end) = userRings(:,:,1:totRings);
                    hold_rings = imrotate3(hold_rings,-x_ang,[0,0,1],'nearest','crop','FillValues',0);
                    userRings(:,:,1:totRings) = hold_rings(:,:,2:end);
                    hold_rings = [];
                    x_ang = 0;
                elseif abs(x_ang)>0 && totRings>0 && areWeGoingBack == 1
                    x_ang_old = x_ang;
                    % update 'x_ang_new' back to zero
                    x_ang_new = 0;
                    % calculate difference between previous and new rotation
                    x_ang_dif = x_ang_new-x_ang_old;
                    % rotate 'X' (the CT scan data)
                    X = imrotate3(X,x_ang_dif,[0,0,1],'linear','crop','FillValues',-1000);
                    % rotate userRings
                    userRings = imrotate3(userRings,x_ang_dif,[0,0,1],'nearest','crop','FillValues',0);

                end
            % elseif abs(x_ang)>0 && totRings>0 && areWeGoingBack == 0 % X-ray and rotated
            %     [ur,uc] = find(userRings);
            %     userRings0 = zeros(size(slabDraw(:,:,1)));
            %     if length(uc)>0
            %         for jk = 1:length(uc)
            %             userRings0(userRings(ur(jk),uc(jk)),ur(jk)) = uc(jk);
            %         end
            %     end
            %     userRings0 = imrotate(userRings0,x_ang,'nearest','loose');
            % 
            %     userRings = zeros(size(slabDraw,2),200);
            %     [ur,uc] = find(userRings0);
            %     if length(uc)>0
            %         for jk = 1:length(uc)
            %             userRings(uc(jk),userRings0(ur(jk),uc(jk))) = ur(jk);
            %         end
            %     end
            %     x_ang = 0;
            %     clearvars userRings0
            elseif abs(x_ang)>0 && areWeGoingBack == 0 % X-ray and rotated
                % so we rotate slab to where it was left off
                slabDraw = imrotate(slabDraw,-x_ang,'nearest','loose');
                keep_cols = max(max(slabDraw,[],3),[],1)~=0;
                keep_rows = max(max(slabDraw,[],3),[],2)~=0;
                slabDraw = slabDraw(keep_rows,keep_cols,:);
                % update image size
                col = size(slabDraw,2);
                row = size(slabDraw,2);
                layers = size(slabDraw,1);
                x_ang_new = x_ang;
                %set(Rotate2dIn,'Value',x_ang)
                %set(lblRot2d,'String',strcat(num2str(round(Rotate2dIn.Value)),' °'))
            end
        end

        % loaded everything, can now delete image data for view only
        if exist(fullfile(selpath,'my_trees','current_image_view_only'),'dir')
            rmdir(fullfile(selpath,'my_trees','current_image_view_only'),'s')
        end
        if exist(fullfile(selpath,'my_trees','current_image_view_only'),'dir')
            rmdir(fullfile(selpath,'my_trees','current_image_view_only'),'s')
        end

        % if unlocked set to -1, delete image data
        if (areDataUnlocked==-1||areDataUnlocked==3)
            if exist(fullfile(selpath,'my_trees','current_image','image'),'dir')
                rmdir(fullfile(selpath,'my_trees','current_image','image'),'s')
                mkdir(fullfile(selpath,'my_trees','current_image','image'))
                img_name = dir([fullfile(selpath,'my_trees','current_image'),filesep,'*.tiff']);
                delete(fullfile(selpath,'my_trees','current_image',img_name(1).name))
            end
            if exist(fullfile(selpath,'my_trees','current_image','dicoms'),'dir')
                rmdir(fullfile(selpath,'my_trees','current_image','dicoms'),'s')
                mkdir(fullfile(selpath,'my_trees','current_image','dicoms'))
                delete(fullfile(selpath,'my_trees','current_image','dicoms.zip'))
            end
        end

        % initial setup before GUI
        j = 0; % counter for which ring we're working on
        maxRings = 1e3; % initialized size of storage matrix, can adjust if needed

        % If we aren't editing an existing file, initialize userRings to
        % store 3-D map of user's identified ring locations
        if areWeEditing == 0
            if ct == 1
                userRings = zeros(row,col,maxRings); % matrix for storing rings
                userRings2 = zeros(row,col,maxRings); % matrix for storing bottom of rings
            else
                userRings = zeros(col,maxRings); % matrix for storing rings
                userRings2 = zeros(col,maxRings); % matrix for storing bottom of rings
            end
        end
        haveLims = 0; % toggle for whether user has zoomed in on image
        [rowMesh ,colMesh] = meshgrid(1:row,1:col); % mesh for interpolating

        % Initialize some variables
        ldbDraw = zeros(layers,row);
        if areWeEditing == 0
            thick_mm = 3;
            thick = round(thick_mm/2/hpxS);
            if ct
                contra = [300 2300];
            else
                contra = [0,1];
            end
            proj = 'mean';
        else
            try thick_mm = thick*2*hpxS;
            catch
                thick_mm = 3;
                thick = round(thick_mm/2/hpxS);
                if ct
                    contra = [300 2300];
                else
                    contra = [0,1];
                end
                proj = 'mean';
            end
        end
        x_ang_new = 0;
        circle_j = j;
        if ct == 1
            temp_rings = zeros(row,col);
            temp_rings_idx = zeros(row,col);
        else
            temp_rings = zeros(1,size(userRings,1)); 
            temp_rings_idx = zeros(1,size(userRings,1));
        end
        newRot = 0;
        if ct ~= 1
            thick_mm = 5;
        end

        if ct == 1
            % Find approximate location of core within the scan:

            % sample of core, just halfway down the scan
            samp = round(layers/2);

            % filter image to smooth pore spaces
            filteredXcore(:,:) = imfilter(X(:,:,samp), h2, 'replicate');

            % convert to binary image
            treeSamp = imbinarize((filteredXcore-min(min(filteredXcore)))/max(max(filteredXcore-min(min(filteredXcore)))).*255);

            % find locations of tree (value of 1 in binary)
            [r,c] = find(treeSamp); % r and c are rows and columns of tree pixels

            % determind outer bounds of core:
            [val,loc] = max(r);
            topMost = [c(loc),r(loc)];
            [val,loc] = min(r);
            bottomMost = [c(loc),r(loc)];
            [val,loc] = max(c);
            rightMost = [c(loc),r(loc)];
            [val,loc] = min(c);
            leftMost = [c(loc),r(loc)];

            % midpoint of the core in the scan
            center = [round((rightMost(1)+leftMost(1))/2),round((topMost(2)+bottomMost(2))/2)];

            % our starting point for a slice (i.e. slab) is just this middle
            % location
            slab = round(mean(center));

            % convert from pixels to distance using hpxS variable (which is
            % horizontal pixel spacing)
            slabPos = slab*hpxS;

        end

        % set up GUI

        % Initialize these labels:
        if any((j+1)==missingRings)
            while any((j+1)==missingRings)
                j = j+1;
            end
        end
        if yrTog == 0
            textClick = sprintf('Next ring will be ring %s',num2str(round(j+1)));
        else
            updatebreaksNumbering
            textClick = sprintf('Next ring will be top of %s',num2str(inputTopYear-round(j+1)+1+breaksRingsCumSum(j+1)));
        end

        switchRingTypeIn = uicontrol(UserFig,'Style','pushbutton','String',{'Switch ring type'},'Visible','off','FontSize',textscale*10,...
            'Position',figscale*[950,650,150,25],'Units','normalized','BackgroundColor',butCols(96,:),'FontName','Arial','Callback', @switchRings_Callback);
        lblClick = uicontrol(UserFig,'Style','text','String',textClick,'Position',figscale*[50,650,320,25],...
            'BackgroundColor','none','FontSize',textscale*14,'FontName','Arial','Units','normalized',...
            'ForegroundColor',themeColor1);
        lblClick2 = uicontrol(UserFig,'Style','text','String',textClick2,'Position',figscale*[550,650,375,25],...
            'BackgroundColor','none','FontSize',textscale*14,'FontName','Arial','Units','normalized',...
            'ForegroundColor',themeColor1,'Visible','off');
        if strcmp(detectMode,'seasonal')
            if ringType == 2
                textClick2 = 'Currently working on top of early-wood rings';
                set(lblClick2,'String',textClick2,'Visible','on','ForegroundColor','c')
            elseif ringType == 1
                textClick2 = 'Currently working on top of late-wood rings';
                set(lblClick2,'String',textClick2,'Visible','on','ForegroundColor','y')
            end
            set(switchRingTypeIn,'Visible','on')
        end

        function switchRings_Callback(source,eventdata)
            if ringType == 1
                ringType = 2; % set to top of early wood
                textClick2 = 'Currently working on top of early-wood rings';
                set(lblClick2,'String',textClick2,'Visible','on','ForegroundColor','c')
            elseif ringType == 2
                ringType = 1; % set to main rings
                textClick2 = 'Currently working on top of late-wood rings';
                set(lblClick2,'String',textClick2,'Visible','on','ForegroundColor','y')
            end
        end
        
        lblCheck = uicontrol(UserFig,'Style','text','String','Return to ring 1? Click above','Position',figscale*[250,680,500,25],'FontSize',textscale*18,'FontName','Arial','Units','normalized');
        set(lblCheck,'Visible','off')
        lblLoading = uicontrol(UserFig,'Style','text','String','LOADING..','BackgroundColor','none',...
            'Position',figscale*[350,655,300,35],'FontSize',textscale*18,'FontName','Arial','Units','normalized',...
            'ForegroundColor','w');
        set(lblLoading,'Visible','off')

        % Function for response to user's image brightness selection
        function brightness_Callback(source,eventdata)
            functionsOff
            currentC = get(ha,'CLim'); % get current contrast
            currentRange = max(currentC)-min(currentC); % current color range

            % the next two lines adjust the overall image color range based
            % on the new selection for brightness, such that the brightness
            % selection is the middle of the displayed color range
            contra(1) = -brightnessIn.Value-currentRange/2; % apply lower bound of contrast
            contra(2) = -brightnessIn.Value+currentRange/2; % apply upper bound of contrast

            set(ha,'CLim',contra); % set image color range
            if ct == 1
                set(ha2,'CLim',contra); % set image color range
            end
            set(lblBright,'String',strcat(num2str(round(-brightnessIn.Value)),' HU'))
            %delete(lblBright); % delete existing brightness label

            % Create new brightness label:
            % textBright = sprintf('%s HU',num2str(round(-brightnessIn.Value))); % CAN BE DELETED?
            %lblBright = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(-brightnessIn.Value)),' HU'),...
            %    'Position',figscale*[850,590,83,25],'Units','normalized','BackgroundColor',themeColor1,'FontSize',textscale*14,'FontName','Arial');
            functionsOn
        end

        % Create slider bar for adjusting image brightness
        %otsu_thresh = otsuthresh(filteredXcore(:)-min(filteredXcore(:)));
        %best_thresh = min(filteredXcore(:))-otsu_thresh*range(filteredXcore(:));
        %brightnessIn = uicontrol(UserFig,'Style','slider',...
        %    'Position',figscale*[725,560,265,25],'Units','normalized',...
        %    'Min', -2000,'Max', 1500,'Value', -median(contra),'Callback', @brightness_Callback);
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            if ct
                brightnessIn = uislider(UserFig,'Position',figscale*[725,585,265,25],...
                    'Limits',[-2000, 1500],'Value', -median(contra),...
                    'FontColor',themeColor1,'MajorTicks',[],'MinorTicks',[],...
                    'ValueChangedFcn', @brightness_Callback);
            else
                brightnessIn = uislider(UserFig,'Position',figscale*[725,585,265,25],...
                    'Limits',[-1 0],'Value', -median(contra),'Visible','off',...
                    'FontColor',themeColor1,'MajorTicks',[],'MinorTicks',[],...
                    'ValueChangedFcn', @brightness_Callback);
            end
        else
            brightnessIn = uicontrol(UserFig,'Style','slider',...
                'Position',figscale*[725,565,265,25],'Units','normalized',...
                'Min', -2000,'Max', 1500,'Value', -median(contra),'Callback', @brightness_Callback);
        end

        % rotating for 2-d images
        if ct == 0
            Rotate2dIn = uislider(UserFig,'Position',figscale*[725,585,265,25],...
                'Limits',[-30, 30],'Value', 0,'Visible','off',...
                'FontColor',themeColor1,'MajorTicks',-30:10:30,'MinorTicks',-30:30,...
                'ValueChangedFcn', @rotate2d_Callback);
            if abs(x_ang)>0
                set(Rotate2dIn,'Value',x_ang);
            end
        end

        % Label for current rotation setting
        if ct == 0
            lblRot2d = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(Rotate2dIn.Value)),' °'),...
                'Position',figscale*[850,595,83,23],'Units','normalized','ForegroundColor',themeColor1,...
                'BackGroundColor','none','FontSize',textscale*12,'FontName','Arial','Visible','off');

            textRot2d = uicontrol(UserFig,'Style','text','String','Rotation:','Visible','off',...
                'Position',figscale*[725,596,120,23],'ForegroundColor',themeColor1,...
                'BackGroundColor','none','Units','normalized','FontSize',textscale*12,'FontName','Arial');
        end

        % Label for current brightness setting
        lblBright = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(-brightnessIn.Value)),' HU'),...
            'Position',figscale*[850,595,83,23],'Units','normalized','ForegroundColor',themeColor1,...
            'BackGroundColor','none','FontSize',textscale*12,'FontName','Arial','Visible','off');

        % Function for response to user's image contrast selection
        function contrast_Callback(source,eventdata)
            functionsOff
            currentC = get(ha,'CLim'); % get current contrast
            currentMean = mean(currentC); % middle of contrast range

            % next two lines set the upper and lower bounds for the
            % contrast based on mid-point of existing contrast (i.e. the
            % brightness) and the user's selection of contrast:
            contra(1) = currentMean+contrastIn.Value/2;
            contra(2) = currentMean-contrastIn.Value/2;

            set(ha,'CLim',contra);  % set image color range
            if ct == 1
                set(ha2,'CLim',contra);  % set image color range
            end
            set(lblContrast,'String',strcat(num2str(round(-contrastIn.Value)),' HU'))
            functionsOn
        end

        % Create slider bar for adjusting image contrast
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            if ct
            contrastIn = uislider(UserFig,'Position',figscale*[725,535,265,25],...
                'Limits',[-3000, -10],'Value', -range(contra),...
                'FontColor',themeColor1,'MajorTicks',[],'MinorTicks',[],...
                'ValueChangedFcn', @contrast_Callback);
            else
                contrastIn = uislider(UserFig,'Position',figscale*[725,535,265,25],...
                'Limits',[-1, 0],'Value', 0,'Visible','off',...
                'FontColor',themeColor1,'MajorTicks',[],'MinorTicks',[],...
                'ValueChangedFcn', @contrast_Callback);
            end
        else
            contrastIn = uicontrol(UserFig,'Style','slider',...
                'Position',figscale*[725,515,265,25],'Units','normalized',...
                'Min', -3000,'Max', -10,'Value', -range(contra),'Callback', @contrast_Callback);
        end


        % Label for current contrast setting
        lblContrast = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(-contrastIn.Value)),' HU'),...
            'Position',figscale*[850,545,83,23],'Units','normalized','ForegroundColor',themeColor1,...
            'BackGroundColor','none','FontSize',textscale*12,'FontName','Arial','Visible','off');

        % Function for response to user's image contrast selection
        function thickness_Callback(source,eventdata)
            functionsOff
            % 'thick' stores pixels into and out of screen to incorporate
            % into image display, simply update this below. The value of
            % 'hpxS' converts horizontal distance to pixels, so the user
            % selects distance (mm) and 'thick' stores this as pixels
            set(lblThick,'String',strcat(num2str(round(thickIn.Value*10)/10),' mm'))
            thick = round(thickIn.Value/2/hpxS)-1; % in pixels

            if areWeSettingDefaults == 0
                if smoothedRingsDrawn == 0
                    drawAndLabelRings
                else
                    drawAndLabelSmoothedRings
                end
            end
            functionsOn
        end

        % Create slider bar for adjusting slice thickness
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            if thick_mm<1
                thick_mm = 1;
            end
            thickIn = uislider(UserFig,'Position',figscale*[725,473,265,25],...
                'Limits',[1 10],'Value', thick_mm,...
                'FontColor',themeColor1,'MajorTicks',1:10,'MinorTicks',[],...
                'ValueChangedFcn', @thickness_Callback);
        else
            thickIn = uicontrol(UserFig,'Style','slider',...
                'Position',figscale*[725,453,265,25],'Units','normalized',...
                'Min', 1,'Max', 10,'Value', thick_mm,'Callback', @thickness_Callback);
        end

        % Label for current thickness setting
        lblThick = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(thickIn.Value*10)/10),' mm'),...
            'Position',figscale*[850,484,83,23],'Units','normalized','ForegroundColor',themeColor1,...
            'BackGroundColor','none','FontSize',textscale*12,'FontName','Arial');

        % Function for response to user's image position selection
        function position_Callback(source,eventdata)
            functionsOff
            % 'slab' stores the pixel at the center of the displayed slice.
            % We just update this below (user supplies in mm, 'slab' stores
            % in pixels)
            slab = round(positionIn.Value/hpxS);
            set(lblPos,'String',strcat(num2str(round(positionIn.Value)),' mm'))

            % update the image display
            if areWeSettingDefaults == 0
                if smoothedRingsDrawn == 0
                    drawAndLabelRings
                else
                    drawAndLabelSmoothedRings
                end
            end
            functionsOn
        end

        if areWeGoingBack == 1
            slabPos = returnSlabPos*hpxS;
            slab = returnSlabPos;
        end

        % Create slider bar for adjusting slice position
        if ct == 1
            if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
                try positionIn = uislider(UserFig,'Position',figscale*[725,385,265,25],...
                    'Limits',[3+ceil(thick*hpxS/2) round(col*hpxS)-3-floor(thick*hpxS/2)],...
                    'Value', slabPos,'MinorTicks',[],...
                    'FontColor',themeColor1,...
                    'ValueChangedFcn', @position_Callback);
                catch
                    positionIn = uislider(UserFig,'Position',figscale*[725,385,265,25],...
                    'Limits',[thick_mm/2+thick*hpxS/2, round(col*hpxS)-thick_mm/2-thick*hpxS/2],...
                    'Value', mean([thick_mm/2+thick*hpxS/2, round(col*hpxS)-thick_mm/2-thick*hpxS/2]),'MinorTicks',[],...
                    'FontColor',themeColor1,...
                    'ValueChangedFcn', @position_Callback);
                end
            else
                positionIn = uicontrol(UserFig,'Style','slider',...
                    'Position',figscale*[725,365,265,25],'Units','normalized',...
                    'Min', 1+ceil(thick*hpxS/2),'Max', round(col*hpxS)-1-floor(thick*hpxS/2),'Value', slabPos,'Callback', @position_Callback);
            end
        else
            positionIn = uicontrol(UserFig,'Style','slider',...
                'Position',figscale*[725,380,265,25],'Units','normalized',...
                'Min', 1,'Max', 3,'Value', 2,'Callback', @position_Callback);
        end

        % Label for current position setting
        lblPos = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(positionIn.Value)),' mm'),...
            'Position',figscale*[850,396,83,23],'Units','normalized','ForegroundColor',themeColor1,...
            'BackGroundColor','none','FontSize',textscale*12,'FontName','Arial');

        % Function for response to user's image rotation selection
        function rotation_Callback(source,eventdata)

            functionsOff

            set(lblRot,'String',strcat(num2str(round(rotationIn.Value)),' °'))

            newRot = 1; % toggle to identify that this is a new rotation

            xs = get(ha,'XLim'); % store current x limit of display
            ys = get(ha,'YLim'); % store current y limit of display
            haveLims = 1; % toggle to store that we've saved these

            % turn on label to show this is loading because it can take a
            % while
            set(lblLoading,'Visible','on')

            % short pause because this is needed to enable the visible on
            % to take effect
            pause(0.01)

            % save previous rotation angle (currently in 'x_ang_new');
            x_ang_old = x_ang_new;

            % update 'x_ang_new' with user's selected rotation
            x_ang_new = rotationIn.Value;

            % calculate difference between previous and new rotation
            x_ang_dif = x_ang_new-x_ang_old;

            % rotate 'X' (the CT scan data)
            X = imrotate3(X,x_ang_dif,[0,0,1],'linear','crop','FillValues',-1000);

            % rotate userRings

            hold_rings = zeros(row,col,length(userRings(1,1,:))+1);
            hold_rings(:,:,2:end) = userRings;
            hold_rings = imrotate3(hold_rings,x_ang_dif,[0,0,1],'nearest','crop','FillValues',0);
            userRings = hold_rings(:,:,2:end);
            hold_rings = [];
            %userRings = imrotate3(userRings,x_ang_dif,[0,0,1],'nearest','crop','FillValues',0);

            % store our current rotation as 'x_ang'
            x_ang = x_ang_new;

            % display intersects of existing rings into this new view
            if smoothedRingsDrawn == 0
                drawAndLabelRings
            else
                drawAndLabelSmoothedRings
            end

            %haveLims = 0;

            % turn off 'Loading' label
            set(lblLoading,'Visible','off')

            functionsOn

        end

        function rotate2d_Callback(source,eventdata)

            functionsOff

            set(lblRot2d,'String',strcat(num2str(round(Rotate2dIn.Value)),' °'))

            newRot = 1; % toggle to identify that this is a new rotation

            xs = get(ha,'XLim'); % store current x limit of display
            ys = get(ha,'YLim'); % store current y limit of display
            haveLims = 1; % toggle to store that we've saved these

            % turn on label to show this is loading because it can take a
            % while
            set(lblLoading,'Visible','on')

            % short pause because this is needed to enable the visible on
            % to take effect
            pause(0.01)

            % save previous rotation angle (currently in 'x_ang_new');
            x_ang_old = x_ang;

            % update 'x_ang_new' with user's selected rotation
            x_ang_new = Rotate2dIn.Value;
            
            % calculate difference between previous and new rotation
            x_ang_dif = x_ang_new-x_ang_old;

            userRings0 = zeros(size(slabDraw(:,:,1)));
            userRings02 = zeros(size(slabDraw(:,:,1)));
            if sum(~isnan(ringMarks1D))>0
                userRings03 = zeros(size(slabDraw(:,:,1)));
            end
            if sum(~isnan(ringMarks1D2))>0
                userRings05 = zeros(size(slabDraw(:,:,1)));
            end
            if size(line_segments,1)>1
                userRings04 = zeros(size(slabDraw(:,:,1)));
            end
            if size(treeROI,1)>1
                userRings06 = zeros(size(slabDraw(:,:,1)));
            end


            % rotate slab (the image data)
            slabDraw = imrotate(slabDraw,-x_ang_dif,'bilinear','loose');
            %slabDraw2 = imrotate3(slabDraw,x_ang_dif,'bilinear','loose');

            % find empty rows and columns for deletion
            keep_cols = max(max(slabDraw,[],3),[],1)~=0;
            keep_rows = max(max(slabDraw,[],3),[],2)~=0;

            % rotate userRings
            % 
            % hold_rings = zeros(row,col,length(userRings(1,1,:))+1);
            % hold_rings(:,:,2:end) = userRings;
            % hold_rings = imrotate3(hold_rings,x_ang_dif,[0,0,1],'nearest','crop','FillValues',0);
            % userRings = hold_rings(:,:,2:end);
            % hold_rings = [];
            
            % rotate userRings
            [ur,uc] = find(userRings);
            if length(uc)>0
                for jjk = 1:length(uc)
                    userRings0(userRings(ur(jjk),uc(jjk)),ur(jjk)) = uc(jjk);
                end
            end
            userRings0 = imrotate(userRings0,-x_ang_dif,'nearest','loose');

            % remove empty rows and cols
            slabDraw = slabDraw(keep_rows,keep_cols,:);
            userRings0 = userRings0(keep_rows,keep_cols,:);

            userRings = zeros(size(slabDraw,2),maxRings);
            [ur,uc] = find(userRings0);
            if length(uc)>0
                for jjk = 1:length(uc)
                    userRings(uc(jjk),userRings0(ur(jjk),uc(jjk))) = ur(jjk);
                end
            end

            % rotate userRings2
            [ur,uc] = find(userRings2);
            if length(uc)>0
                for jjk = 1:length(uc)
                    userRings02(userRings2(ur(jjk),uc(jjk)),ur(jjk)) = uc(jjk);
                end
            end
            userRings02 = imrotate(userRings02,-x_ang_dif,'nearest','loose');

            % remove empty rows and cols
            userRings02 = userRings02(keep_rows,keep_cols,:);

            userRings2 = zeros(size(slabDraw,2),maxRings);
            [ur,uc] = find(userRings02);
            if length(uc)>0
                for jjk = 1:length(uc)
                    userRings2(uc(jjk),userRings02(ur(jjk),uc(jjk))) = ur(jjk);
                end
            end

            % rotate 1D marks
            if sum(~isnan(ringMarks1D))>0
                for jjk = 1:length(ringMarks1D)
                    if ringMarks1D(jjk,1) > 0 && ringMarks1D(jjk,2) > 0
                    userRings03(round(ringMarks1D(jjk,2)/pxS)-1:round(ringMarks1D(jjk,2)/pxS)+1,...
                        round(ringMarks1D(jjk,1)/hpxS)-1:round(ringMarks1D(jjk,1)/hpxS)+1) = jjk;
                    end
                end

                userRings03 = imrotate(userRings03,-x_ang_dif,'nearest','loose');

                % remove empty rows and cols
                userRings03 = userRings03(keep_rows,keep_cols,:);

                ringMarks1D = zeros(size(ringMarks1D));
                for jjk = 1:length(ringMarks1D)
                    [ur,uc] = find(userRings03==jjk);
                    ringMarks1D(jjk,:) = [mean(uc)*hpxS,mean(ur)*pxS];
                end

                clearvars userRings03
            end

            % rotate negative 1D marks
            if sum(~isnan(ringMarks1D2))>0
                for jjk = 1:length(ringMarks1D2)
                    if ringMarks1D2(jjk,1) > 0 && ringMarks1D2(jjk,2) > 0
                    userRings05(round(ringMarks1D2(jjk,2)/pxS)-1:round(ringMarks1D2(jjk,2)/pxS)+1,...
                        round(ringMarks1D2(jjk,1)/hpxS)-1:round(ringMarks1D2(jjk,1)/hpxS)+1) = jjk;
                    end
                end

                userRings05 = imrotate(userRings05,-x_ang_dif,'nearest','loose');

                % remove empty rows and cols
                userRings05 = userRings05(keep_rows,keep_cols,:);

                ringMarks1D2 = zeros(size(ringMarks1D2));
                for jjk = 1:length(ringMarks1D2)
                    [ur,uc] = find(userRings05==jjk);
                    ringMarks1D2(jjk,:) = [mean(uc)*hpxS,mean(ur)*pxS];
                end

                clearvars userRings05
            end

            % rotate segments
            if size(line_segments,1)>1
                for jjk = 1:length(line_segments)
                    userRings04(round(line_segments(jjk,2)/pxS)-1:round(line_segments(jjk,2)/pxS)+1,...
                        round(line_segments(jjk,1)/hpxS)-1:round(line_segments(jjk,1)/hpxS)+1) = jjk;
                end

                userRings04 = imrotate(userRings04,-x_ang_dif,'nearest','loose');

                % remove empty rows and cols
                userRings04 = userRings04(keep_rows,keep_cols,:);

                line_segments = zeros(size(line_segments));
                for jjk = 1:length(line_segments)
                    [ur,uc] = find(userRings04==jjk);
                    line_segments(jjk,:) = [mean(uc)*hpxS,mean(ur)*pxS];
                end

                clearvars userRings04

                interp_segments = [interp1(1:length(line_segments(:,1)),line_segments(:,1),linspace(1,length(line_segments(:,1)),length(line_segments(:,1))*1e4))',...
                    interp1(1:length(line_segments(:,2)),line_segments(:,2),linspace(1,length(line_segments(:,2)),length(line_segments(:,2))*1e4))'];
            end

            if size(treeROI,1)>1

                for jjk = 1:length(treeROI(:,1))
                    userRings06(round(treeROI(jjk,2)/pxS)-1:round(treeROI(jjk,2)/pxS)+1,...
                        round(treeROI(jjk,1)/hpxS)-1:round(treeROI(jjk,1)/hpxS)+1) = jjk;
                end

                userRings06 = imrotate(userRings06,-x_ang_dif,'nearest','loose');

                % remove empty rows and cols
                userRings06 = userRings06(keep_rows,keep_cols,:);

                treeROI = zeros(size(treeROI));
                for jjk = 1:length(treeROI(:,1))
                    [ur,uc] = find(userRings06==jjk);
                    treeROI(jjk,:) = [mean(uc)*hpxS,mean(ur)*pxS];
                end

                clearvars userRings06

                hold(ha,'on')
                measArea = plot(ha,[treeROI(:,1);treeROI(1,1)],[treeROI(:,2);treeROI(1,2)],'r-','LineWidth',2);
                hold(ha,'off')
                
            end

            % store our current rotation as 'x_ang'
            x_ang = x_ang_new;

            clearvars userRings0 userRings02

            % update image size
            col = size(slabDraw,2);
            row = size(slabDraw,2);
            layers = size(slabDraw,1);

            % set blanks to NaN:
            [del_r,del_c] = find(max(slabDraw,[],3)==0);
            for jk = 1:length(del_r)
                slabDraw(del_r(jk),del_c(jk),:) = NaN;
            end

            % display intersects of existing rings into this new view
            if smoothedRingsDrawn == 0
                drawAndLabelRingsXray
            else
                drawAndLabelSmoothedRingsXray
            end

            %haveLims = 0;

            % turn off 'Loading' label
            set(lblLoading,'Visible','off')

            functionsOn
            pause(0.01)

        end

        if areWeGoingBack == 1
            startingRotation = x_ang;
        end

        % Create slider bar for adjusting slice rotation
        if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
            rotationIn = uislider(UserFig,'Position',figscale*[725,297,265,25],...
                'Limits',[0 180],'MajorTicks',0:15:180,'MinorTicks',[],...
                'Value', startingRotation,...
                'FontColor',themeColor1,...
                'ValueChangedFcn', @rotation_Callback);
        else
            rotationIn = uicontrol(UserFig,'Style','slider',...
                'Position',figscale*[725,277,265,25],'Units','normalized',...
                'Min', 0,'Max',180,'Value', startingRotation,'Callback', @rotation_Callback);
        end

        if areWeGoingBack == 1
            rotationIn.Value = 0;
        end

        % Label for current rotation setting
        lblRot = uicontrol(UserFig,'Style','text','String',strcat(num2str(round(rotationIn.Value)),' °'),...
            'Position',figscale*[850,308,83,23],'Units','normalized','ForegroundColor',themeColor1,...
