        % Function for response to user's choice to redo a ring
        function erase_Callback(source,eventdata)

            try
                if isfinite(ring2erase) && ring2erase==floor(ring2erase)
                    disableAll

                    % set all ring locations to zero for this ring
                    if ringType == 1
                        if ct == 1
                            userRings(:,:,ring2erase) = 0;
                        else
                            userRings(:,ring2erase) = 0;
                            if length(ringMarks1D) > 1
                                try
                                ringMarks1D(ring2erase,:) = NaN;
                                catch
                                end
                            end
                        end
                    else
                        if ct == 1
                            userRings2(:,:,ring2erase) = 0;
                        else
                            userRings2(:,ring2erase) = 0;
                            if length(ringMarks1D2) > 1
                                try
                                ringMarks1D2(ring2erase,:) = NaN;
                                catch
                                end
                            end
                        end
                    end

                    if length(xIntersect) >= ring2erase
                        xIntersect(ring2erase) = 0;
                        yIntersect(ring2erase) = 0;
                    end

                    %if ringType == 1
                        j = ring2erase-1;
                        if any((j+1)==missingRings)
                            while any((j+1)==missingRings)
                                j = j+1;
                            end
                        end
                        if yrTog == 0
                            textClick = sprintf('Next ring will be ring %s',num2str(round(j+1)));
                        else
                            updatebreaksNumbering
                            textClick = sprintf('Next ring will be top of %s',num2str(inputTopYear-round(j+1)+1+breaksRingsCumSum(j+1)));
                        end
                    % else
                    %     j = ring2erase+1;
                    %     if any((j+1)==missingRings)
                    %         while any((j+1)==missingRings)
                    %             j = j+1;
                    %         end
                    %     end
                    %     if yrTog == 0
                    %         textClick = sprintf('Next ring will be ring %s',num2str(round(j-1)));
                    %     else
                    %         textClick = sprintf('Next ring will be top of %s',num2str(-(inputTopYear-abs(round(j-1))+1)));
                    %     end
                    % end

                    % update label that says what the next ring will be
                    set(lblClick,'String',textClick,'ForeGroundColor',themeColor1)

                    % show a label that the ring was deleted
                    delete(lblErased) % delete this label if it already exists

                    % display label confirming the ring was deleted
                    lblErased = uicontrol(UserFig,'Style','text','String',sprintf('Erased ring %s',eraseSetIn.String),'Position',figscale*[190,330,300,60],'BackgroundColor',[0.97,0.90,0.61],'FontWeight','bold','FontSize',textscale*18,'FontName','Arial','Units','normalized');
                    set(lblErased,'Visible','on')

                    % update image display
                    if ct
                        if smoothedRingsDrawn == 0
                            drawAndLabelRings
                        else
                            drawAndLabelSmoothedRings
                        end
                    else
                        if smoothedRingsDrawn == 0
                            drawAndLabelRingsXray
                        else
                            drawAndLabelSmoothedRingsXray
                        end
                    end

                    pause(3)

                    set(lblErased,'Visible','off')
                end
            catch
            end
            enableAll
        end

        % Function for response to user's choice to delete a ring
        function delete_Callback(source,eventdata)

            try
                if isfinite(ring2delete) && ring2delete==floor(ring2delete)
                    disableAll

                    % completely delete this ring
                    if ringType == 1
                        if ct == 1
                            userRings(:,:,ring2delete) = [];
                            totRings =length(find(max(max(userRings)))>0);
                        else
                            userRings(:,ring2delete) = [];
                            totRings =length(find(max(userRings))>0);
                            if length(ringMarks1D) >= ring2delete
                                ringMarks1D(ring2delete,:) = [];
                            end
                        end
                    else
                        if ct == 1
                            userRings2(:,:,ring2delete) = [];
                            totRings =length(find(max(max(userRings)))>0);
                        else
                            userRings2(:,ring2delete) = [];
                            totRings =length(find(max(userRings))>0);
                            if length(ringMarks1D2) >= abs(ring2delete)
                                ringMarks1D2(ring2delete,:) = [];
                            end
                        end
                    end


                    % show a label that the ring was deleted
                    delete(lblDeleted) % delete this label if it already exists

                    % display label confirming the ring was deleted
                    lblDeleted = uicontrol(UserFig,'Style','text','String',sprintf('Removed ring %s',deleteSetIn.String),'Position',figscale*[190,330,300,60],'BackgroundColor',[0.97,0.90,0.61],'FontWeight','bold','FontSize',textscale*18,'FontName','Arial');
                    set(lblDeleted,'Visible','on')

                    % update image display
                    if ct
                        if smoothedRingsDrawn == 0
                            drawAndLabelRings
                        else
                            drawAndLabelSmoothedRings
                        end
                    else
                        if smoothedRingsDrawn == 0
                            drawAndLabelRingsXray
                        else
                            drawAndLabelSmoothedRingsXray
                        end
                    end

                    pause(3)

                    set(lblDeleted,'Visible','off')
                end
            catch
            end
            enableAll

        end


