        % Function for response to user's selection of ring to insert
        function insertSet_Callback(source,eventdata)
            insertThisRing = str2num(insertSetIn.String); % simply store it here
            if yrTog == 1
                %if ringType == 2
                %    insertThisRing = -(inputTopYear-abs(insertThisRing) +1);
                %else
                    %insertThisRing = inputTopYear-insertThisRing +1;
                %end
                updatebreaksNumbering
                insertThisRing = inputTopYear-insertThisRing +1;
                if insertThisRing>length(breaksRingsCumSum)
                    insertThisRing = insertThisRing+breaksRingsCumSum(end);
                else
                    insertThisRing = insertThisRing+breaksRingsCumSum(insertThisRing);
                end
            end
