        % Function for response to user's choice to insert a ring
        function insert_Callback(source,eventdata)
            disableAll

            if ringType == 1
                if ct == 1
                    userRings(:,:,1:insertThisRing) = userRings(:,:,1:insertThisRing); % CAN'T THIS BE DELETD?

                    % Copy the rings below the chosen one, but shifted down one
                    % place in the 3rd dimension of userRings
                    userRings(:,:,insertThisRing+2:length(userRings(1,1,:))+1) = userRings(:,:,insertThisRing+1:length(userRings(1,1,:)));

                    % Set the inserted ring data to all zeros (i.e. empty)
                    userRings(:,:,insertThisRing+1) = zeros(row,col);
                else
                    userRings(:,1:insertThisRing) = userRings(:,1:insertThisRing);
                    userRings(:,insertThisRing+2:length(userRings(1,:))+1) = userRings(:,insertThisRing+1:length(userRings(1,:)));
                    userRings(:,insertThisRing+1) = zeros(size(userRings,1),1);
                    if length(ringMarks1D) > 1
                        ringMarks1D(insertThisRing+2:length(ringMarks1D(:,1))+1,:) = ringMarks1D(insertThisRing+1:length(ringMarks1D(:,1)),:);
                        ringMarks1D(insertThisRing+1,:) = NaN;
                    end
                end
            else
                if ct == 1
                    userRings2(:,:,1:insertThisRing) = userRings2(:,:,1:insertThisRing); % CAN'T THIS BE DELETD?

                    % Copy the rings below the chosen one, but shifted down one
                    % place in the 3rd dimension of userRings
                    userRings2(:,:,insertThisRing+2:length(userRings2(1,1,:))+1) = userRings2(:,:,insertThisRing+1:length(userRings(1,1,:)));

                    % Set the inserted ring data to all zeros (i.e. empty)
                    userRings2(:,:,insertThisRing+1) = zeros(row,col);
                else
                    userRings2(:,1:insertThisRing) = userRings2(:,1:insertThisRing);
                    userRings2(:,insertThisRing+2:length(userRings2(1,:))+1) = userRings2(:,insertThisRing+1:length(userRings2(1,:)));
                    userRings2(:,insertThisRing+1) = zeros(size(userRings2,1),1);
                    if length(ringMarks1D2) > 1
                        ringMarks1D2(insertThisRing+2:length(ringMarks1D2(:,1))+1,:) = ringMarks1D2(insertThisRing+1:length(ringMarks1D2(:,1)),:);
                        ringMarks1D2(insertThisRing+1,:) = NaN;
                    end
                end
            end

            % update j to the ring we inserted, assuming user will want to
            % define it now
            j = insertThisRing;

            %if ringType == 1
                if any((j+1)==missingRings)
                    while any((j+1)==missingRings)
                        j = j+1;
                    end
                end
                if yrTog == 0
                    textClick = sprintf('Next ring will be ring %s',num2str(round(j+1)));
                else
