        function cropRings_Callback(source,eventdata)

            roiCrop = drawrectangle(ha);

            rows_remove = [roiCrop.Position(2), roiCrop.Position(2)+roiCrop.Position(4)];
            cols_remove = [roiCrop.Position(1), roiCrop.Position(1)+roiCrop.Position(3)];

            % make sure it's within the image dimensions:
            if cols_remove(2)/hpxS > size(userRings,1)
                cols_remove(2) = size(userRings,1).*hpxS;
            end
            if cols_remove(1)/hpxS < 1
                cols_remove(1) = 1;
            end

            % remove 2d
            [rem1,rem2] = find(userRings(round(cols_remove(1)./hpxS):round(cols_remove(2)./hpxS),:) > round(rows_remove(1)./pxS) & ...
                userRings(round(cols_remove(1)./hpxS):round(cols_remove(2)./hpxS),:) < round(rows_remove(2)./pxS));

            for i6 = 1:length(rem1)
                userRings(rem1(i6)+round(cols_remove(1)./hpxS)-1,rem2(i6)) = 0;
            end

            [rem1,rem2] = find(userRings2(round(cols_remove(1)./hpxS):round(cols_remove(2)./hpxS),:) > round(rows_remove(1)./pxS) & ...
                userRings2(round(cols_remove(1)./hpxS):round(cols_remove(2)./hpxS),:) < round(rows_remove(2)./pxS));

            for i6 = 1:length(rem1)
                userRings2(rem1(i6)+round(cols_remove(1)./hpxS)-1,rem2(i6)) = 0;
            end

            % remove 1d
            if length(ringMarks1D) == 1
                ringMarks1D = [NaN,NaN];
            else
                ringMarks1D(ringMarks1D(:,1)>cols_remove(1) & ringMarks1D(:,1)<cols_remove(2) &...
                    ringMarks1D(:,2)>rows_remove(1) & ringMarks1D(:,2)<rows_remove(2),:) = [];

                ringMarks1D2(ringMarks1D2(:,1)>cols_remove(1) & ringMarks1D2(:,1)<cols_remove(2) &...
                    ringMarks1D2(:,2)>rows_remove(1) & ringMarks1D2(:,2)<rows_remove(2),:) = [];
            end

            functionsOff
            if ct
                if smoothedRingsDrawn == 0
                    drawAndLabelRings
                else
                    drawAndLabelSmoothedRings
                end
            else
                if smoothedRingsDrawn == 0
                    drawAndLabelRingsXray
                else
                    drawAndLabelSmoothedRingsXray
                end
            end
            functionsOn
        end

        cropSegmentsIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'Crop segments'},'Visible','off',...
            'Position',figscale*[660,460,200,40],'Units','normalized','BackgroundColor',butCols(1,:),'FontSize',textscale*14,'FontName','Arial','Callback',@cropSegments_Callback);

        function cropSegments_Callback(source,eventdata)

            roiCrop = drawrectangle(ha);

            rows_remove = [roiCrop.Position(2), roiCrop.Position(2)+roiCrop.Position(4)];
            cols_remove = [roiCrop.Position(1), roiCrop.Position(1)+roiCrop.Position(3)];

            % make sure it's within the image dimensions:
            if cols_remove(2)./hpxS > size(userRings,1)
                cols_remove(2) = size(userRings,1).*hpxS;
            end
            if cols_remove(1)./hpxS < 1
                cols_remove(1) = 1;
            end

            rem_segs = find(line_segments(:,1)>cols_remove(1) & line_segments(:,1)<cols_remove(2) &...
                line_segments(:,2)>rows_remove(1) & line_segments(:,2)<rows_remove(2));

            line_segments(rem_segs,:) = [];

            if size(line_segments,1)>1
                interp_segments = [interp1(1:length(line_segments(:,1)),line_segments(:,1),linspace(1,length(line_segments(:,1)),length(line_segments(:,1))*1e4))',...
                    interp1(1:length(line_segments(:,2)),line_segments(:,2),linspace(1,length(line_segments(:,2)),length(line_segments(:,2))*1e4))'];
            else
                interp_segments = [];
            end
            get1Dintersections % this updates ringMarks1D for where there are 2D-ring intersections
            get1Dintersections2

            % for top of rings
            totRings3 = find(max(userRings)); % which rings are from 2D
            totRings4 = find(ringMarks1D(:,1))'; % which rings are from 1D
            totRings5 = setdiff(totRings4,totRings3); % which rings are only 1D

            if length(interp_segments)
                for i4 = totRings5
                    d = pdist2(interp_segments,ringMarks1D(i4,:));
                    [val,loc] = min(d);
                    ringMarks1D(i4,1:2) = interp_segments(loc,:);
                end
            else
                ringMarks1D = [NaN,NaN];
            end

            % for bottom of rings
            totRings3 = find(max(userRings2)); % which rings are from 2D
            totRings4 = find(ringMarks1D2(:,1))'; % which rings are from 1D
            totRings5 = setdiff(totRings4,totRings3); % which rings are only 1D

            if length(interp_segments)
                for i4 = totRings5
                    d = pdist2(interp_segments,ringMarks1D2(i4,:));
                    [val,loc] = min(d);
                    ringMarks1D2(i4,1:2) = interp_segments(loc,:);
                end
            else
                ringMarks1D2 = [NaN,NaN];
            end

            functionsOff
            if ct
                if smoothedRingsDrawn == 0
                    drawAndLabelRings
                else
                    drawAndLabelSmoothedRings
                end
            else
                if smoothedRingsDrawn == 0
                    drawAndLabelRingsXray
                else
                    drawAndLabelSmoothedRingsXray
                end
            end
            if size(line_segments,1) <= 1
                set(click1DIn,'Visible','off')
            end
            functionsOn

        end

