        function drawMeasureArea(src,event)

            pan(ha,'off')
            zoom(ha,'off')
            set(zoomInIn,'Visible','on')
            set(zoomInOut,'Visible','off')
            set(panIn,'Visible','on')
            set(panOut,'Visible','off')

