            else
                thisROI = drawpolygon(ha,'Position',treeROI);
                functionsOff
                set(outlineMeasurementsOut,'Visible','on')
                uiwait(UserFig);
                if length(treeROI) > 2
                    try
                        treeROI = thisROI.Position;
                    catch
                        treeROI = [];
                    end
                else
                    treeROI = [];
                end
                set(outlineMeasurementsOut,'Visible','off')
                functionsOn
            end
            
            delete(thisROI);

            hold(ha,'on')
            if length(treeROI) > 2
                measArea = plot(ha,[treeROI(:,1);treeROI(1,1)],[treeROI(:,2);treeROI(1,2)],'r-','LineWidth',2);
            end
            hold(ha,'off')

        end

