        function missingRingsApply(source,eventdata)
            
            adjustBreaks = 0;
            try
                missingEntries = abs(str2num(missingRingsSetIn.String));
                if yrTog == 1
                    missingEntries = inputTopYear-missingEntries+1;
                end
                need2replot = 0;
                if missingEntries > 1
                    for ijj = 1:length(missingEntries)
                        
                        if any(missingEntries(ijj)==missingRings) % already exists, delete
                            if any(missingEntries(ijj)<missPos)
                                for ijjkk = 1:length(missPos)
                                    if missingEntries(ijj)<missPos(ijjkk)
                                        userRings(:,missPos(ijjkk)) = [];
                                        userRings(:,missPos(ijjkk)+1:end+1) = userRings(:,missPos(ijjkk):end);
                                        userRings(:,missPos(ijjkk)+1) = 0;
                                        try
                                            ringMarks1D(missPos(ijjkk),:) = [];
                                            ringMarks1D(missPos(ijjkk):end,:) = ringMarks1D(missPos(ijjkk)-1:end-1,:);
                                            ringMarks1D(missPos(ijjkk)-1,:) = 0;
                                        catch
                                        end
                                    end
                                end
                            end

                            if any(missingEntries(ijj)<missPos)
                                for ijjkk = 1:length(missPos)
                                    if missingEntries(ijj)<missPos(ijjkk)
                                        userRings2(:,missPos(ijjkk)) = [];
                                        userRings2(:,missPos(ijjkk)+1:end+1) = userRings2(:,missPos(ijjkk):end);
                                        userRings2(:,missPos(ijjkk)+1) = 0;
                                        try
                                            ringMarks1D2(missPos(ijjkk),:) = [];
                                            ringMarks1D2(missPos(ijjkk):end,:) = ringMarks1D2(missPos(ijjkk)-1:end-1,:);
                                            ringMarks1D2(missPos(ijjkk)-1,:) = 0;
                                        catch
                                        end
                                    end
                                end
                            end

                            missingRings(missingEntries(ijj)==missingRings) = [];
                            missingRings(-missingEntries(ijj)==missingRings) = [];
                            need2replot = 1;

                            % just delete the missing ring place in userRings and
                            % ringMarks since they should be empty
                            if ct == 1
                                % NEED TO DO
                            else
                                %if missingEntries(ijj) > 0
                                try userRings(:,missingEntries(ijj)) = [];
                                catch
                                end
                                try ringMarks1D(missingEntries(ijj),:) = [];
                                catch
                                end
                                %else
                                try userRings2(:,missingEntries(ijj)) = [];
                                catch
                                end
                                try ringMarks1D2(missingEntries(ijj),:) = [];
                                catch
                                end
                                %end
                            end

                        else % add to missing rings

                            % adjust for core breaks
                            if length(breaksRingsCumSum)>0 && yrTog == 1
                                missingEntries(ijj) = missingEntries(ijj)+breaksRingsCumSum(missingEntries(ijj));
                            end
                            %missingRings(missingRings<0) = missingRings(missingRings<0)+breaksRingsCumSum(abs(missingRings(missingRings<0)));

                            missingRings(end+1) = missingEntries(ijj);
                            missingRings(end+1) = -missingEntries(ijj);
                            missingRings = sort(missingRings,'ascend');

                            % adjust core breaks
                            adjustBreaks = 1;

                            % shift rings if this one was already defined
                            if ct == 1
                                % NEED TO DO
                            else
                                %if missingEntries(ijj) > 0
                                if any(missingEntries(ijj)<missPos)
                                    for ijjkk = 1:length(missPos)
                                        if missingEntries(ijj)<missPos(ijjkk)
                                            userRings(:,missPos(ijjkk)) = [];
                                            userRings(:,missPos(ijjkk):end) = userRings(:,missPos(ijjkk)-1:end-1);
                                            userRings(:,missPos(ijjkk)-1) = 0;
                                            try
                                                ringMarks1D(missPos(ijjkk),:) = [];
                                                ringMarks1D(missPos(ijjkk):end,:) = ringMarks1D(missPos(ijjkk)-1:end-1,:);
                                                ringMarks1D(missPos(ijjkk)-1,:) = 0;
                                            catch
                                            end
                                        end
                                    end
                                end
                                %if max(userRings(:,missingEntries(ijj))) > 0 % already defined
                                need2replot = 1;
                                userRings(:,missingEntries(ijj)+1:end+1) = userRings(:,missingEntries(ijj):end);
                                userRings(:,missingEntries(ijj)) = 0;
                                %end
                                try
                                    %if ringMarks1D(missingEntries(ijj),1) > 0% already defined
                                        need2replot = 1;
                                        ringMarks1D(missingEntries(ijj)+1:end+1,:) = ringMarks1D(missingEntries(ijj):end,:);
                                        ringMarks1D(missingEntries(ijj),:) = 0;
                                    %end
                                catch
                                end
                                if any(missingEntries(ijj)<missPos) % shift other missing rings
                                    for ijjkk = 1:length(missPos)
                                        if missingEntries(ijj)<missPos(ijjkk)
                                            userRings2(:,missPos(ijjkk)) = [];
                                            userRings2(:,missPos(ijjkk):end) = userRings2(:,missPos(ijjkk)-1:end-1);
                                            userRings2(:,missPos(ijjkk)-1) = 0;
                                            try
                                                ringMarks1D2(missPos(ijjkk),:) = [];
                                                ringMarks1D2(missPos(ijjkk):end,:) = ringMarks1D2(missPos(ijjkk)-1:end-1,:);
                                                ringMarks1D2(missPos(ijjkk)-1,:) = 0;
                                            catch
                                            end
                                        end
                                    end
                                end
                                %else
                                %if max(userRings2(:,missingEntries(ijj))) > 0 % already defined
                                    need2replot = 1;
                                    userRings2(:,missingEntries(ijj)+1:end+1) = userRings2(:,missingEntries(ijj):end);
                                    userRings2(:,missingEntries(ijj)) = 0;
                                %end
                                try
                                    %if ringMarks1D2(missingEntries(ijj),1) > 0% already defined
                                        need2replot = 1;
                                        ringMarks1D2(missingEntries(ijj)+1:end+1,:) = ringMarks1D2(missingEntries(ijj):end,:);
                                        ringMarks1D2(missingEntries(ijj),:) = 0;
                                    %end
                                catch
                                end
                                %end
                            end
                        end
                    end
                end
                updatebreaksNumbering
                %missingRings = missingRings-breaksRingsCumSum(missingRings);
                missingRingsList = {'';''};
                missPos = missingRings(missingRings>0);
                %missPos = missPos+breaksRingsCumSum(missPos);
                for ijj = 1:length(missPos)
                    if yrTog == 0
                        missingRingsList{ijj} = num2str(missPos(ijj));
                    else
                        missingRingsList{ijj} = num2str(inputTopYear-missPos(ijj)+1+breaksRingsCumSum(missPos(ijj)));
                    end
                end
                missingRingsSetIn.String = 'Enter missing rings';
                missingRingsIn.Items = missingRingsList;

                if adjustBreaks == 1
                    breaksRings(breaksRings>abs(missingEntries)) = breaksRings(breaksRings>abs(missingEntries))+1;
                    skipsRings(skipsRings>abs(missingEntries)) = skipsRings(skipsRings>abs(missingEntries))+1;
                end

                % replot if any rings shifted
                if need2replot == 1
                    if ct
                        if smoothedRingsDrawn == 0
                            drawAndLabelRings
                        else
                            drawAndLabelSmoothedRings
                        end
                    else
                        if smoothedRingsDrawn == 0
                            drawAndLabelRingsXray
                        else
                            drawAndLabelSmoothedRingsXray
                        end
                    end
                end
            catch
            end
            
        end


