        function mode1D_Callback(source,eventdata)
            % options to draw a segment or add rings
            % draw a segment is where user draws a line. If autorings are
            % on, then use same detection algorithm and tuning parameters as
            % already exists, placing single points along that line. If not
            % autorings, then after drawing the segment, the user can use
            % the add rings button to make clicks along the segment.
            % measurement is just 2-d distance point to point
            
            disableAll
            set(clickIn,'Visible','off')
            set(multiRingIn,'Visible','off')
            set(mode1DIn,'Visible','off')
            set(mode2DIn,'Visible','on')
            set(dispSmoothRingsIn,'Visible','off')
            set(dispInterpClicksIn,'Visible','off')
            if size(line_segments,1)>1
                set(click1DIn,'Visible','on')
            end
            set(drawSegmentIn,'Visible','on')
            set(cropSegmentsIn,'Visible','on')
            set(filterEditIn,'Visible','off')
            set(clickIn,'Visible','off')
            dimMode = 1;
            drawAndLabelRingsXray
            set(dispSmoothRingsIn,'Visible','off')
            enableAll

        end

        function mode2D_Callback(source,eventdata)

            disableAll
            set(clickIn,'Visible','on')
            if autoDetectionToggle == 1
                set(multiRingIn,'Visible','on')
            end
            set(mode1DIn,'Visible','on')
            set(mode2DIn,'Visible','off')
            set(click1DIn,'Visible','off')
            set(drawSegmentIn,'Visible','off')
            set(cropSegmentsIn,'Visible','off')
            set(dispSmoothRingsIn,'Visible','on')
            set(clickIn,'Visible','on')
            if smoothedRingsDrawn == 0
                set(dispSmoothRingsIn,'Visible','on')
                set(dispInterpClicksIn,'Visible','off')
            elseif smoothedRingsDrawn == 1
                set(dispSmoothRingsIn,'Visible','off')
                set(dispInterpClicksIn,'Visible','on')
            end

            dimMode = 2;
            drawAndLabelRingsXray
            enableAll
        end

        %first_segment = 1;
        function drawSegment_Callback(source,eventdata)
            new_segment = drawline(ha);
            if length(line_segments) < 1
                line_segments = new_segment.Position;
            else
                line_segments(end+1:end+2,:) = new_segment.Position;
            end
            delete(new_segment)
            disableAll
            drawAndLabelRingsXray
            interp_segments = [interp1(1:length(line_segments(:,1)),line_segments(:,1),linspace(1,length(line_segments(:,1)),length(line_segments(:,1))*1e4))',...
                interp1(1:length(line_segments(:,2)),line_segments(:,2),linspace(1,length(line_segments(:,2)),length(line_segments(:,2))*1e4))'];
            enableAll

            set(click1DIn,'Visible','on')

        end

        function clickXray1D_Callback(source,eventdata)
            function mouse_click(src,eventData)
                % get coordinates of click
                coords = eventData.IntersectionPoint;
                x1 = coords(1);
                y1 = coords(2);
                uiresume(UserFig)
            end
            if autoDetectionToggle == 1
                clickXrayMulti_Callback
            else
                iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                iptSetPointerBehavior(segPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                pause(0.01)

                clickingMode
                set(UndoLastClickIn,'Visible','off')
                set(drawDeleteBox1In,'Visible','off')

                pause(0.01)

                x1 = [];
                y1 = [];

                pause(0.01)
                currentYlim = get(ha,'YLim');
                currentXlim = get(ha,'XLim');
                pause(0.01)

                try
                    hz.Enable = 'off';
                    hp.Enable = 'off';
                catch
                    pause(1)
                    try
                        hz.Enable = 'off';
                        hp.Enable = 'off';
                    catch
                        pause(10)
                        try
                            hz.Enable = 'off';
                            hp.Enable = 'off';
                        catch
                            pause(30)
                            try
                                hz.Enable = 'off';
                                hp.Enable = 'off';
                            catch
                            end
                        end
                    end
                end

                ha.InteractionOptions.ZoomSupported = "off";
                ha.InteractionOptions.PanSupported = "off";

                set(lblCheck,'Visible','off')
                set(lblDeleted,'Visible','off')

                areWeDone = 0;

                hold(ha,'on')
                iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
                iptSetPointerBehavior(segPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));

                pause(0.01)

                while areWeDone == 0

                    %if j >= 0
                        j = j+1;
                        if any(j==missingRings)
                            while any(j==missingRings)
                                j = j+1;
                            end
                        end
                    % else
                    %     j = j-1;
                    %     if any(j==missingRings)
                    %         while any(j==missingRings)
                    %             j = j-1;
                    %         end
                    %     end
                    % end

                    if yrTog == 0
                        textClick = sprintf('Next ring is %s',num2str(round(j)));
                    else
                        updatebreaksNumbering
                        textClick = sprintf('Next ring is top of %s',num2str(inputTopYear-round(j+1)+1+breaksRingsCumSum(j)));
                    end
                    set(lblClick,'String',textClick,'ForeGroundColor',themeColor1)

                    pause(0.01);
                    if areWeDone == 1
                        set(lblClick,'String',' ')
                        j = j-1;
                        break
                    end

                    set(0, 'CurrentFigure', UserFig);
                    set(corePlot,'ButtonDownFcn',@mouse_click)
                    set(segPlot,'ButtonDownFcn',@mouse_click)
                    uiwait(UserFig);
                    set(corePlot,'ButtonDownFcn','')
                    set(segPlot,'ButtonDownFcn','')
                    
                    pause(0.01);
                    if areWeDone == 1
                        set(lblClick,'String',' ')
                        % if j >= 0
                            j = j-1;
                        % else
                        %     j = j+1;
                        % end
                        break
                    end

                    if ringType == 1
                        d = pdist2(interp_segments,[x1,y1]);
                        [val,loc] = min(d);
                        ringMarks1D(j,1:2) = interp_segments(loc,:);
                        plot(ha,ringMarks1D(j,1),ringMarks1D(j,2),'yo','LineWidth',2)
                        if yrTog == 0
                            ring_text(j) = text(ha,ringMarks1D(j,1),ringMarks1D(j,2),['  ',num2str(j)],'Color','y','Clipping','on');
                        else
                            ring_text(j) = text(ha,ringMarks1D(j,1),ringMarks1D(j,2),['  ',num2str(inputTopYear-j+1)],'Color','y','Clipping','on');
                        end
                        if yrTog == 1 && any(skipsRings==j)
                            set(ring_text(j),'Color','r');
                        end
                    else
                        d = pdist2(interp_segments,[x1,y1]);
                        [val,loc] = min(d);
                        ringMarks1D2(j,1:2) = interp_segments(loc,:);
                        plot(ha,ringMarks1D2(j,1),ringMarks1D2(j,2),'yo','LineWidth',2)
                        if yrTog == 0
                            ring_text2(j) = text(ha,ringMarks1D2(j,1),ringMarks1D2(j,2),['     ',num2str(j)],'Color','c','Clipping','on');
                        else
                            ring_text2(j) = text(ha,ringMarks1D2(j,1),ringMarks1D2(j,2),['     ',num2str(inputTopYear-j+1)],'Color','c','Clipping','on');
                        end
                        if yrTog == 1 && any(skipsRings+breaksRingsCumSum(i4)==i4)
                            set(ring_text2(i4),'Color','r');
                        end
                    end

                end

                iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'arrow'));
                iptSetPointerBehavior(segPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'arrow'));
                
                %if j >= 0
                    if any((j+1)==missingRings)
                        while any((j+1)==missingRings)
                            j = j+1;
                        end
                    end
                    if yrTog == 0
                        textClick = sprintf('Next ring will be %s',num2str(round(j+1)));
                    else
                        updatebreaksNumbering
                        textClick = sprintf('Next ring will be top of %s',num2str(inputTopYear-round(j+1)+1+breaksRingsCumSum(j+1)));
                    end
                % else
                %     if any((j-1)==missingRings)
                %         while any((j-1)==missingRings)
                %             j = j-1;
                %         end
                %     end
                %     if yrTog == 0
                %         textClick = sprintf('Next ring will be %s',num2str(round(j-1)));
                %     else
                %         textClick = sprintf('Next ring will be top of %s',num2str(-(inputTopYear-abs(round(j-1))+1)));
                %     end
                % end
                set(lblClick,'String',textClick,'ForeGroundColor',themeColor1)
                defaultMode
                
            end

        end

