        % Function to reset defaults
        function defaults_Callback(source,eventdata)
            functionsOff
            areWeSettingDefaults = 1;
            set(lblLoading,'Visible','on')
            if ct == 1
                thickIn.Value = thick_mm;
                thickness_Callback
                positionIn.Value = slabPos;
                position_Callback
                rotationIn.Value = 0;
                rotation_Callback
                if strcmp(brightnessIn.Visible,'on')
                    brightnessIn.Value = -1300;
                    brightness_Callback
                    contrastIn.Value = -2000;
                    contrast_Callback
                end
            end
            set(lblLoading,'Visible','off')
            areWeSettingDefaults = 0;
            functionsOn
        end

        function adjustBreaks(source,eventdata)

            set(editBreaksIn,'Visible','off')
            set(doneBreaksIn,'Visible','on')

            set(missingRingsTextIn,'Visible','off')
            set(missingRingsApplyIn,'Visible','off')
            set(missingRingsSetIn,'Visible','off')
