            set(breaksTextIn,'Visible','on')

            set(skipsApplyIn,'Visible','on')
            set(skipsIn,'Visible','on')
            set(skipsTextIn,'Visible','on')

            set(panIn,'Enable','off')
            set(panOut,'Enable','off')
            set(zoomInIn,'Enable','off')
            set(zoomInOut,'Enable','off')
            set(zoomOutIn,'Enable','off')

            breaksList = {'';''};
            for ijj = 1:length(breaksRings)
                %if yrTog == 0
                    breaksList{ijj} = num2str(breaksRings(ijj));
                % else
                %     breaksList{ijj} = num2str(inputTopYear - breaksRings(ijj)+1);
                % end
            end
            skipsList = {'';''};
            for ijj = 1:length(skipsRings)
                if yrTog == 1
                    skipsList{ijj} = num2str(inputTopYear - skipsRings(ijj)+1);
                else
                    skipsList{ijj} = num2str(skipsRings(ijj));
                end
            end
            if yrTog == 0
                breaksSetIn.String = 'Enter ring # above break/skip';
            else
                breaksSetIn.String = 'Enter year of break/skip';
            end
            breaksIn.Items = breaksList;
            skipsIn.Items = skipsList;

            pause(0.01)

        end

