        function breaksApply(source,eventdata)
            
            try
                if yrTog == 0
                    breaksEntries = str2num(breaksSetIn.String);
                else
                    breaksEntries = inputTopYear - str2num(breaksSetIn.String) + 1;
                end
                updatebreaksNumbering
                if yrTog == 1
                    breaksEntries = breaksEntries+breaksRingsCumSum(breaksEntries);
                end
                for ijj = 1:length(breaksEntries)
                    if any(breaksEntries(ijj)==breaksRings) % already exists, delete
                        breaksRings(breaksEntries(ijj)==breaksRings) = [];
                    else % add to missing rings
                        breaksRings(end+1) = breaksEntries(ijj);
                        breaksRings = sort(breaksRings,'ascend');
                        % adjust missing rings list
                        %userRings(:,missingRings(missingRings>abs(breaksEntries(ijj)))) = userRings(:,missingRings(missingRings>abs(breaksEntries(ijj)))-1);
                        %userRings(:,missingRings(missingRings>abs(breaksEntries(ijj)))-1) = 0;
                        %missingRings(missingRings>abs(breaksEntries(ijj))) = missingRings(missingRings>abs(breaksEntries(ijj)))-1;
                    end
                end
                updatebreaksNumbering
                breaksList = {'';''};
                for ijj = 1:length(breaksRings)
                    %if yrTog == 0
                        breaksList{ijj} = num2str(breaksRings(ijj));
                    % else
                    %     breaksList{ijj} = num2str(inputTopYr - breaksRings(ijj)+1);
                    % end
                end
                % adjust missing rings list
                missingRingsList = {'';''};
                missPos = missingRings(missingRings>0);
                %missPos = missPos-breaksRingsCumSum(missPos);
                for ijj = 1:length(missPos)
                    if yrTog == 0
                        missingRingsList{ijj} = num2str(missPos(ijj));
                    else
                        missingRingsList{ijj} = num2str(inputTopYear-missPos(ijj)+1+breaksRingsCumSum(missPos(ijj)));
                    end
                end
                missingRingsSetIn.String = 'Enter missing rings';
                missingRingsIn.Items = missingRingsList;

                if yrTog == 0
                    breaksSetIn.String = 'Enter ring # above break/skip';
                else
                    breaksSetIn.String = 'Enter year of break/skip';
                end
                breaksIn.Items = breaksList;

                %if yrTog == 1
                    if ct
                        if smoothedRingsDrawn == 0
                            drawAndLabelRings
                        else
                            drawAndLabelSmoothedRings
                        end
                    else
                        if smoothedRingsDrawn == 0
                            drawAndLabelRingsXray
                        else
                            drawAndLabelSmoothedRingsXray
                        end
                    end
                %end

            catch
            end
        end

