        function calibrate_callback(source,eventdata)

            set(lblLoading,'Visible','on')
            pause(0.01)
            disableAll
            calibFig = uifigure('Visible','on','Units','normalized','Position',([UserFig.Position(1)+UserFig.Position(3),UserFig.Position(2)+UserFig.Position(4)-0.1,0.1,0.1]),'Color','k');
            calibrationOut = uicontrol(calibFig,'Style','pushbutton',...
                'String',{'Apply calibration'},'Visible','on','Units','normalized',...
                'Position',[0.05,0.05,0.9,0.35],'BackgroundColor',[255,96,92]./256,'FontSize',11,'FontName','Arial','Callback',@calibratingDone);
            calibDistIn = uicontrol(calibFig,'Style','Edit','Visible','on','String','Enter mm',...
                'Units','normalized','Position',[0.05,0.5,0.9,0.35],'FontSize',textscale*12,'FontName','Arial');

            pause(3)
            set(lblLoading,'Visible','off')
            calib_line = drawline(ha);

            function calibratingDone(obj,evd)
                uiresume(UserFig);
            end

            uiwait(UserFig);
            try
                set(lblLoading,'Visible','on')
                pause(0.01)
                mm_measured = str2num(calibDistIn.String);
                pixels_measured = sqrt((calib_line.Position(1)-calib_line.Position(2))^2 + (calib_line.Position(3)-calib_line.Position(4))^2)/hpxS;
                hpxS = mm_measured/pixels_measured;
                pxS = mm_measured/pixels_measured;
                xrayDPI = 25.4/pxS;

                try mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                catch
                    try
                        cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password); % make sure we can connect to sftp server 1
                        cd(cache1,'tdecarlo19/public/TreeTrove');
                        mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                    catch
                        connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                        connectionEstablished = 0;
                        for ij = 1:length(connectTimes)
                            if connectionEstablished == 0
                                if connectTimes(ij) == 1
                                    waitText = [' ',num2str(connectTimes(ij)),' minute.']
                                else
                                    waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                                end
                                set(htextCalibStatus,'Visible','on',...
                                    'String',{'Error connecting to server.';strcat('Trying again in',waitText)},...
                                    'Units','normalized')
                                pause(connectTimes(ij)*60)
                                try
                                    cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                                    cd(cache1,'tdecarlo19/public/TreeTrove')
                                    mget22(cache1,'tree_directory_master.txt',fullfile(selpath,'my_trees'));
                                    connectionEstablished = 1;
                                    set(htextCalibStatus,'Visible','off')
                                catch
                                end
                            end
                        end
                        if connectionEstablished == 0
                            zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                        end
                        set(htextCalibStatus,'Visible','on',...
                            'String',{'Error connecting to server. (code 042)';'Please try again later.'},...
                            'Units','normalized')
                        while 1==1
                            pause
                        end
                    end
                end
                % import master directory into this session
                treeDir = importdata(fullfile(selpath,'my_trees','tree_directory_master.txt'));

                pause(0.01)
                %dirRow = find(strcmp(core4calibEqn,treeDir.textdata(:,1)));

                if length(dirRow)

                    treeDir.data(dirRow-1,14) = xrayDPI;
                    treeDirHold = treeDir;
                    treeDirHold.textdata = treeDirHold.textdata(2:end,:);
                    treeDirStruct = struct('name',treeDirHold.textdata(:,1),...
                        'piece',treeDirHold.textdata(:,2),...
                        'region',treeDirHold.textdata(:,3),...
                        'sub_region',treeDirHold.textdata(:,4),...
                        'genus',treeDirHold.textdata(:,5),...
                        'owner',treeDirHold.textdata(:,6),...
                        'notes',treeDirHold.textdata(:,7),...
                        'citation',treeDirHold.textdata(:,8),...
                        'acknowledgement',treeDirHold.textdata(:,9),...
                        'bibtex',treeDirHold.textdata(:,10),...
                        'hard_drive',treeDirHold.data(1,1),...
                        'flip',treeDirHold.data(1,2),...
                        'lat',treeDirHold.data(1,3),...
                        'lon',treeDirHold.data(1,4),...
                        'elevation',treeDirHold.data(1,5),...
                        'month',treeDirHold.data(1,6),...
                        'year',treeDirHold.data(1,7),...
                        'file_size',treeDirHold.data(1,8),...
                        'unlocked',treeDirHold.data(1,9),...
                        'denslope',treeDirHold.data(1,10),...
                        'denintercept',treeDirHold.data(1,11),...
                        'ct',treeDirHold.data(1,12),...
                        'imageinvert',treeDirHold.data(1,13),...
                        'dpi',treeDirHold.data(1,14));
                    for ic = 1:length(treeDirHold.data(:,1))
                        treeDirStruct(ic).hard_drive = treeDirHold.data(ic,1);
                        treeDirStruct(ic).flip = treeDirHold.data(ic,2);
                        treeDirStruct(ic).lat = treeDirHold.data(ic,3);
                        treeDirStruct(ic).lon = treeDirHold.data(ic,4);
                        treeDirStruct(ic).elevation = treeDirHold.data(ic,5);
                        treeDirStruct(ic).month = treeDirHold.data(ic,6);
                        treeDirStruct(ic).year = treeDirHold.data(ic,7);
                        treeDirStruct(ic).file_size = treeDirHold.data(ic,8);
                        treeDirStruct(ic).unlocked = treeDirHold.data(ic,9);
                        treeDirStruct(ic).denslope = treeDirHold.data(ic,10);
                        treeDirStruct(ic).denintercept = treeDirHold.data(ic,11);
                        treeDirStruct(ic).ct = treeDirHold.data(ic,12);
                        treeDirStruct(ic).imageinvert = treeDirHold.data(ic,13);
                        treeDirStruct(ic).dpi = treeDirHold.data(ic,14);
                    end
                    writetable(struct2table(treeDirStruct),fullfile(selpath,'my_trees','tree_directory_master.txt'),'Delimiter','\t')

                    try mput(cache1,fullfile(selpath,'my_trees','tree_directory_master.txt'));
                    catch
                        try
                            cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                            cd(cache1,'tdecarlo19/public/TreeTrove')
                            mput(cache1,fullfile(selpath,'my_trees','tree_directory_master.txt'));
                        catch
                            connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                            connectionEstablished = 0;
                            for ij = 1:length(connectTimes)
                                if connectionEstablished == 0
                                    if connectTimes(ij) == 1
                                        waitText = [' ',num2str(connectTimes(ij)),' minute.']
                                    else
                                        waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                                    end
                                    set(htextCalibStatus,'Visible','on',...
                                        'String',{'Error connecting to server.';strcat('Trying again in',waitText)},...
                                        'Units','normalized')
                                    pause(connectTimes(ij)*60)
                                    try
                                        cache1 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                                        cd(cache1,'tdecarlo19/public/TreeTrove')
                                        mput(cache1,fullfile(selpath,'my_trees','tree_directory_master.txt'));
                                        connectionEstablished = 1;
                                        set(htextCalibStatus,'Visible','off')
                                    catch
                                    end
                                end
                            end
                            if connectionEstablished == 0
                                zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                            end
                            set(htextCalibStatus,'Visible','on',...
                                'String',{'Error connecting to server. (code 042)';'Please try again later.'},...
                                'Units','normalized')
                            while 1==1
                                pause
                            end
                        end
                    end
                end

                delete(calibFig)
                delete(calib_line)
            catch
            end

