        viewScreenshotsIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'View screenshots'},'Visible','on',...
            'Position',figscale*[980,15,125,24],'Units','normalized','BackgroundColor',butCols(99,:),'FontSize',textscale*11,'FontName','Arial','Callback',@viewScreenshots);

        saveScreenshotIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'Snap screenshot'},'Visible','on',...
            'Position',figscale*[980,49,125,24],'Units','normalized','BackgroundColor',butCols(85,:),'FontSize',textscale*11,'FontName','Arial','Callback',@screenShot);

        function screenShot(source,eventdata)
            functionsOff
            set(saveScreenshotIn,'Enable','off')
            drawnow
            sshotFig = uifigure('Visible','on','Position',...
                [(this_screen(3)-1112*figscale)/4,(this_screen(4)-800*figscale)/2,800*figscale,800*figscale],'Color','k');
            sshotperim = uiaxes(sshotFig,'units','normalized','Position',[0,0,1,1]);
            set(sshotperim,'Color','k','xcolor','w','ycolor','w','XTick',[],'YTick',[],'Box','on','LineWidth',3)
            sha1 = uiaxes(sshotFig,'units','normalized','Position',[0.0300    0.1100    0.7    0.8150]);
            set(sha1,'Color','k','xcolor','k','ycolor','k','XTick',[],'YTick',[])
            box on
            axcopy = copyobj(ha.Children,sha1);
            set(sha1,'PlotBoxAspectRatio',[1 1 1])
            set(sha1,'DataAspectRatio',[1 1 1])
            set(sha1,'Colormap',colormap('bone'))
            set(sha1,'CLim',contra);
            set(sha1,'YLim',get(ha,'YLim'),'XLim',get(ha,'XLim'))
            t = datetime('now') ;
            t.Format = 'dd-MMM-uuuu HH:mm a';
            text(sha1,0.01,0.01,strcat([saveFileName,': ',char(t)]),'Color','y','units','normalized','FontSize',textscale*12)
            if strcmp(sectionName,'')
                dispTitleName = treeName;
            else
                dispTitleName = [treeName,' ',sectionName];
            end
            dispTitleName0 = double(dispTitleName);
            idxUnderScore = find(dispTitleName0==95);
            if length(idxUnderScore)
                dispTitleName = [];
                idxUnderScore = [0, idxUnderScore];
                for jjj = 2:length(idxUnderScore)
                    dispTitleName = [dispTitleName, dispTitleName0(idxUnderScore(jjj-1)+1:idxUnderScore(jjj)-1),92, 95];
                end
                dispTitleName = char([dispTitleName, dispTitleName0(idxUnderScore(jjj)+1:end)]);
            else
                %dispTitleName = treeName;
            end
            
            title(sha1,dispTitleName,'Color',themeColor1)

            if ct == 1
                sha2 = uiaxes(sshotFig,'units','normalized','Position',[0.7500    0.1100    0.2    0.2]);
                hold on
                set(sha2,'Color','k','xcolor','k','ycolor','k','XTick',[],'YTick',[])
                axcopy = copyobj(ha2.Children,sha2);
                set(sha2,'PlotBoxAspectRatio',[1 1 1])
                set(sha2,'DataAspectRatio',[1 1 1])
                set(sha2,'Colormap',colormap('bone'))
                set(sha2,'CLim',contra);
            else
                set(sha1,'YDir','reverse')
            end

            closeSnapIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Close window'},'Visible','on',...
                'Position',figscale*[10,765,130,24],'Units','normalized','BackgroundColor',[255,96,92]./256,'FontSize',textscale*11,'FontName','Arial','Callback',@closeSnap);

            function closeSnap(source,eventdata)
                close(sshotFig)
                set(saveScreenshotIn,'Enable','on')
            end

            drawAnnotationIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Draw textbox'},'Visible','on',...
                'Position',figscale*[160,765,140,24],'Units','normalized','BackgroundColor',[1 0.65 0],'FontSize',textscale*11,'FontName','Arial','Callback',@drawAnnote);

            textCol = [0.6 0.8 1];

            chooseColorIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Choose text color'},'Visible','on',...
                'Position',figscale*[320,765,140,24],'Units','normalized','BackgroundColor',textCol,'FontSize',textscale*11,'FontName','Arial','Callback',@chooseColor);

            function chooseColor(source,eventdata)
                textCol = uisetcolor(textCol);
                set(chooseColorIn,'BackgroundColor',textCol)
            end

            editAnnotationsIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Edit annotations'},'Visible','on',...
                'Position',figscale*[480,765,140,24],'Units','normalized','BackgroundColor',[0.97,0.90,0.61],'FontSize',textscale*11,'FontName','Arial','Callback',@editAnnotations);

            editAnnotationsOut = [];
            stopEditFig = [];
            keepEditingAnnotations = 0;
            function editAnnotations(source,eventdata)
                set(editAnnotationsIn,'Visible','off')
                stopEditFig = uifigure('Visible','on','Position',figscale*[800+50,900-26,182,26],'Color','k');
                editAnnotationsOut = uicontrol(stopEditFig,'Style','pushbutton',...
                    'String',{'Done Editing'},'Visible','on',...
                    'Position',figscale*[1,1,180,24],'Units','normalized','BackgroundColor',[255,96,92]./256,'FontSize',textscale*11,'FontName','Arial','Callback',@editAnnotationsDone);
                keepEditingAnnotations = 1;
                plotedit(sshotFig)
                posMain = get(sha1,'Position');
                while keepEditingAnnotations == 1
                    if sum(posMain - get(sha1,'Position'))==0
                    else
                        set(sha1,'Position',posMain)
                    end
                    pause(0.01)
                end

                function editAnnotationsDone(source,eventdata)
                    keepEditingAnnotations = 0;
                    plotedit(sshotFig,'off')
                    set(editAnnotationsIn,'Visible','on')
                    close(stopEditFig)
                end

            end

            function drawAnnote(source,eventdata)
                boxLoc = drawrectangle(sha1);
                posText = [(boxLoc.Position(1)-min(get(sha1,'XLim')))/range(get(sha1,'XLim'))*0.7+0.03,...
                    (boxLoc.Position(2)-min(get(sha1,'YLim')))/range(get(sha1,'YLim'))*0.8150*0.85+0.11+0.065,...
                    (boxLoc.Position(3))/range(get(sha1,'XLim'))*(0.7-0.03),...
                    (boxLoc.Position(4))/range(get(sha1,'YLim'))*(0.8150-0.11)];
                annotationIn = uitextarea(sshotFig,'Position',posText*800,...
                    'ValueChangedFcn',@(textarea,event) textEntered2(textarea),...
                    'FontColor','white','BackGroundColor','k','Visible','on');
                delete(boxLoc);
                text_entered = 0;
                function textEntered2(textarea)
                    val = textarea.Value;
                    for k = 1:length(val)
                        if(~isempty(val{k}))
                            text_entered = 1;
                            break;
                        end
                    end
                end
                while text_entered >= 0
                    pause(0.01)
                    if text_entered == 1
                        break
                    end
                end
                tbox = annotation(sshotFig,"textbox");
                tbox.String = val;
                tbox.Position = posText;
                tbox.FontSize = 12;
                tbox.EdgeColor = 'none';
                tbox.Color = textCol;
                delete(annotationIn)
            end

            labCol = [rand rand rand]*0.7+0.3;
            drawLineIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Measure line'},'Visible','on',...
                'Position',figscale*[640,765,140,24],'Units','normalized','BackgroundColor',labCol,'FontSize',textscale*11,'FontName','Arial','Callback',@drawLine);

            lineLoc = [];
            function drawLine(source,eventdata)
                lineLoc = drawline(sha1,'Color',labCol);
                thisMeasure = sqrt(((lineLoc.Position(2,2)-lineLoc.Position(1,2)))^2 + ...
                    ((lineLoc.Position(2,1)-lineLoc.Position(1,1)))^2);
                lineLoc.Label = ['   ',num2str(round(thisMeasure*100)/100),' mm'];
                lineLoc.LabelAlpha = 0.7;
                labCol = [rand rand rand]*0.7+0.3;
                drawLineIn.BackgroundColor = labCol;
                addlistener(lineLoc,'MovingROI',@changeLine);
                addlistener(lineLoc,'ROIMoved',@changeLine);
            end

            function changeLine(src,evt)
                thisMeasure = sqrt(((lineLoc.Position(2,2)-lineLoc.Position(1,2)))^2 + ...
                    ((lineLoc.Position(2,1)-lineLoc.Position(1,1)))^2);
                lineLoc.Label = ['   ',num2str(round(thisMeasure*100)/100),' mm'];
                lineLoc.LabelAlpha = 0.7;
            end

            screenShotToServerIn = uicontrol(sshotFig,'Style','pushbutton',...
                'String',{'Send to server'},'Visible','on',...
                'Units','normalized','Position',[0.8,0.5,0.15,0.075],'BackgroundColor',[1 0.65 0],'FontSize',textscale*11,'FontName','Arial','Callback',@screenShotToServer);

            function screenShotToServer(source,eventdata)

                try
                    if serverChoice == 1
                        cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password)
                    elseif serverChoice == 2
                        cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password)
                    elseif serverChoice == 3
                        cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                    end
                catch
                    try
                        if serverChoice == 1
                            cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password)
                        elseif serverChoice == 2
                            cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password)
                        elseif serverChoice == 3
                            cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                        end
                    catch
                        try
                            connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                            connectionEstablished = 0;
                            for ij = 1:length(connectTimes)
                                if connectionEstablished == 0
                                    if connectTimes(ij) == 1
                                        waitText = [' ',num2str(connectTimes(ij)),' minute.']
                                    else
                                        waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                                    end
                                    set(lblOpeningError,'Units','Pixels','Visible','on','Position',figscale*[200,130,500,40],...
                                        'String',{'Error connecting to server.';strcat('Trying again in',waitText)},...
                                        'Units','normalized')
                                    pause(connectTimes(ij)*60)
                                    try
                                        if serverChoice == 1
                                            cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password)
                                        elseif serverChoice == 2
                                            cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password)
                                        elseif serverChoice == 3
                                            cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                                        end
                                        connectionEstablished = 1;
                                        set(lblOpeningError,'Units','Pixels','Visible','off',...
                                            'Position',figscale*[200,150,500,20],'Units','normalized')
                                    catch
                                    end
                                end
                            end
                            if connectionEstablished == 0
                                zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                            end
                        catch
                            set(lblOpeningError,'Units','Pixels','Position',figscale*[200,130,500,40],'Visible','on',...
                                'String',{'Error connecting to server. (code 029)';'Please try again later.'},...
                                'Units','normalized')
                            while 1==1
                                pause
                            end
                        end
                    end
                end

                if strcmp('',sectionName) % no sections
                    % set directory to this tree's folder on server
                    server_path = strcat(h_drive,treeDir.textdata{dirRow,3},'/',...
                        treeDir.textdata{dirRow,4},'/',thisTreeName);
                    if serverChoice == 1 || serverChoice == 3
                        server_path(double(server_path)==32) = 95; % converts spaces to _
                    end
                else % yes, sections
                    % set directory to this sections's folder on server
                    server_path = strcat(h_drive,'/',treeDir.textdata{dirRow,3},'/',...
                        treeDir.textdata{dirRow,4},'/',thisTreeName,'/',thisSectionName);
                    if serverChoice == 1 || serverChoice == 3
                        server_path(double(server_path)==32) = 95; % converts spaces to _
                    end
                end
                cd(cache2,server_path)
                dSnaps = dir(cache2);
                dirSnaps = [];
                for iii = 1:length(dSnaps)
                    if length(strsplit(dSnaps(iii).name,'Screenshot'))==2
                        dirSnaps = [dirSnaps;dSnaps(iii).name];
                    end
                end
                if length(dirSnaps)
                    nSnaps = length(dirSnaps(:,1));
                else
                    nSnaps = 0;
                end
                img_text = sprintf('%05d', nSnaps+1);
                exportgraphics(sshotFig,fullfile(refPath,strcat('Screenshot_',img_text,'.png')),'BackgroundColor','k');
                mput(cache2,fullfile(refPath,strcat('Screenshot_',img_text,'.png')));

            end
            functionsOn
        end

        dispSmoothRingsIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'Show smoothed rings'},'Visible','off',...
            'Position',figscale*[220   15   210    30],'Units','normalized','BackgroundColor',butCols(1,:),'FontSize',textscale*11,'FontName','Arial','Callback',@dispSmoothRings);

        dispInterpClicksIn = uicontrol(UserFig,'Style','pushbutton',...
            'String',{'Show interpolated clicks'},'Visible','off',...
            'Position',figscale*[220   15   210    30],'Units','normalized','BackgroundColor',butCols(15,:),'FontSize',textscale*11,'FontName','Arial','Callback',@dispIntClicks);

        smoothedRingsDrawn = 0;

        function dispSmoothRings(source,eventdata)
            functionsOff
            set(dispInterpClicksIn,'Visible','on')
            set(dispSmoothRingsIn,'Visible','off')
            smoothedRingsDrawn = 1;
            if length(ringsPlot)
                if ct == 1
                    drawAndLabelSmoothedRings
                else
                    drawAndLabelSmoothedRingsXray
                end
            end
            functionsOn
        end

        function dispIntClicks(source,eventdata)
            functionsOff
            set(dispInterpClicksIn,'Visible','off')
            set(dispSmoothRingsIn,'Visible','on')
            smoothedRingsDrawn = 0;
            if ct == 1
                drawAndLabelRings
            else
                drawAndLabelRingsXray
            end
            functionsOn
        end

        function updateRingLines

            try delete(ringsPlot)
            catch
            end
            try delete(ringsPlot2)
            catch
            end
            try delete (ring_text)
            catch
            end
            try delete (prop_text)
            catch
            end

            if strcmp(detectMode,'seasonal')
                howManyLines = 2;
            else
                howManyLines = 1;
            end

            for ijk = 1:howManyLines
                if ijk == 1
                    whichRings = userRings;
                elseif ijk == 2
                    whichRings = userRings2;
                end
            if ct == 1
                if smoothedRingsDrawn == 0
                    if max(max(max(whichRings)))>0
                        totRings3 = find(max(max(whichRings)));
                        LDBdata = zeros(row,col,max(totRings3));
                        for i4 = totRings3'
                            if max(max(whichRings(:,:,i4)))>0
                                [r,c] = find(whichRings(:,:,i4));
                                if ~isempty(r)
                                    v = zeros(1,length(r));
                                    for j2 = 1:length(r)
                                        v(j2) = whichRings(r(j2),c(j2),i4);
                                    end
                                    warning('off','all');
                                    if length(round(griddata(r,c,v,rowMesh,colMesh)))>1
                                        LDBdata(:,:,i4) = permute(round(griddata(r,c,v,rowMesh,colMesh)),[2,1,3]);
                                    end
                                    warning('on','all');
                                end
                            end
                        end

                        LDBdata(isnan(LDBdata)) = 0;
                        ldbDraw = LDBdata;

                        reDrawLines(whichRings,ijk)
                        pause(0.001)
                        hold(ha,'on')
                        xIntersect = NaN(max(totRings3),1);
                        yIntersect = NaN(max(totRings3),1);
                        try delete(ring_text)
                        catch
                        end
                        updatebreaksNumbering
                        ring_text = gobjects(0);
                        for i4 = totRings3'
                            if max(max(whichRings(:,:,i4)))>0
                                [r,c] = find(LDBdata(:,slab,i4));
                                hold(ha,'on')
                                if length(r)>0
                                    if max(max(LDBdata(:,:,i4)))>0
                                        xIntersect(i4) = median(r)*hpxS;
                                        yIntersect(i4) = (LDBdata(round(median(r)),slab,i4)-layers)*-pxS;
                                        if yrTog == 1 && i4 < max(totRings3)
                                            if max(LDBdata(:,:,i4+1))>0
                                                [r2,c2] = find(LDBdata(:,slab,i4));
                                                yIntersect2 = (LDBdata(round(median(r)),slab,i4+1)-layers)*-pxS;
                                                yIntersectMean = mean([yIntersect(i4),yIntersect2]);
                                            end
                                        end
                                        if yrTog == 0
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersect(i4),num2str(i4),'Color','yellow','Clipping','on');
                                        elseif i4 < max(totRings3)
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersectMean,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','yellow','Clipping','on');
                                        end
                                        if yrTog == 1 && any(skipsRings==i4)
                                            set(ring_text(i4),'Color','r');
                                        end
                                    end
                                end
                                hold(ha,'off')
                            end
                        end
                    end

                else

                    if max(max(max(whichRings)))>0
                        totRings3 = find(max(max(whichRings)));
                        LDBdata = zeros(row,col,length(whichRings(1,1,1:max(totRings3))));
                        ring_filt4plot = zeros(size(LDBdata));
                        surf_filt = h3;
                        for i4 = totRings3'
                            if max(max(whichRings(:,:,i4)))>0
                                [r,c] = find(whichRings(:,:,i4));
                                if isempty(r)
                                    break
                                end
                                v = zeros(1,length(r));
                                for j2 = 1:length(r)
                                    v(j2) = whichRings(r(j2),c(j2),i4);
                                end
                                warning('off','all');
                                if length(round(griddata(r,c,v,rowMesh,colMesh)))>1
                                    LDBdata(:,:,i4) = permute(round(griddata(r,c,v,rowMesh,colMesh)),[2,1,3]);
                                end
                                warning('on','all');
                            end
                            ring_filt4plot(:,:,i4) = nanconv(LDBdata(:,:,i4), surf_filt, 'nanout');
                        end

                        LDBdata(isnan(LDBdata)) = 0;
                        ring_filt4plot(isnan(ring_filt4plot)) = 0;

                        ldbDraw = ring_filt4plot;

                        reDrawLines(whichRings,ijk)
                        %set(ringsPlot,'Color',[1 0.65 0])
                        set(ringsPlot,'Color','y')
                        pause(0.001)
                        hold(ha,'on')
                        xIntersect = NaN(max(totRings3),1);
                        yIntersect = NaN(max(totRings3),1);
                        try delete(ring_text)
                        catch
                        end
                        updatebreaksNumbering
                        ring_text = gobjects(0);
                        for i4 = totRings3'
                            if max(max(whichRings(:,:,i4)))>0
                                [r,c] = find(LDBdata(:,slab,i4));
                                hold(ha,'on')
                                if length(r)>0
                                    if max(max(LDBdata(:,:,i4)))>0
                                        xIntersect(i4) = median(r)*hpxS;
                                        yIntersect(i4) = (LDBdata(round(median(r)),slab,i4)-layers)*-pxS;
                                        if yrTog == 1 && i4 < max(totRings3)
                                            if max(LDBdata(:,:,i4+1))>0
                                                [r2,c2] = find(LDBdata(:,slab,i4));
                                                yIntersect2 = (LDBdata(round(median(r)),slab,i4+1)-layers)*-pxS;
                                                yIntersectMean = mean([yIntersect(i4),yIntersect2]);
                                            end
                                        end
                                        if yrTog == 0
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersect(i4),num2str(i4),'Color','y','Clipping','on');
                                        elseif i4 < max(totRings3)
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersectMean,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','y','Clipping','on');
                                        end
                                        if yrTog == 1 && any(skipsRings==i4)
                                            set(ring_text(i4),'Color','r');
                                        end
                                    end
                                end
                                hold(ha,'off')
                            end
                        end
                    end
                end

            else
                if smoothedRingsDrawn == 0

                    smoothed_on = 0;
                    reDrawLines(whichRings,ijk)
                    pause(0.001)
                    hold(ha,'on')
                    totRings3 = find(max(whichRings));
                    xIntersect = NaN(max(totRings3),1);
                    yIntersect = NaN(max(totRings3),1);
                    if ijk == 1
                        try delete(ring_text)
                        catch
                        end
                    elseif ijk == 2
                        try delete(ring_text2)
                        catch
                        end
                    end
                    updatebreaksNumbering
                    ring_text = gobjects(0);
                    ring_text2 = gobjects(0);
                    for i4 = totRings3
                        if max(max(whichRings(:,i4)))>0
                            c = find(whichRings(:,i4));
                            hold(ha,'on')
                            if length(c)>1
                                if yrTog == 1
                                    addThisLabel = 0;
                                else
                                    addThisLabel = 1;
                                end
                                xIntersect(i4) = median(c)*hpxS;
                                interpLab = interp1(c,whichRings(c,i4),round(median(c)));
                                if yrTog == 1 && i4 < max(totRings3) && length(find(userRings(:,i4+1)))>1
                                    addThisLabel = 1;
                                    if ijk == 1
                                        c2 = find(userRings(:,i4+1));
                                        xIntersect2 = median(c2)*hpxS;
                                        yIntersect2 = interp1(c2,userRings(c2,i4+1),round(median(c2)));
                                    elseif ijk == 2 && length(find(userRings2(:,i4)))
                                        c2 = find(userRings2(:,i4));
                                        xIntersect2 = median(c2)*hpxS;
                                        yIntersect2 = interp1(c2,userRings2(c2,i4),round(median(c2)));
                                    end
                                    yIntersectMean = mean([interpLab,yIntersect2]);
                                    xIntersectMean = mean([xIntersect(i4),xIntersect2]);
                                elseif yrTog == 1 && i4 < max(totRings3) && any(i4+1 == missingRings)
                                    addThisLabel = 1;
                                    % next non-missing ring:
                                    nextring = min(missingRings(missingRings>0 & missingRings>i4)-i4+1);
                                    if nextring > 0 && nextring < 99e3
                                        c2 = find(userRings(:,i4+nextring));
                                        xIntersect2 = median(c2)*hpxS;
                                        yIntersect2 = interp1(c2,userRings(c2,i4+nextring),round(median(c2)));
                                        yIntersectMean = mean([interpLab,yIntersect2]);
                                        xIntersectMean = mean([xIntersect(i4),xIntersect2]);
                                    end
                                end
                                if ijk == 1 && addThisLabel == 1
                                    if yrTog == 0
                                        ring_text(i4) = text(ha,xIntersect(i4),interpLab*pxS,num2str(i4),'Color','y','Clipping','on');
                                    elseif i4 < max(totRings3) && ~any(i4==breaksRings)
                                        ring_text(i4) = text(ha,xIntersectMean,yIntersectMean*pxS,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','y','Clipping','on');
                                    end
                                    if yrTog == 1 && any(skipsRings==i4)
                                        set(ring_text(i4),'Color','r');
                                    end
                                elseif ijk == 2 && addThisLabel == 1
                                    if yrTog == 0
                                        ring_text2(i4) = text(ha,xIntersect(i4),interpLab*pxS,['   ',num2str(i4)],'Color','c','Clipping','on');
                                    elseif i4 < max(totRings3) && ~any(i4==breaksRings)
                                        ring_text2(i4) = text(ha,xIntersectMean,yIntersectMean*pxS,['   ',num2str(inputTopYear-i4+1)],'Color','c','Clipping','on');
                                    end
                                    if yrTog == 1 && any(skipsRings==i4)
                                        set(ring_text2(i4),'Color','r');
                                    end
                                end
                            end
                            hold(ha,'off')
                        end
                    end

                else

                    smoothed_on = 1;
                    totRings3 = find(max(whichRings));
                    LDBdata = zeros(col,max(totRings3));
                    ring_filt = NaN(size(LDBdata));
                    h2d = sum(h3);
                    h2mid = ceil(length(h3(:,1))/2);
                    for i4 = totRings3
                        if max(max(whichRings(:,i4)))>0
                            c = find(whichRings(:,i4));
                            if isempty(c)
                                break
                            end
                            this_ring_interp = interp1(c,whichRings(c,i4),min(c):max(c));

                            for i5 = min(c):max(c)
                                h2x = i5-h2mid:i5-h2mid+length(h2d)-1;
                                thisH2d = h2d;
                                thisH2d(h2x < min(c)) = [];
                                h2x(h2x < min(c)) = [];
                                thisH2d(h2x > max(c)) = [];
                                h2x(h2x > max(c)) = [];
                                h2x = h2x-min(c)+1;
                                thisH2d = thisH2d./sum(thisH2d);
                                ring_filt(i5,i4) = sum(this_ring_interp(h2x).*thisH2d);
                            end
                        end
                    end
                    LDBdata = ring_filt;

                    reDrawLines(whichRings,ijk)
                    if ijk == 1
                        %set(ringsPlot,'Color',[1 0.65 0])
                        set(ringsPlot,'Color','y')
                    elseif ijk == 2
                        set(ringsPlot2,'Color','c')
                    end

                    pause(0.001)
                    hold(ha,'on')
                    xIntersect = NaN(max(totRings3),1);
                    yIntersect = NaN(max(totRings3),1);
                    try delete(ring_text)
                    catch
                    end
                    try delete(ring_text2)
                    catch
                    end
                    updatebreaksNumbering
                    ring_text = gobjects(0);
                    ring_text2 = gobjects(0);
                    for i4 = totRings3
                        if max(max(userRings(:,i4)))>0
                            c = find(userRings(:,i4));
                            hold(ha,'on')
                            if length(c)>0
                                if max(LDBdata(:,i4))>0
                                    xIntersect(i4) = median(c)*hpxS;
                                    yIntersect(i4) = (LDBdata(round(median(c)),i4))*pxS;
                                    if yrTog == 1 && i4 < max(totRings3)
                                        if max(LDBdata(:,i4+1))>0
                                            c2 = find(userRings(:,i4+1));
                                            yIntersect2 = (LDBdata(round(median(c2)),i4+1))*pxS;
                                            yIntersectMean = mean([yIntersect(i4),yIntersect2]);
                                        end
                                    end
                                    if ijk == 1
                                        if yrTog == 0
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersect(i4),num2str(i4),'Color','y','Clipping','on');
                                        elseif i4 < max(totRings3)
                                            ring_text(i4) = text(ha,xIntersect(i4),yIntersectMean,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','y','Clipping','on');
                                        end
                                        if yrTog == 1 && any(skipsRings==i4)
                                            set(ring_text(i4),'Color','r');
                                        end
                                    elseif ijk == 2
                                        if yrTog == 0
                                            ring_text2(i4) = text(ha,xIntersect(i4),yIntersectMean,['   ',num2str(i4)],'Color','c','Clipping','on');
                                        elseif i4 < max(totRings3)
                                            ring_text2(i4) = text(ha,xIntersect(i4),yIntersect(i4),['   ',num2str(inputTopYear-i4+1+breaksRingsCumSum(i4))],'Color','c','Clipping','on');
                                        end
                                        if yrTog == 1 && any(skipsRings==i4)
                                            set(ring_text2(i4),'Color','r');
                                        end
                                    end
                                end
                            end
                            hold(ha,'off')
                        end
                    end
                end
            end
            end

            drawnow;

            function reDrawLines(whichRings,whichType)
                if haveLims == 0
                    xs = [min([1:row].*hpxS),max([1:row].*hpxS)];
                    ys = [min([1:layers].*pxS),max([1:layers].*pxS)];
                else
                    ys = get(ha,'YLim');
                    xs = get(ha,'XLim');
                    haveLims = 1;
                end
                hold(ha,'on')
                ring_lines = [NaN,NaN];
                counter = 1;
                if ct == 1
                    totRings3 = find(max(max(whichRings)));
                else
                    totRings3 = find(max(whichRings));
                end
                if ct == 1
                    for i4 = totRings3'
                        if max(max(whichRings(:,:,i4)))>0
                            r = find(ldbDraw(:,slab,i4));
                            if length(r)>0
                                for i6 = 1:length(r)
                                    counter = counter+1;
                                    ring_lines(counter,:) = [r(i6)*hpxS,(layers-ldbDraw(r(i6),slab,i4))*pxS];
                                end
                                ring_lines(counter+1,:) = [NaN,NaN];
                                counter = counter+1;
                            end
                        end
                    end
                else
                    for i4 = totRings3
                        if max(whichRings(:,i4))>0
                            if smoothed_on == 0
                                c = find(whichRings(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,whichRings(c,i4)*pxS];
                            else
                                c = find(LDBdata(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,LDBdata(c,i4)*pxS];
                            end
                            ring_lines(counter+1+length(c),:) = [NaN,NaN];
                            counter = counter+length(c)+1;
                        end
                    end
                end
                ring_lines(ring_lines(:,2) > ys(2),:) = NaN;
                ring_lines(ring_lines(:,1) > xs(2),:) = NaN;
                ring_lines(ring_lines(:,2) < ys(1),:) = NaN;
                ring_lines(ring_lines(:,1) < xs(1),:) = NaN;
                if whichType == 1
                    ringsPlot = plot(ha,ring_lines(:,1),ring_lines(:,2),'-','Color','y');
                elseif whichType == 2
                    ringsPlot2 = plot(ha,ring_lines(:,1),ring_lines(:,2),'-','Color','c');
                end
                if length(ring_lines)>2
                    interpRingsPlotted = 1;
                end
                hold(ha,'off')
            end

        end


