        % Function to update display of image and intersections of rings
        function drawAndLabelRings

            set(lblLoading,'Visible','on')
            pause(0.01)

            smoothed_on = 0;
            topOfRing = 1;

            if max(max(max(userRings)))>0
                totRings3 = find(max(max(userRings)));
                LDBdata = zeros(row,col,max(totRings3));
                for i4 = totRings3'
                    if max(max(userRings(:,:,i4)))>0
                        [r,c] = find(userRings(:,:,i4));
                        if ~isempty(r)
                            v = zeros(1,length(r));
                            for j2 = 1:length(r)
                                v(j2) = userRings(r(j2),c(j2),i4);
                            end
                            warning('off','all');
                            if length(round(griddata(r,c,v,rowMesh,colMesh)))>1
                                LDBdata(:,:,i4) = permute(round(griddata(r,c,v,rowMesh,colMesh)),[2,1,3]);
                            end
                            warning('on','all');
                        end
                    end
                end

                LDBdata(isnan(LDBdata)) = 0;
                ldbDraw = LDBdata;

                dispSlab
                pause(0.001)
                hold(ha,'on')
                xIntersect = NaN(max(totRings3),1);
                yIntersect = NaN(max(totRings3),1);
                try delete(ring_text)
                catch
                end
                try delete(ring_text)
                catch
                end
                updatebreaksNumbering
                ring_text = gobjects(0);
                for i4 = totRings3'
                    if max(max(userRings(:,:,i4)))>0
                        [r,c] = find(LDBdata(:,slab,i4));
                        hold(ha,'on')
                        if length(r)>0
                            if max(max(LDBdata(:,:,i4)))>0
                                xIntersect(i4) = median(r)*hpxS;
                                yIntersect(i4) = (LDBdata(round(median(r)),slab,i4)-layers)*-pxS;
                                if yrTog == 1 && i4 < max(totRings3)
                                    if max(LDBdata(:,:,i4+1))>0
                                        [r2,c2] = find(LDBdata(:,slab,i4));
                                        yIntersect2 = (LDBdata(round(median(r2)),slab,i4+1)-layers)*-pxS;
                                        yIntersectMean = mean([yIntersect(i4),yIntersect2]);
                                    end
                                end
                                if yrTog == 0
                                    ring_text(i4) = text(ha,xIntersect(i4),yIntersect(i4),num2str(i4),'Color','yellow','Clipping','on');
                                else
                                    ring_text(i4) = text(ha,xIntersect(i4),yIntersectMean,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','yellow','Clipping','on');
                                end
                                if yrTog == 1 && any(skipsRings==i4)
                                    set(ring_text(i4),'Color','r');
                                end
                            end
                        end
                        hold(ha,'off')
                    end
                end
            else
                dispSlab
            end
            if dimMode ~=1
                if smoothedRingsDrawn == 0
                    set(dispSmoothRingsIn,'Visible','on')
                    set(dispInterpClicksIn,'Visible','off')
                else
                    set(dispSmoothRingsIn,'Visible','off')
                    set(dispInterpClicksIn,'Visible','on')
                end
            end

            if strcmp(detectMode,'seasonal')

                totRings32 = find(max(max(userRings2)));
                LDBdata2 = zeros(row,col,max(totRings32));
                for i4 = totRings32'
                    if max(max(userRings2(:,:,i4)))>0
                        [r,c] = find(userRings2(:,:,i4));
                        if ~isempty(r)
                            v = zeros(1,length(r));
                            for j2 = 1:length(r)
                                v(j2) = userRings2(r(j2),c(j2),i4);
                            end
                            warning('off','all');
                            if length(round(griddata(r,c,v,rowMesh,colMesh)))>1
                                LDBdata2(:,:,i4) = permute(round(griddata(r,c,v,rowMesh,colMesh)),[2,1,3]);
                            end
                            warning('on','all');
                        end
                    end
                end

                LDBdata2(isnan(LDBdata2)) = 0;
                ldbDraw2 = LDBdata2;

                topOfRingHold = topOfRing;
                topOfRing = 0;
                dispSlab
                pause(0.001)
                hold(ha,'on')
                xIntersect2 = NaN(max(totRings32),1);
                yIntersect2 = NaN(max(totRings32),1);
                try delete(ring_text2)
                catch
                end
                try delete(ring_text2)
                catch
                end
                updatebreaksNumbering
                ring_text2 = gobjects(0);
                for i4 = totRings32'
                    if max(max(userRings2(:,:,i4)))>0
                        [r,c] = find(LDBdata2(:,slab,i4));
                        hold(ha,'on')
                        if length(r)>0
                            if max(max(LDBdata2(:,:,i4)))>0
                                xIntersect2(i4) = median(r)*hpxS;
                                yIntersect2(i4) = (LDBdata2(round(median(r)),slab,i4)-layers)*-pxS;
                                if yrTog == 1 && i4 < max(totRings3)
                                    if max(LDBdata2(:,:,i4+1))>0
                                        [r2,c2] = find(LDBdata2(:,slab,i4));
                                        yIntersect22 = (LDBdata2(round(median(r2)),slab,i4+1)-layers)*-pxS;
                                        yIntersectMean = mean([yIntersect2(i4),yIntersect22]);
                                    end
                                end
                                if yrTog == 0
                                    ring_text2(i4) = text(ha,xIntersect2(i4),yIntersect2(i4),num2str(i4),'Color','c','Clipping','on');
                                else
                                    ring_text2(i4) = text(ha,xIntersect2(i4),yIntersectMean,num2str(inputTopYear-i4+1+breaksRingsCumSum(i4)),'Color','c','Clipping','on');
                                end
                                if yrTog == 1 && any(skipsRings==i4)
                                    set(ring_text2(i4),'Color','r');
                                end
                            end
                        end
                        hold(ha,'off')
                    end
                end
                topOfRing = topOfRingHold;
            end

            %smoothedRingsDrawn = 0;
            set(lblLoading,'Visible','off')
        end


        function drawAndLabelSmoothedRings

            set(lblLoading,'Visible','on')
            pause(0.01)

            if max(max(max(userRings)))>0
                totRings3 = find(max(max(userRings)));
                LDBdata = zeros(row,col,length(userRings(1,1,1:max(totRings3))));
                ring_filt4plot = zeros(size(LDBdata));
                surf_filt = h3;
                for i4 = totRings3'
                    if max(max(userRings(:,:,i4)))>0
                        [r,c] = find(userRings(:,:,i4));
                        if isempty(r)
                            break
                        end
                        v = zeros(1,length(r));
                        for j2 = 1:length(r)
                            v(j2) = userRings(r(j2),c(j2),i4);
                        end
