            end
            try delete(ring_text)
            catch
            end
            updatebreaksNumbering
            ring_text = gobjects(0);
            for i4 = totRings3
                if max(max(userRings(:,i4)))>0 || dimMode == 1
                    c = find(userRings(:,i4));
                    hold(ha,'on')
                    if length(c)>1 || dimMode == 1
                        if yrTog == 1
                            addThisLabel = 0;
                        else
                            addThisLabel = 1;
                        end
                        if dimMode == 2
                            xIntersect(i4) = median(c)*hpxS;
                            interpLab = interp1(c,userRings(c,i4),round(median(c)));
                            if yrTog == 1 && i4 < max(totRings3) && length(find(userRings(:,i4+1)))>1
                                addThisLabel = 1;
