        function drawAndLabelSmoothedRingsXray
            set(lblLoading,'Visible','on')
            pause(0.01)

            smoothed_on = 1;
            totRings3 = find(max(userRings));
            LDBdata = zeros(col,max(totRings3));
            ring_filt = NaN(size(LDBdata));
            h2d = sum(h3);
            h2mid = ceil(length(h3(:,1))/2);
            for i4 = totRings3
                if max(max(userRings(:,i4)))>0
                    c = find(userRings(:,i4));
                    if isempty(c) || length(c) == 1
                        break
                    end
                    this_ring_interp = interp1(c,userRings(c,i4),min(c):max(c));

                    for i5 = min(c):max(c)
                        h2x = i5-h2mid:i5-h2mid+length(h2d)-1;
                        thisH2d = h2d;
                        thisH2d(h2x < min(c)) = [];
                        h2x(h2x < min(c)) = [];
                        thisH2d(h2x > max(c)) = [];
                        h2x(h2x > max(c)) = [];
                        h2x = h2x-min(c)+1;
                        thisH2d = thisH2d./sum(thisH2d);
                        ring_filt(i5,i4) = sum(this_ring_interp(h2x).*thisH2d);
                    end
                end
            end
            LDBdata = ring_filt;

            topOfRing = 1;
            dispSlab
            %set(ringsPlot,'Color',[1 0.65 0])
