        segPlot = [];
        % Function to update display of image
        function dispSlab

            if haveLims == 0
                xs = [min([1:row].*hpxS),max([1:row].*hpxS)];
                ys = [min([1:layers].*pxS),max([1:layers].*pxS)];
            else
                ys = get(ha,'YLim');
                xs = get(ha,'XLim');
                haveLims = 1;
                %set(ha,'Visible','off')
                % ha_copy = uiaxes('Position',get(ha,'Position'));
                % xInds = round(xs(1)./hpxS):round(xs(2)./hpxS);
                % yInds = round(ys(1)./pxS):round(ys(2)./pxS);
                % xInds(xInds<1) = 1;
                % xInds(xInds>row) = row;
                % yInds(yInds<1) = 1;
                % yInds(yInds>layers) = layers;
                % corePlot2 = pcolor(ha_copy,xInds.*hpxS,yInds.*pxS,slabDraw(yInds,xInds));
                % set(ha_copy,'XLim',xs,'YLim',ys)
                % axis equal
                % if ct == 1
                %     set(corePlot2,'EdgeColor','none')
                %     set(corePlot2,'EdgeColor','interp')
                % end
                % set(ha_copy,'PlotBoxAspectRatio',[1 1 1])
                % set(ha_copy,'DataAspectRatio',[1 1 1])
                % set(ha_copy,'Colormap',colormap('bone'))
                % set(ha_copy,'CLim',contra);
                % drawnow
            end
            
            interpRingsPlotted = 0;
            set(lblLoading,'Visible','on')
            if ct == 1
                slabDraw = zeros(row,1,layers);
                if strcmp(proj,'min')
                    slabDraw(:,:,1:layers)  = min(X(:,slab-thick:slab+thick,:),[],2);
                elseif strcmp(proj,'mean')
                    slabDraw(:,:,1:layers)  = mean(X(:,slab-thick:slab+thick,:),2);
                elseif strcmp(proj,'max')
                    slabDraw(:,:,1:layers)  = max(X(:,slab-thick:slab+thick,:),[],2);
                end
                slabDraw = permute(slabDraw,[3,1,2]);
            end
            if ct == 1 && topOfRing == 1
                xInds = round(xs(1)./hpxS):round(xs(2)./hpxS);
                yInds = round(ys(1)./pxS):round(ys(2)./pxS);
                xInds(xInds<1) = [];
                xInds(xInds>row) = [];
                yInds(yInds<1) = [];
                yInds(yInds>layers) = [];
                %hold off
                %axis equal
                %if sum(get(ha,'DataAspectRatio')==[1,1,1])<3 || range(get(ha,'XLim')) ~= range(get(ha,'YLim'))
                %set(ha,'DataAspectRatio',[1,1,1]);
                axis(ha,'equal')
                %end
            %ha_copy = copyobj(ha,UserFig)
                corePlot = pcolor(ha,xInds.*hpxS,yInds.*pxS,slabDraw(yInds,xInds));
                ys = get(ha,'YLim');
                xs = get(ha,'XLim');
                haveLims = 1;
                set(ha,'YColor','white')
                ylabel('mm')
                scalebar = patch(ha,xs(1)+[range(xs)*0.05, range(xs)*0.05, range(xs)*0.05+scale_mm,...
                    range(xs)*0.05+scale_mm, range(xs)*0.05],...
                    ys(1)+[range(ys)*0.03, range(ys)*0.035, range(ys)*0.035,...
                    range(ys)*0.03, range(ys)*0.03],themeColor1,'EdgeColor','none');
                scalebar1 = patch(ha,xs(1)+[range(xs)*0.05, range(xs)*0.05, range(xs)*0.055,...
                    range(xs)*0.055, range(xs)*0.05],...
                    ys(1)+[range(ys)*0.02, range(ys)*0.045, range(ys)*0.045,...
                    range(ys)*0.02, range(ys)*0.02],themeColor1,'EdgeColor','none');
                scalebar2 = patch(ha,xs(1)+[range(xs)*0.045+scale_mm, range(xs)*0.045+scale_mm, range(xs)*0.05+scale_mm,...
                    range(xs)*0.05+scale_mm, range(xs)*0.045+scale_mm],...
                    ys(1)+[range(ys)*0.02, range(ys)*0.045, range(ys)*0.045,...
                    range(ys)*0.02, range(ys)*0.02],themeColor1,'EdgeColor','none');
                scaleText = text(ha,xs(1)+range(xs)*0.06+scale_mm,...
                    ys(1)+range(ys)*0.03,'1 mm','FontSize',textscale*12,'FontWeight','bold',...
                    'Color',themeColor1,'VerticalAlignment','bottom');
            elseif ct == 0 && topOfRing == 1
                corePlot = imagesc(ha,[1:col].*hpxS,[1:layers].*pxS,(slabDraw));
                ys = get(ha,'YLim');
                xs = get(ha,'XLim');
                %axis(ha,'equal')
                %haveLims = 1;
                scalebar = patch(ha,xs(1)+[range(xs)*0.05, range(xs)*0.05, range(xs)*0.05+scale_mm,...
                    range(xs)*0.05+scale_mm, range(xs)*0.05],...
                    ys(2)-[range(ys)*0.03, range(ys)*0.035, range(ys)*0.035,...
                    range(ys)*0.03, range(ys)*0.03],themeColor1,'EdgeColor','none');
                scalebar1 = patch(ha,xs(1)+[range(xs)*0.05, range(xs)*0.05, range(xs)*0.055,...
                    range(xs)*0.055, range(xs)*0.05],...
                    ys(2)-[range(ys)*0.02, range(ys)*0.045, range(ys)*0.045,...
                    range(ys)*0.02, range(ys)*0.02],themeColor1,'EdgeColor','none');
                scalebar2 = patch(ha,xs(1)+[range(xs)*0.045+scale_mm, range(xs)*0.045+scale_mm, range(xs)*0.05+scale_mm,...
                    range(xs)*0.05+scale_mm, range(xs)*0.045+scale_mm],...
                    ys(2)-[range(ys)*0.02, range(ys)*0.045, range(ys)*0.045,...
                    range(ys)*0.02, range(ys)*0.02],themeColor1,'EdgeColor','none');
                scaleText = text(ha,xs(1)+range(xs)*0.06+scale_mm,...
                    ys(2)-range(ys)*0.03,'1 mm','FontSize',textscale*12,'FontWeight','bold',...
                    'Color',themeColor1,'VerticalAlignment','bottom');
            end

            if topOfRing == 1
                if strcmp(sectionName,'')
                    dispTitleName = treeName;
                else
                    dispTitleName = [treeName,' ',sectionName];
                end
                dispTitleName0 = double(dispTitleName);
                idxUnderScore = find(dispTitleName0==95);
                if length(idxUnderScore)
                    dispTitleName = [];
                    idxUnderScore = [0, idxUnderScore];
                    for jjj = 2:length(idxUnderScore)
                        dispTitleName = [dispTitleName, dispTitleName0(idxUnderScore(jjj-1)+1:idxUnderScore(jjj)-1),92, 95];
                    end
                    dispTitleName = char([dispTitleName, dispTitleName0(idxUnderScore(jjj)+1:end)]);
                else
                    %dispTitleName = treeName;
                end

                title(dispTitleName,'Color',themeColor1)
            end
            
            hold(ha,'on')
            ring_lines = [NaN,NaN];
            counter = 1;
            if ct == 1
                if topOfRing == 1
                    totRings3 = find(max(max(userRings)));
                else
                    totRings3 = find(max(max(userRings2)));
                end
            else
                if topOfRing == 1
                    totRings3 = find(max(userRings));
                else
                    totRings3 = find(max(userRings2));
                end
            end
            if ct == 1
                for i4 = totRings3'
                    if topOfRing == 1
                        if max(max(userRings(:,:,i4)))>0
                            r = find(ldbDraw(:,slab,i4));
                            if length(r)>0
                                for i6 = 1:length(r)
                                    counter = counter+1;
                                    ring_lines(counter,:) = [r(i6)*hpxS,(layers-ldbDraw(r(i6),slab,i4))*pxS];
                                end
                                ring_lines(counter+1,:) = [NaN,NaN];
                                counter = counter+1;
                            end
                        end
                    else
                        if max(max(userRings2(:,:,i4)))>0
                            r = find(ldbDraw2(:,slab,i4));
                            if length(r)>0
                                for i6 = 1:length(r)
                                    counter = counter+1;
                                    ring_lines(counter,:) = [r(i6)*hpxS,(layers-ldbDraw2(r(i6),slab,i4))*pxS];
                                end
                                ring_lines(counter+1,:) = [NaN,NaN];
                                counter = counter+1;
                            end
                        end
                    end
                end
            else
                for i4 = totRings3
                    if topOfRing == 1
                        if max(userRings(:,i4))>0
                            if smoothed_on == 0
                                c = find(userRings(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,userRings(c,i4)*pxS];
                            else
                                c = find(LDBdata(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,LDBdata(c,i4)*pxS];
                            end
                            ring_lines(counter+1+length(c),:) = [NaN,NaN];
                            counter = counter+length(c)+1;
                        end
                    else
                        if max(userRings2(:,i4))>0
                            if smoothed_on == 0
                                c = find(userRings2(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,userRings2(c,i4)*pxS];
                            else
                                c = find(LDBdata(:,i4));
                                ring_lines(counter+1:counter+length(c),:) = [c*hpxS,LDBdata(c,i4)*pxS];
                            end
                            ring_lines(counter+1+length(c),:) = [NaN,NaN];
                            counter = counter+length(c)+1;
                        end
                    end
                end
            end
            ring_lines(ring_lines(:,2) > ys(2),:) = NaN;
            ring_lines(ring_lines(:,1) > xs(2),:) = NaN;
            ring_lines(ring_lines(:,2) < ys(1),:) = NaN;
            ring_lines(ring_lines(:,1) < xs(1),:) = NaN;
            if dimMode ~= 1
                if topOfRing == 1
                    ringsPlot = plot(ha,ring_lines(:,1),ring_lines(:,2),'-','Color','y');
                else
                    ringsPlot2 = plot(ha,ring_lines(:,1),ring_lines(:,2),'-','Color','c');
                end
            end
            if length(ring_lines)>2
                interpRingsPlotted = 1;
            end
            hold(ha,'off')

            if ct == 1
                set(corePlot,'EdgeColor','none')
                set(corePlot,'EdgeColor','interp')
                set(ha,'Colormap',colormap('bone'))
            end
            set(ha,'PlotBoxAspectRatio',[1 1 1])
            set(ha,'DataAspectRatio',[1 1 1])
            set(ha,'CLim',contra);

            if length(treeROI) > 1
                hold(ha,'on')
                measArea = plot(ha,[treeROI(:,1);treeROI(1,1)],[treeROI(:,2);treeROI(1,2)],'r-','LineWidth',2);
                hold(ha,'off')
            end

            drawnow
            %set(ha,'Visible','on')
            % if exist('ha_copy')
            %     delete(ha_copy)
            % end

            set(lblLoading,'Visible','off')
            if haveLims==1
                set(ha,'YLim',ys)
                set(ha,'XLim',xs)
            end
            if ct == 1
                circlePlot
            end
        end

        % Function to display axial image
        function circlePlot

            %set(UserFig,'CurrentAxes',ha2);
            %axes(ha2)
            if j>1 && (max(max(temp_rings))>0 || max(max(max(userRings(:,:,j-1:j))))>0)

                if (max(max(temp_rings))>0 || max(max(userRings(:,:,j)))>0)
                    plot_rings = zeros(row,col,2);
                    plot_rings(:,:,1) = temp_rings;
                    plot_rings(:,:,2) = userRings(:,:,j);
                    these_user_rings = max(plot_rings,[],3);
                    title_num = num2str(j);
                    %coreSampLayer = round(median(these_user_rings(find(these_user_rings>0))));
                else
                    these_user_rings = userRings(:,:,j-1);
                    title_num = num2str(j-1);
                end
                coreSampLayer = round(median(these_user_rings(find(these_user_rings>0))));
                p_axial = pcolor(ha2,X(:,:,layers-coreSampLayer)');
                title(ha2,sprintf('ring %s',title_num),'Color',themeColor1);
                %set(ha2,'XLim',xs)
                [r_blue,c_blue] = find(these_user_rings>0);
                hold(ha2,'on')
                b_points = plot(ha2,r_blue,c_blue,'.','Color','y','MarkerSize',10);
                hold(ha2,'off')
            elseif j==1 && (max(max(temp_rings))>0 || max(max(max(userRings(:,:,j))))>0)
                plot_rings = zeros(row,col,2);
                plot_rings(:,:,1) = temp_rings;
                plot_rings(:,:,2) = userRings(:,:,j);
                these_user_rings = max(plot_rings,[],3);
                coreSampLayer = round(median(these_user_rings(find(these_user_rings>0))));
                p_axial = pcolor(ha2,X(:,:,layers-coreSampLayer)');
                title(ha2,sprintf('ring %s',num2str(j)),themeColor1);
                [r_blue,c_blue] = find(these_user_rings>0);
                hold(ha2,'on')
                b_points = plot(ha2,r_blue,c_blue,'.','Color','y','MarkerSize',10);
                hold(ha2,'off')
            else
                coreSampLayer = round(layers/2);
                p_axial = pcolor(ha2,X(:,:,coreSampLayer)');
            end
            set(p_axial,'EdgeColor','none')
            set(p_axial,'EdgeColor','interp')
            set(ha2,'PlotBoxAspectRatio',[1 1 1])
            set(ha2,'DataAspectRatio',[1 1 1])
            set(ha2,'Colormap',colormap('bone'))
            set(ha2,'CLim',contra);

            filteredCore = imfilter(X(:,:,layers+1-coreSampLayer), h2, 'replicate');
            coreSamp = imbinarize((filteredCore-min(min(filteredCore)))/max(max(filteredCore-min(min(filteredCore)))).*255);

            [ro,co] = find(coreSamp);

            [val,loc] = max(ro);
            tops = [co(loc),ro(loc)];
            [val,loc] = min(ro);
            bottoms = [co(loc),ro(loc)];
            [val,loc] = max(co);
            rights = [co(loc),ro(loc)];
            [val,loc] = min(co);
            lefts = [co(loc),ro(loc)];

            offsets = mean([rights(1)-lefts(1),tops(2)-bottoms(2)])*0.15;
            set(ha2,'Xtick',[],'Ytick',[],'CLim',contra,'XLim',...
                round([lefts(1)-offsets rights(1)+offsets]),'YLim',round([bottoms(2)-offsets tops(2)+offsets]))
            our_box = [1,slab-thick/2; 1,slab+thick/2; col,slab+thick/2; col,slab-thick/2; 1,slab-thick/2];
            hold(ha2,'on')
            p_box = plot(ha2,our_box(:,1),our_box(:,2),'r-','LineWidth',1);
            circle_j = j;
            % circle plot
            rad = max([rights(1)-lefts(1),tops(2)-bottoms(2)])/1.7;
            this_center = [mean([rights(1),lefts(1)]),slab];
            these_angles = linspace(+pi/(180/x_ang_new), pi+pi/(180/x_ang_new), 500);
            arc_x = rad * cos(these_angles) + this_center(1);
            arc_y = rad * sin(these_angles) + this_center(2);
            p_arc = plot(ha2,arc_x,arc_y,'-','Color','m');
            ticks_set = [0,45,90,135,180];
            ticks_plot = ticks_set+x_ang_new;
            for i2 = 1:length(ticks_set)
                dummy_x = linspace(rad*cosd(ticks_plot(i2))+this_center(1),this_center(1),100);
                dummy_y = linspace(rad*sind(ticks_plot(i2))+this_center(2),this_center(2),100);
                p_degrees = plot(ha2,[dummy_x(1),dummy_x(7)],[dummy_y(1),dummy_y(7)],'k-','Color','m');
                t_degrees = text(ha2,dummy_x(14),dummy_y(14),num2str(ticks_set(length(ticks_set)+1-i2)),...
                    'FontSize',textscale*9,'Color','m','HorizontalAlignment','center','FontWeight','bold','FontName','Arial');
            end
            hold(ha2,'off')
            drawnow
        end

        function checkOut = checkDone

            checkOut = areWeDone;

        end


        currentYlim = [];
        currentXlim = [];

        interpRingsPlotted = 0;
        x = [];
        y = [];
        lastPoint = [];
        lastPoint2 = [];

        function click_Callback(source,eventdata)

            x1 = [];
            y1 = [];

            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
            iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));

            pause(0.02)

            clickingMode

            pause(0.02)

            % if interpRingsPlotted == 1
            %     set(hideInterpIn,'Visible','on')
            %     set(showInterpIn,'Visible','off')
            % end

            if strcmp(get(autoEnableIn,'Visible'),'on')
                isEnableVis = 1;
                set(autoEnableIn,'Visible','off')
            else
                isEnableVis = 0;
            end


            function mouse_click(src,eventData)
                % get coordinates of click
                coords = eventData.IntersectionPoint;
                x1 = coords(1);
                y1 = coords(2);
                uiresume(UserFig)
            end

            pause(0.02)
            currentYlim = get(ha,'YLim');
            currentXlim = get(ha,'XLim');
            pause(0.02)

            try
                hz.Enable = 'off';
                hp.Enable = 'off';
            catch
                pause(1)
                try
                    hz.Enable = 'off';
                    hp.Enable = 'off';
                catch
                    pause(10)
                    try
                        hz.Enable = 'off';
                        hp.Enable = 'off';
                    catch
                        pause(30)
                        try
                            hz.Enable = 'off';
                            hp.Enable = 'off';
                        catch
                        end
                    end
                end
            end

            %zoomPostCallback

            ha.InteractionOptions.ZoomSupported = "off";
            ha.InteractionOptions.PanSupported = "off";

            set(lblCheck,'Visible','off')
            set(lblDeleted,'Visible','off')

            areWeDone = 0;

            if ct == 1
                temp_rings = zeros(row,col);
                temp_rings_idx = zeros(row,col);
            else
                temp_rings = zeros(1,size(userRings,1));
                temp_rings_idx = zeros(1,size(userRings,1));
            end

            j = j+1;
            if any(j==missingRings)
                while any(j==missingRings)
                    j = j+1;
                end
            end

            if ct == 1
                circlePlot
            end

            x = [];
            y = [];
            b = [];
            b1 = 1;
            rings = 0;
            apply_auto = 1;

            add2circle = 0;
            hold(ha,'on')
            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            b1 = 1;

            set(drawDeleteBox1In,'Visible','off')
            set(UndoLastClickIn,'Visible','off')

            pause(0.02)

            while areWeDone == 0

                if yrTog == 0
                    textClick = sprintf('Currently on ring %s',num2str(round(j)));
                else
                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                    textClick = sprintf('Currently on top of ring %s',num2str(inputTopYear-round(j)+1+breaksRingsCumSum(j)));
                end
                set(lblClick,'String',textClick)
                if mult_rings == 0 && ringType == 1
                    set(lblClick,'ForeGroundColor','y')
                elseif mult_rings == 0 && ringType == 2
                    set(lblClick,'ForeGroundColor','c')
                else
                    set(lblClick,'ForeGroundColor',themeColor1)
                end

                pause(0.01);
                if areWeDone == 1
                    set(lblClick,'String',' ')
                    break
                end

                if (length(~isnan(xIntersect))+length(find(xIntersect==0)))<1
                    newRot = 0;
                end

                pointsFromIntersect = 0;
                if ct == 1
                    if j <= length(xIntersect)
                        if newRot == 1 && isnan(xIntersect(j)) == 0 && xIntersect(j) ~= 0 && autoDetectionToggle == 1
                            % simulate click on ring intersection
                            apply_auto = 1;
                            x1 = xIntersect(j);
                            y1 = yIntersect(j);
                            pointsFromIntersect = 1;
                            b1 = 1;
                            xIntersect(j) = NaN;
                            yIntersect(j) = NaN;
                        else
                            set(0, 'CurrentFigure', UserFig);
                            set(corePlot,'ButtonDownFcn',@mouse_click)
                            set(ringsPlot,'ButtonDownFcn',@mouse_click)
                            uiwait(UserFig);
                            set(corePlot,'ButtonDownFcn','')
                            set(ringsPlot,'ButtonDownFcn','')
                        end
                    else
                        set(0, 'CurrentFigure', UserFig);
                        set(corePlot,'ButtonDownFcn',@mouse_click)
                        set(ringsPlot,'ButtonDownFcn',@mouse_click)
                        uiwait(UserFig);
                        set(corePlot,'ButtonDownFcn','')
                        set(ringsPlot,'ButtonDownFcn','')
                    end
                else
                    set(0, 'CurrentFigure', UserFig);
                    set(corePlot,'ButtonDownFcn',@mouse_click)
                    set(ringsPlot,'ButtonDownFcn',@mouse_click)
                    uiwait(UserFig);
                    set(corePlot,'ButtonDownFcn','')
                    set(ringsPlot,'ButtonDownFcn','')
                end

                if add2circle == 0
                    iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                    iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                end

                if ct == 1
                    plotcirc = 1;
                end

                if apply_auto==1 && autoDetectionToggle == 1 && ~isempty(y1)
                    iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                    iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                    if y1/pxS < layers && y1/pxS > 0 && x1/hpxS < col && x1/hpxS > 0
                        proposed_rings = ringDetection(x1,y1);
                        for kjj = 1:size(proposed_rings,3)
                            if j>=0
                                p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'y-','LineWidth',2);
                                if yrTog == 0
                                    prop_text(kjj) = text(ha,proposed_rings(end,1,kjj).*hpxS+hpxS*10,proposed_rings(end,2,kjj).*pxS,num2str(kjj),'Color','y','FontSize',textscale*12,'Clipping','on');
                                else
                                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                    prop_text(kjj) = text(ha,proposed_rings(end,1,kjj).*hpxS+hpxS*10,proposed_rings(end,2,kjj).*pxS,strcat('\downarrow',num2str(inputTopYear-kjj+1+breaksRingsCumSum(kjj))),'Color','y','FontSize',textscale*12,'Clipping','on');
                                end
                            else
                                p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'c-','LineWidth',2);
                                if yrTog == 0
                                    prop_text(kjj) = text(ha,proposed_rings(end,1,kjj).*hpxS+hpxS*10,proposed_rings(end,2,kjj).*pxS,num2str(kjj),'Color','c','FontSize',textscale*12,'Clipping','on');
                                else
                                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                    prop_text(kjj) = text(ha,proposed_rings(end,1,kjj).*hpxS+hpxS*10,proposed_rings(end,2,kjj).*pxS,strcat('\downarrow',num2str(inputTopYear-kjj+1+breaksRingsCumSum(kjj))),'Color','c','FontSize',textscale*12,'Clipping','on');
                                end
                            end
                        end
                        if strcmp(detectMode,'seasonal')
                            topOfRing = 0;
                            proposed_rings2 = ringDetection(x1,y1);
                            for kjj = 1:size(proposed_rings2,3)
                                p_prop2(kjj) = plot(ha,proposed_rings2(:,1,kjj).*hpxS,proposed_rings2(:,2,kjj).*pxS,'c-','LineWidth',2);
                                if yrTog == 0
