                y1 = coords(2);
                uiresume(UserFig)
            end

            pause(0.01)
            currentYlim = get(ha,'YLim');
            currentXlim = get(ha,'XLim');
            pause(0.01)

            try
                hz.Enable = 'off';
                hp.Enable = 'off';
            catch
                pause(1)
                try
                    hz.Enable = 'off';
                    hp.Enable = 'off';
                catch
                    pause(10)
                    try
                        hz.Enable = 'off';
                        hp.Enable = 'off';
                    catch
                        pause(30)
                        try
                            hz.Enable = 'off';
                            hp.Enable = 'off';
                        catch
                        end
                    end
                end
            end

            ha.InteractionOptions.ZoomSupported = "off";
            ha.InteractionOptions.PanSupported = "off";

            set(lblCheck,'Visible','off')
            set(lblDeleted,'Visible','off')

            areWeDone = 0;

            temp_rings = zeros(row,col);
            temp_rings_idx = zeros(row,col);

            j = j+1;
            if any(j==missingRings)
                while any(j==missingRings)
                    j = j+1;
                end
            end

            circlePlot

            x = [];
            y = [];
            b = [];
            b1 = 1;
            rings = 0;
            apply_auto = 1;

            add2circle = 0;
            hold(ha,'on')
            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            try iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            catch
                try iptSetPointerBehavior(segPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
                catch
                end
            end
            b1 = 1;

            set(drawDeleteBox1In,'Visible','off')
            set(UndoLastClickIn,'Visible','off')

            pause(0.01)

            if yrTog == 0
                textClick = sprintf('Currently on ring %s',num2str(round(j)));
            else
                breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                textClick = sprintf('Currently on top of ring %s',num2str(inputTopYear-round(j)+1+breaksRingsCumSum(j)));
            end
            set(lblClick,'String',textClick)
            if mult_rings == 0 && ringType == 1
                set(lblClick,'ForeGroundColor','y')
            elseif mult_rings == 0 && ringType == 2
                set(lblClick,'ForeGroundColor','c')
            else
                set(lblClick,'ForeGroundColor',themeColor1)
            end

            set(0, 'CurrentFigure', UserFig);
            set(corePlot,'ButtonDownFcn',@mouse_click)
            try set(ringsPlot,'ButtonDownFcn',@mouse_click)
            catch
                try set(segPlot,'ButtonDownFcn',@mouse_click)
                catch
                end
            end
            uiwait(UserFig);
            set(corePlot,'ButtonDownFcn','')
            try set(ringsPlot,'ButtonDownFcn','')
            catch
                try set(segPlot,'ButtonDownFcn','')
                catch
                end
            end

            if length(x1)==1
                lastPoint = scatter(ha,x1,y1,100,3000);
            end
            pause(0.01)

            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
            try iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
            catch
                try iptSetPointerBehavior(segPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                catch
                end
            end
            if y1/pxS < layers && y1/pxS > 0 && x1/hpxS < col && x1/hpxS > 0
                topOfRing = 1;
                proposed_rings = ringDetection(x1,y1);
                replotMulti
            end
            delete(lastPoint)

            functionsOff
            acceptRejectMultiOn
            adjustRingDetect_fun
            % allows accept all, reject all, dialog box to remove some

            uiwait(UserFig);

            acceptRejectMultiOff
            cancelAdjustRingDetect_fun

            pause(0.01)
            
            if acceptMultiToggle == 1
                if length(goodRingsMulti) > 0

                    % these are the ring numbers to be assigned to
                    goodRingsNums = intersect(goodRingsMultiPlot,goodRingsMulti);

                    % indices of proposed rings to use
                    bnds_idx = 1:size(proposed_rings,3);
                    bnds_exclude = setdiff(goodRingsMultiPlot,goodRingsMulti);
                    bnds_idx(find(ismember(goodRingsMultiPlot,bnds_exclude))) = [];

                    for kjj = 1:length(goodRingsNums)
                        this_ring_num = goodRingsNums(kjj);
                        this_ring_idx = bnds_idx(kjj);
                        this_idx = find(~isnan(proposed_rings(:,1,this_ring_idx)));
                        new_x = proposed_rings(this_idx,1,this_ring_idx);
                        new_y = proposed_rings(this_idx,2,this_ring_idx);
                        if ct
                            userRings(new_x,slab-1:slab+1,this_ring_num) = repmat(layers-round(new_y),[1,3]);
                        else
                            userRings(new_x,this_ring_num) = new_y;
                        end
                        if dimMode == 1
                            get1Dintersections
                            userRings(new_x,this_ring_num) = 0;
                        end
                    end
                    if strcmp(detectMode,'seasonal')

                        % these are the ring numbers to be assigned to
                        goodRingsNums2 = sort(intersect(goodRingsMultiPlot2,goodRingsMulti2),'ascend');

                        % indices of proposed rings to use
                        bnds_idx = 1:size(proposed_rings2,3);
                        bnds_exclude = setdiff(goodRingsMultiPlot2,goodRingsMulti2);
                        bnds_idx(find(ismember(goodRingsMultiPlot2,bnds_exclude))) = [];

                        for kjj = 1:length(goodRingsNums2)
                            this_ring_num = goodRingsNums2(kjj);
                            this_ring_idx = bnds_idx(kjj);
                            this_idx = find(~isnan(proposed_rings2(:,1,this_ring_idx)));
                            new_x = proposed_rings2(this_idx,1,this_ring_idx);
                            new_y = proposed_rings2(this_idx,2,this_ring_idx);
                            if ct
                                userRings2(new_x,slab-1:slab+1,this_ring_num) = repmat(layers-round(new_y),[1,3]);
                            else
                                userRings2(new_x,this_ring_num) = new_y;
                            end
                            if dimMode == 1
                                get1Dintersections2
                                userRings2(new_x,this_ring_num) = 0;
                            end
                        end
                    end
                    j = this_ring_num;
                    try delete(prop_text);
                        clearvars prop_text
                    catch
                    end
                    try delete(p_prop);
                        clearvars p_prop
                    catch
                    end
                    try delete(prop_text2);
                        clearvars prop_text2
                    catch
                    end
                    try delete(p_prop2);
                        clearvars p_prop2
                    catch
                    end
                    if dimMode ~= 1
                        updateRingLines
                    else
                        drawAndLabelRingsXray
                    end

                end
            else
                try delete(prop_text);
                    clearvars prop_text
                catch
                end
                try delete(p_prop);
                    clearvars p_prop
                catch
                end
                try delete(prop_text2);
                    clearvars prop_text2
                catch
                end
                try delete(p_prop2);
                    clearvars p_prop2
                catch
                end
            end

            functionsOn
