        function replotMulti(source,eventdata)
            goodInput = 1;
            try str2num(excludeMultiIn.String)+1;
            catch
                goodInput = 0;
            end
            if goodInput == 1
                try delete(prop_text);
                    clearvars prop_text
                catch
                end
                try delete(p_prop);
                    clearvars p_prop
                catch
                end
                try delete(prop_text2);
                    clearvars prop_text2
                catch
                end
                try delete(p_prop2);
                    clearvars p_prop2
                catch
                end
                goodRingsMulti = j:j+size(proposed_rings,3)-1;
                goodRingsMultiPlot = goodRingsMulti;
                goodRingsList = zeros(size(goodRingsMultiPlot));
                for kjj = 1:length(goodRingsMultiPlot)
                    if any(goodRingsMultiPlot(kjj)==missingRings)
                        while any(goodRingsMultiPlot(kjj)==missingRings)
                            goodRingsMultiPlot(kjj:end) = goodRingsMultiPlot(kjj:end)+1;
                            goodRingsList(kjj:end) = goodRingsList(kjj:end)+1;
                        end
                    end
                end
                if yrTog == 0
                    exlRings = str2num(excludeMultiIn.String);
                else
                    exlRings = inputTopYear-str2num(excludeMultiIn.String)+1+breaksRingsCumSum(kjj);
                end
                goodRingsMulti = j:j+size(proposed_rings,3)-1+max(goodRingsList);
                goodRingsMulti(ismember(goodRingsMulti,exlRings)) = [];
                for kjj = 1:size(proposed_rings,3)
                    if dimMode == 2
                        if ismember(goodRingsMultiPlot(kjj),goodRingsMulti)
                            p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'y-','LineWidth',2);
                            if yrTog == 0
                                prop_text(kjj) = text(ha,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),2,kjj).*pxS,num2str(goodRingsMultiPlot(kjj)),'Color','y','FontSize',textscale*12,'Clipping','on','BackGroundColor',[0,0,0,0.5]);
                            else
                                breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                prop_text(kjj) = text(ha,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),2,kjj).*pxS,strcat('\downarrow',num2str(inputTopYear-goodRingsMultiPlot(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot(kjj)))),'Color','y','FontSize',textscale*12,'Clipping','on','BackGroundColor',[0,0,0,0.5]);
                            end
                        else
                            p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'r-','LineWidth',2);
                            if yrTog == 0
                                prop_text(kjj) = text(ha,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),2,kjj).*pxS,num2str(goodRingsMultiPlot(kjj)),'Color','r','FontSize',textscale*12,'Clipping','on','BackGroundColor',[1,1,1,0.5]);
                            else
                                breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                prop_text(kjj) = text(ha,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),2,kjj).*pxS,strcat('\downarrow',num2str(inputTopYear-goodRingsMultiPlot(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot(kjj)))),'Color','r','FontSize',textscale*12,'Clipping','on','BackGroundColor',[1,1,1,0.5]);
                            end
                        end
                    else
                        [xi,yi] = polyxpoly(line_segments(:,1),line_segments(:,2),proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS);
                        if length(xi)>0
                            if ismember(goodRingsMultiPlot(kjj),goodRingsMulti)
                                p_prop(kjj) = plot(ha,xi,yi,'y','LineWidth',2);
                                if length(goodRingsMultiPlot) >= kjj
                                    if yrTog == 0
                                        prop_text(kjj) = text(ha,xi+range(currentXlim)*0.0,yi,['  ',num2str(goodRingsMultiPlot(kjj))],'Color','y','FontSize',textscale*14,'FontWeight','bold','Clipping','on','BackGroundColor','none');
                                    else
                                        breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                        prop_text(kjj) = text(ha,xi+range(currentXlim)*0.0,yi,['  ',num2str(inputTopYear-goodRingsMultiPlot(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot(kjj)))],'Color','y','FontSize',textscale*14,'FontWeight','bold','Clipping','on','BackGroundColor','none');
                                    end
                                end
                            else
                                p_prop(kjj) = plot(ha,xi,yi,'ro','LineWidth',2);
                                if length(goodRingsMultiPlot) >= kjj
                                    if yrTog == 0
                                        prop_text(kjj) = text(ha,xi+range(currentXlim)*0.0,yi,['  ',num2str(goodRingsMultiPlot(kjj))],'Color','r','FontSize',textscale*14,'FontWeight','bold','Clipping','on','BackGroundColor','none');
                                    else
                                        breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                        prop_text(kjj) = text(ha,xi+range(currentXlim)*0.0,yi,['  ',num2str(inputTopYear-goodRingsMultiPlot(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot(kjj)))],'Color','r','FontSize',textscale*14,'FontWeight','bold','Clipping','on','BackGroundColor','none');
                                    end
                                end
                            end
                        end
                    end
                    % if max(kjj==goodRingsMulti-goodRingsList-j+1) == 0
                    %     set(p_prop(kjj),'Color','r')
                    %     set(prop_text(kjj),'Color','r')
                    % end
                end
                if strcmp(detectMode,'seasonal')
                    topOfRing = 0;
                    proposed_rings2 = ringDetection(x1,y1);
                    goodRingsMulti2 = j:1:j+size(proposed_rings2,3)-1;
                    goodRingsMultiPlot2 = goodRingsMulti2;
                    goodRingsList2 = zeros(size(goodRingsMultiPlot2));
                    for kjj = 1:length(goodRingsMultiPlot2)
                        if any(goodRingsMultiPlot2(kjj)==missingRings)
                            while any(goodRingsMultiPlot2(kjj)==missingRings)
                                goodRingsMultiPlot2(kjj:end) = goodRingsMultiPlot2(kjj:end)+1;
                                goodRingsList2(kjj:end) = goodRingsList2(kjj:end)+1;
                            end
                        end
                    end
                    if yrTog == 0
                        exlRings = str2num(excludeMultiIn.String);
                    else
                        if str2num(excludeMultiIn.String)>=0
                            exlRings = [];%inputTopYear-str2num(excludeMultiIn.String)+1;
                        else
                            exlRings = -(inputTopYear-abs(str2num(excludeMultiIn.String))+1);
                        end
                    end
                    goodRingsMulti2 = j:1:j+size(proposed_rings2,3)-1+max(goodRingsList2);
                    goodRingsMulti2(ismember(goodRingsMulti2,-exlRings)) = [];
                    for kjj = 1:size(proposed_rings2,3)
                        if dimMode == 2
                            if ismember(goodRingsMultiPlot2(kjj),goodRingsMulti2)
                                p_prop2(kjj) = plot(ha,proposed_rings2(:,1,kjj).*hpxS,proposed_rings2(:,2,kjj).*pxS,'c-','LineWidth',2);
                                if yrTog == 0
                                    prop_text2(kjj) = text(ha,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),2,kjj).*pxS,['   ',num2str(goodRingsMultiPlot2(kjj))],'Color','c','FontSize',textscale*12,'Clipping','on','BackGroundColor',[0,0,0,0.5]);
                                else
                                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                    prop_text2(kjj) = text(ha,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),2,kjj).*pxS,['   ',num2str(inputTopYear-goodRingsMultiPlot2(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot2(kjj)))],'Color','c','FontSize',textscale*12,'Clipping','on','BackGroundColor',[0,0,0,0.5]);
                                end
                            else
                                p_prop2(kjj) = plot(ha,proposed_rings2(:,1,kjj).*hpxS,proposed_rings2(:,2,kjj).*pxS,'r-','LineWidth',2);
                                if yrTog == 0
                                    prop_text2(kjj) = text(ha,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),2,kjj).*pxS,strcat('\downarrow',num2str(goodRingsMultiPlot2(kjj))),'Color','r','FontSize',textscale*12,'Clipping','on','BackGroundColor',[1,1,1,0.5]);
                                else
                                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                                    prop_text2(kjj) = text(ha,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings2(max(find(~isnan(proposed_rings2(:,1,kjj)))),2,kjj).*pxS,strcat('\downarrow',num2str(inputTopYear-goodRingsMultiPlot2(kjj)+1+breaksRingsCumSum(goodRingsMultiPlot2(kjj)))),'Color','r','FontSize',textscale*12,'Clipping','on','BackGroundColor',[1,1,1,0.5]);
                                end
                            end
                        else
                            [xi,yi] = polyxpoly(line_segments(:,1),line_segments(:,2),proposed_rings2(:,1,kjj).*hpxS,proposed_rings2(:,2,kjj).*pxS);
                            if length(xi)>0
                                if ismember(goodRingsMultiPlot2(kjj),goodRingsMulti2)
                                    p_prop2(kjj) = plot(ha,xi,yi,'c','LineWidth',2);
                                    if length(goodRingsMultiPlot2) >= kjj
                                        if yrTog == 0
                                            prop_text2(kjj) = text(ha,xi+range(currentXlim)*0.0,yi,['     ',num2str(goodRingsMultiPlot2(kjj))],'Color','c','FontSize',textscale*14,'FontWeight','bold','Clipping','on','BackGroundColor','none');
                                        else
