        function acceptRejectMultiOn
            set(acceptMultiIn,'Visible','on')
            set(rejectMultiIn,'Visible','on')
            set(replotMultiIn,'Visible','on')
            set(excludeMultiIn,'Visible','on')
            set(recountMultiIn,'Visible','on')
        end

        function acceptRejectMultiOff
            set(acceptMultiIn,'Visible','off')
            set(rejectMultiIn,'Visible','off')
            set(replotMultiIn,'Visible','off')
            set(excludeMultiIn,'Visible','off','String','exclude rings')
            set(recountMultiIn,'Visible','off')
        end

        function clickXray_Callback(source,eventdata)

            mult_rings = 0;

            x1 = [];
            y1 = [];

            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
            iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));

            pause(0.01)

            clickingMode

            pause(0.01)

            if strcmp(get(autoEnableIn,'Visible'),'on')
                isEnableVis = 1;
                set(autoEnableIn,'Visible','off')
            else
                isEnableVis = 0;
            end

            if interpRingsPlotted == 1
                set(hideInterpIn,'Visible','on')
                set(showInterpIn,'Visible','off')
            end

            function mouse_click(src,eventData)
                % get coordinates of click
                coords = eventData.IntersectionPoint;
                x1 = coords(1);
                y1 = coords(2);
                uiresume(UserFig)
            end

            pause(0.01)
            currentYlim = get(ha,'YLim');
            currentXlim = get(ha,'XLim');
            pause(0.01)

            try
                hz.Enable = 'off';
                hp.Enable = 'off';
            catch
                pause(1)
                try
                    hz.Enable = 'off';
                    hp.Enable = 'off';
                catch
                    pause(10)
                    try
                        hz.Enable = 'off';
                        hp.Enable = 'off';
                    catch
                        pause(30)
                        try
                            hz.Enable = 'off';
                            hp.Enable = 'off';
                        catch
                        end
                    end
                end
            end

            ha.InteractionOptions.ZoomSupported = "off";
            ha.InteractionOptions.PanSupported = "off";

            set(lblCheck,'Visible','off')
            set(lblDeleted,'Visible','off')

            areWeDone = 0;

            if ringType == 2
                topOfRing = 0;
            elseif ringType == 1
                topOfRing = 1;
            end

            %if j >= 0
                j = j+1;
                if any(j==missingRings)
                    while any(j==missingRings)
                        j = j+1;
                    end
                end
            % else
            %     j = j-1;
            %     topOfRing = 0;
            %     if any(j==missingRings)
            %         while any(j==missingRings)
            %             j = j-1;
            %         end
            %     end
            % end

            x = [];
            y = [];
            b = [];
            apply_auto = 1;

            hold(ha,'on')
            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
            b1 = 1;

            pause(0.01)

            while areWeDone == 0

                if yrTog == 0
                    textClick = sprintf('Currently on ring %s',num2str(round(j)));
                else
                    breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
                    textClick = sprintf('Currently on top of ring %s',num2str(inputTopYear-round(j)+1+breaksRingsCumSum(j)));
                end
                set(lblClick,'String',textClick)
                if mult_rings == 0 && ringType == 1
                    set(lblClick,'ForeGroundColor','y')
                elseif mult_rings == 0 && ringType == 2
                    set(lblClick,'ForeGroundColor','c')
                else
                    set(lblClick,'ForeGroundColor',themeColor1)
                end

                pause(0.01);
                if areWeDone == 1
                    set(lblClick,'String',' ')
                    break
                end

                set(0, 'CurrentFigure', UserFig);
                set(corePlot,'ButtonDownFcn',@mouse_click)
                set(ringsPlot,'ButtonDownFcn',@mouse_click)
                uiwait(UserFig);
                set(corePlot,'ButtonDownFcn','')
                set(ringsPlot,'ButtonDownFcn','')

                if length(x1)==1
                lastPoint = scatter(ha,x1,y1,100,3000);
                end
                pause(0.01)

                if apply_auto==1 && autoDetectionToggle == 1 && length(x1)==1
                    iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                    iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'watch'));
                    if y1/pxS < layers && y1/pxS > 0 && x1/hpxS < col && x1/hpxS > 0
                        proposed_rings = ringDetection(x1,y1);
                        for kjj = 1:size(proposed_rings,3)
                            if ringType == 1
                                p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'y','LineWidth',2);
                            elseif ringType == 2
                                p_prop(kjj) = plot(ha,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'c','LineWidth',2);
                            end
                            %prop_text(kjj) = text(ha,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),1,kjj).*hpxS+hpxS*0,proposed_rings(max(find(~isnan(proposed_rings(:,1,kjj)))),2,kjj).*pxS,num2str(kjj),'Color','m','FontSize',textscale*12,'Clipping','on','BackGroundColor','w');
                        end
                    end
                    breakLoop = 0;
                    continueAuto = 0;
                    acceptProposed = 0;
                    acceptRejectOn
                    set(calibrateProposedIn,'Visible','on')
                    while breakLoop == 0
                        pause(0.1)
                        apply_auto = 0;
                        if acceptProposed == 1
                            clickingMode
                            x1 = proposed_rings(:,1)'.*hpxS;
                            y1 = proposed_rings(:,2)'.*pxS;

                            try set(p_prop,'Visible','off')
                            catch
                            end
                            [xPlot, idxPlot] = sort(proposed_rings(:,1));
                            plot(ha,xPlot.*hpxS,proposed_rings(idxPlot,2).*pxS,'-','Color','white')

                            if continueAuto == 1
                                breakLoop = 1;
                                apply_auto = 1;
                            elseif continueAuto == 0
                                breakLoop = 1;
                                apply_auto = 0;
                            end
                        end
                        if acceptProposed == 2
                            clickingMode
                            try set(p_prop,'Visible','off')
                            catch
                            end
                            if continueAuto == 1
                                breakLoop = 1;
                                apply_auto = 1;
                            elseif continueAuto == 0
                                breakLoop = 1;
                                apply_auto = 0;
                                set(redoRingIn,'Visible','off')
                            end
                        end
                    end
                    set(calibrateProposedIn,'Visible','off')

                    acceptProposed = 0;

                    totRings = max([length(find(max(userRings))>0),j]);

                    iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
                    iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
                    clearvars proposed_rings
                end
                acceptProposed = 0;

                if need2delete == 1
                    inds4deletion = find(x>area2delete(1) & x<area2delete(1)+area2delete(3) &...
                        y>area2delete(2) & y<area2delete(2)+area2delete(4));
                    clicksDeleted = plot(ha,x(inds4deletion),y(inds4deletion),'yx','markersize',15);
                    x(inds4deletion) = [];
                    y(inds4deletion) = [];
                    set(clicksDeleted,'ButtonDownFcn',@mouse_click)
                    need2delete = 0;
                    delete(roi)
                end

                if length(x1)>0
                    if autoDetectionToggle == 0
                        set(UndoLastClickIn,'Visible','on')
                        set(drawDeleteBox1In,'Visible','on')
                    end
                end

                x = [x x1];
                y = [y y1];
                b = [b b1];

                totRings = max([length(find(max(userRings))>0),j]);

                iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));
                iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'custom', 'PointerShapeCData', ring_pointer, 'PointerShapeHotSpot', ring_pointer_hotspot));

            end

            set(lblLoading,'Visible','on')
            iptSetPointerBehavior(corePlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'arrow'));
            iptSetPointerBehavior(ringsPlot, @(UserFig, currentPoint)set(UserFig, 'Pointer', 'arrow'));
            if oops == 0
                [xSort,idx] = sort(x);
                ySort = y(idx);
                %hold(ha,'on')
                %plot(ha,xSort,ySort,'-','Color','white')
                %hold(ha,'off')
                %drawnow
                
                if j >= 0
                    if any((j+1)==missingRings)
                        while any((j+1)==missingRings)
                            j = j+1;
                        end
                    end
                    if yrTog == 0
                        textClick = sprintf('Next ring will be ring %s',num2str(round(j+1)));
                    else
                        updatebreaksNumbering
                        textClick = sprintf('Next ring will be top of %s',num2str(inputTopYear-round(j+1)+1+breaksRingsCumSum(j+1)));
                    end
                else
                    if any((j-1)==missingRings)
                        while any((j-1)==missingRings)
                            j = j-1;
                        end
                    end
                    if yrTog == 0
                        textClick = sprintf('Next ring will be ring %s',num2str(round(j+1)));
                    else
                        updatebreaksNumbering
                        textClick = sprintf('Next ring will be top of %s',num2str((inputTopYear-abs(round(j+1))+1+breaksRingsCumSum(j+1))));
                    end
                end

                set(lblClick,'String',textClick,'ForeGroundColor',themeColor1)

                if ringType == 1
                    userRings(round(x/hpxS),j) = round(y/pxS);
                else
                    userRings2(round(x/hpxS),j) = round(y/pxS);
                end

                % keep track of how many rings identified for whole core
                clicks = length(b(b==1)) + length(b(b==3));
                if j>0
                    totRings = max([length(find(max(userRings))>0),j-1]);
                    if j > totRings && clicks > 1
                        totRings = max([length(find(max(userRings))>0),j]);
                    end
                else
                end

                pause(0.01)
                save(fullfile(fileOpen,name2search), 'userRings','x_ang','TreeTracerversion','contra','proj','thick','h3_width','h3_std','h3_defined','line_segments','ringMarks1D','missingRings','detectMode','ringMarks1D2','userRings2','treeROI','inputTopYear','breaksRings','skipsRings');

                updateRingLines
                
                set(lblLoading,'Visible','off')
                %hold(ha,'on')
                %text(x(1),y(1),num2str(j),'Color','white','Clipping','on')
                %hold(ha,'off')

            else
                hold(ha,'on')
                oops = 0;
                plot(ha,x,y,'yx','markersize',15)
                hold(ha,'off')
                j = j-1;
                click_Callback
            end
            set(lblLoading,'Visible','off')
            defaultMode
            %ha.InteractionOptions.ZoomSupported = "on";
            %ha.InteractionOptions.PanSupported = "on";
            set(UndoLastClickIn,'Visible','off')
            if isEnableVis == 1
                set(autoEnableIn,'Visible','on')
            end
        end

        howManyTimesGoneBack = 0;
        finishIn = [];
