            save(fullfile(fileOpen,name2search), 'userRings','x_ang','TreeTracerversion','contra','proj','thick','h3_width','h3_std','h3_defined','line_segments','ringMarks1D','missingRings','detectMode','ringMarks1D2','userRings2','treeROI','inputTopYear','breaksRings','skipsRings');

