                process_notesIn.Value{1} = 'none';
            end

            function textEntered(textarea)
                val = textarea.Value;
                % Check each element of text area cell array for text
                for k = 1:length(val)
                    if(~isempty(val{k}))
                        notes_entered = 1;
                        break;
                    end
                end
            end

            finishIn = uicontrol(UserFig,'Style','pushbutton',...
                'String',{'Send outputs to TreeTrove server'},'Visible','on',...
                'Position',figscale*[400,100,350,40],'Units','normalized','BackgroundColor',[0.61,0.86,0.57],....
                'ForegroundColor',[0,0,0],'FontSize',textscale*14,'FontName','Arial','Callback',@finish_fun);

            requestYearAgain = uicontrol(UserFig,'Style','text','String',...
                'Please estimate the top calendar year in YYYY format',...
                'Visible','off','Position',figscale*[375,150,400,25],'Units','normalized',...
                'ForegroundColor',themeColor2,'FontSize',textscale*12,'FontName','Arial',...
                'BackgroundColor',[0 0 0]);

            requestNotesAgain = uicontrol(UserFig,'Style','text','String',...
                'Are you sure you do not want to enter any notes?',...
