                'ForegroundColor',themeColor2,'FontSize',textscale*12,'FontName','Arial',...
                'BackgroundColor',[0 0 0]);

            deletePrevOutputs = uicheckbox(UserFig,'Text','Delete your previous output files',...
                'Value',0,'Position',figscale*[420,30,250,25],...
                'FontSize',textscale*14,'FontName','Arial','FontColor',themeColor2);

            makeLiPDIn = uicheckbox(UserFig,'Text','Create LiPD file',...
                'Value',0,'Position',figscale*[420,60,250,25],'Visible','off',...
                'FontSize',14,'FontName','Arial','FontColor',themeColor2);

            calcColorsIn = uicheckbox(UserFig,'Text','Calculate ring colors',...
                'Value',0,'Position',figscale*[700,420,250,25],...
                'FontSize',textscale*18,'FontName','Arial','FontColor',themeColor2);

            if ct
                set(calcColorsIn,'Visible','off')
            end

            this_bib0 = '';
            try dirRowCite = find(strcmp(treeDir.textdata(:,1),treeName));
                this_bib0 = treeDir.textdata{dirRowCite,10};
            catch
            end

            if any(strcmp(saveFileName,dataOwners),2) && length(this_bib0)>3
                set(makeLiPDIn,'Visible','on')
            end

            inputTopYear = 0; % not sure if this is a problem
            overRideNotes = 0;

            function finish_fun(source,eventdata)
                try inputTopYear = str2num(topRingYearIn.String)
                    if inputTopYear>-99e3 && inputTopYear<2040
                        set(requestYearAgain,'Visible','off')
                        if notes_entered == 1
                            % if howManyTimesGoneBack>0
                            %     for ij = 1:howManyTimesGoneBack
                            %         uiwait(UserFig)
                            %     end
                            % end
                            %uiresume(UserFig)
