                        elseif overRideNotes == 1
                            % if howManyTimesGoneBack>0
                            %     for ij = 1:howManyTimesGoneBack
                            %         uiwait(UserFig)
                            %     end
                            % end
                            %uiresume(UserFig)
                            finishProcess
                        else
                            set(requestNotesAgain,'Visible','on')
                            set(finishIn,'String','Press again to proceed')
                            overRideNotes = 1;
                        end
                    else
                        set(requestYearAgain,'Visible','on')
                    end
                catch
                    %set(requestYearAgain,'Visible','on')
                end
            end
            functionsOn
        end

        

        function finishProcess
            %uiwait(UserFig)

            set(finishIn,'Visible','off')
            set(requestNotesAgain,'Visible','off')
            set(goBackIn,'Visible','off')
            set(deletePrevOutputs,'Visible','off')
            set(makeLiPDIn,'Visible','off')
            set(calcColorsIn,'Visible','off')

            set(requestYearAgain,'Visible','off')
            set(topRingYearText,'Visible','off')
            set(topRingYearIn,'Visible','off')
            if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
                set(process_notesIn,'Visible','off')
                set(labelEnterNotes,'Visible','off')
            end
            set(confidenceRings,'Visible','off')
            set(labelEnterConfidence,'Visible','off')
            set(lblLoading,'Visible','on')

            pause(0.01)

            try
                if serverChoice == 1
                    cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password);
                elseif serverChoice == 2
                    cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password);
                elseif serverChoice == 3
                    cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                end
            catch
                try
                    if serverChoice == 1
                        cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password);
                    elseif serverChoice == 2
                        cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password);
                    elseif serverChoice == 3
                        cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                    end
                catch
                    try
                        connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                        connectionEstablished = 0;
                        for ij = 1:length(connectTimes)
                            if connectionEstablished == 0
                                if connectTimes(ij) == 1
                                    waitText = [' ',num2str(connectTimes(ij)),' minute.']
                                else
                                    waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                                end
                                set(lblOpeningError,'Units','Pixels','Visible','on','Position',figscale*[200,130,500,40],...
                                    'String',{'Error connecting to server.';strcat('Trying again in',waitText)},...
                                    'Units','normalized')
                                pause(connectTimes(ij)*60)
                                try
                                    if serverChoice == 1
                                        cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password)
                                    elseif serverChoice == 2
                                        cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password)
                                    elseif serverChoice == 3
                                        cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                                    end
                                    connectionEstablished = 1;
                                    set(lblOpeningError,'Units','Pixels','Visible','off',...
                                        'Position',figscale*[200,150,500,20],'Units','normalized')
                                catch
                                end
                            end
                        end
                        if connectionEstablished == 0
                            zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                        end
                    catch
                        set(lblOpeningError,'Units','Pixels','Position',figscale*[200,130,500,40],'Visible','on',...
                            'String',{'Error connecting to server. (code 011)';'Please try again later.'},...
                            'Units','normalized')
                        while 1==1
                            pause
                        end
                    end
                end
            end
            if strcmp('',thisSectionName)
                server_path = strcat(h_drive,treeDir.textdata{dirRow,3},'/',...
                    treeDir.textdata{dirRow,4},'/',thisTreeName);
            else
                server_path = strcat(h_drive,'/',treeDir.textdata{dirRow,3},'/',...
                    treeDir.textdata{dirRow,4},'/',thisTreeName,'/',thisSectionName);
            end
            if serverChoice == 1 || serverChoice == 3
                server_path(double(server_path)==32) = 95; % converts spaces to _
            end
            cd(cache2,server_path)

            % Before saving, check if we are working on a core that has
            % multiple sections.
            if strcmp('',sectionName) % no sections
                % set directory to this tree's folder on server
                mput(cache2,fullfile(fileOpen,strcat(saveName,treeName,'.mat')));
            else % yes, sections
                % set directory to this sections's folder on server
                mput(cache2,fullfile(fileOpen,strcat(saveName,treeName,'_',sectionName,'.mat')));
            end

            %if ct == 1
                ha3 = uiaxes(UserFig,'Units','Pixels','Position',figscale*[200,160,500,50],'Units','normalized','Visible','off');
                ha3.InteractionOptions.DatatipsSupported = 'off';
                ha3.InteractionOptions.ZoomSupported = "off";
                ha3.InteractionOptions.PanSupported = "off";
                ha3.Toolbar.Visible = 'off';
                hold(ha3,'on')
                set(ha3,'Xtick',[],'YTick',[],'XLim',[0 1],'YLim',[0 1])
                processingGrowth = 1;
            %end

            set(lblLoading,'Visible','off')

            if strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')
                if ct == 1
                    set(ha3,'Units','Pixels','Position',figscale*[300,30,500,50],'Units','normalized')
                    dispVid = uihtml(UserFig);
                    dispVid.Position = [figscale*250,figscale*100,700,700];
                    dispVid.HTMLSource = (fullfile('loading_movies',strcat('ct_movie1.html')));
                    set(UserFig,'Color','k')
                    set(lblLoading,'BackGroundColor','k')
                else
                    dispVid = uihtml(UserFig);
                    dispVid.Position = [figscale*250,figscale*250,500,500];
                    rng('shuffle')
                    rand_vid = round(rand(1)*(n_loading_vids-1))+1;
                    dispVid.HTMLSource = (fullfile('loading_movies',strcat('ct_movie1',num2str(rand_vid),'.html')));
                    lblVideo = uicontrol(UserFig,'Style','text','String',videoLabel(rand_vid),'Position',figscale*[200,250,500,20],...
                        'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none');
                end
            end

            pause(0.001)

            if ct == 1
                set(ha3,'Visible','on')
                x_ang_old = x_ang_new;
                % update 'x_ang_new' with user's selected rotation
                x_ang_new = 0;
                % calculate difference between previous and new rotation
                x_ang_dif = x_ang_new-x_ang_old;
                % rotate 'X' (the CT scan data)
                X = imrotate3(X,x_ang_dif,[0,0,1],'linear','crop','FillValues',-1000);
                % rotate userRings
                userRings = imrotate3(userRings,x_ang_dif,[0,0,1],'nearest','crop','FillValues',0);

                % flip upside down to work with extension_rate function
                % (measure from top down)
                userRings(userRings==0) = NaN;
                userRings = layers-userRings;
                userRings(isnan(userRings)) = 0;

                userRings2(userRings2==0) = NaN;
                userRings2 = layers-userRings2;
                userRings2(isnan(userRings2)) = 0;

                buildCore
                
                try 

                    doingSeasonal = 0;

                    % First, annual ring widths

                    % remove missing ring blanks
                    missingPos = missingRings(missingRings>0);
                    missingPos = sort(missingPos,'ascend');
                    userRings(:,:,missingPos) = [];

                    currentLoadingTitle = 'Annual ring widths';
                    extension_rate
                    
                    % get density between rings
                    densityBetweenRings
                    density_total = densityTotal;

                    % add back in missing ring blanks
                    for iij = 1:length(missingPos)
                        userRings(:,:,missingPos(iij)+1:end+1) = userRings(:,:,missingPos(iij):end);
                        userRings(:,:,missingPos(iij)) = 0;
                    end

                    % add blanks into extension data
                    for iij = 1:length(missingPos)
                        extension(missingPos(iij)+1:end+1,:) = extension(missingPos(iij):end,:);
                        extension(missingPos(iij),:) = 0;
                    end

                    % add blanks into density data
                    for iij = 1:length(missingPos)
                        density_total(missingPos(iij)+1:end+1) = density_total(missingPos(iij):end);
                        density_total(missingPos(iij)) = 0;
                    end

                    % Now, do seasonal if that mode is on
                    if strcmp(detectMode,'seasonal')

                        doingSeasonal = 1;

                        % remove missing ring blanks
                        missingPos = missingRings(missingRings>0);
                        missingPos = sort(missingPos,'ascend');

                        missingNeg = missingRings(missingRings<0);
                        missingNeg = sort(missingNeg,'descend');

                        userRings(:,:,missingPos) = [];
                        userRings2(:,:,-missingNeg) = [];

                        % save to new variable
                        extension_annual = extension;

                        % hold on to existing data
                        hold_rings1 = userRings;
                        hold_rings2 = userRings2;

                        % initialize new userRings
                        userRings = NaN(size(userRings,1),size(userRings,2),size(userRings,3)*3);
                        
                        % fill in, alternating from top to bottom of rings
                        list1 = 1:2:size(hold_rings1,3)*2;
                        for jjkk = 1:length(list1)
                            userRings(:,:,list1(jjkk)) = hold_rings1(:,:,jjkk);
                        end
                        list2 = 2:2:size(hold_rings2,3)*2;
                        for jjkk = 1:length(list2)
                            userRings(:,:,list2(jjkk)) = hold_rings2(:,:,jjkk);
                        end

                        % get extension and density
                        currentLoadingTitle = 'Late-wood widths';
                        extension_rate
                        currentLoadingTitle = 'Late-wood density';
                        densityBetweenRings

                        % pull out the late wood data (odds)
                        extension_late = extension(1:2:size(extension,1),:);
                        density_late = densityTotal(1:2:end);

                        % add blanks into extension data
                        for iij = 1:length(missingNeg)
                            extension_late(-missingNeg(iij)+1:end+1,:) = extension_late(-missingNeg(iij):end,:);
                            extension_late(-missingNeg(iij),:) = 0;
                        end

                        % add blanks into density data
                        for iij = 1:length(missingNeg)
                            density_late(-missingNeg(iij)+1:end+1) = density_late(-missingNeg(iij):end);
                            density_late(-missingNeg(iij)) = 0;
                        end
                        

                        % now, early wood

                        % initialize new userRings
                        userRings = NaN(size(userRings,1),size(userRings,2),size(userRings,3));
                        
                        % fill in, alternating from top to bottom of rings
                        %userRings(:,:,1:2:size(hold_rings2,2)*2) = hold_rings2;
                        %userRings(:,:,2:2:size(hold_rings1(:,2:end),2)*2) = hold_rings1(:,2:end);
                        list1 = 1:2:size(hold_rings2,3)*2;
                        for jjkk = 1:length(list1)
                            userRings(:,:,list1(jjkk)) = hold_rings2(:,:,jjkk);
                        end
                        list2 = 0:2:size(hold_rings1,3)*2;
                        for jjkk = 2:length(list2)-1
                            userRings(:,:,list2(jjkk)) = hold_rings1(:,:,jjkk);
                        end

                        % get extension and colors
                        currentLoadingTitle = 'Early-wood widths';
                        extension_rate
                        currentLoadingTitle = 'Early-wood density';
                        densityBetweenRings

                        % pull out the early wood data (odds)
                        extension_early = extension(1:2:size(extension,1),:);
                        density_early = densityTotal(1:2:end);

                        % add blanks into extension data
                        for iij = 1:length(missingPos)
                            extension_early(missingPos(iij)+1:end+1,:) = extension_early(missingPos(iij):end,:);
                            extension_early(missingPos(iij),:) = 0;
                        end

                        % add blanks into density data
                        for iij = 1:length(missingPos)
                            density_early(missingPos(iij)+1:end+1) = density_early(missingPos(iij):end);
                            density_early(missingPos(iij)) = 0;
                        end

                        % assign back annual extension to regular variable
                        % name for consistency with code below
                        extension = extension_annual;

                    end

                catch
                    % something is wrong with the rings such as out of
                    % order or missing numbers or crossing
                    youMessedUp = uicontrol(UserFig,'Style','text','String',...
                        'Error with rings, cannot process. (code 023)',...
                        'Visible','on','Position',figscale*[375,90,400,25],'Units','normalized',...
                        'ForegroundColor',themeColor2,'FontSize',textscale*12,'FontName','Arial',...
                        'BackgroundColor',[0 0 0]);
                    pause
                    while 1 ~= 2
                        pause
                    end
                end

            else

                set(ha3,'Visible','on')

                % crop userRings to measurement area (main rings)
                if length(treeROI) > 2
                    existingRings = find(max(userRings));
                    for kjj = existingRings
                        idx_this_ring = find(userRings(:,kjj));
                        out_poly = ~inpolygon(idx_this_ring,userRings(idx_this_ring,kjj),treeROI(:,1)./hpxS,treeROI(:,2)./pxS);
                        userRings(idx_this_ring(out_poly),kjj) = 0;
                    end

                    % delete any rings that are all NaN now
                    inds2remove = [];
                    for kjj = existingRings
                        if nansum(userRings(:,kjj)) < 2
                            inds2remove = [inds2remove;kjj];
                        end
                    end
                    userRings(:,inds2remove) = [];

                    % crop userRings to measurement area (bottom rings)
                    existingRings2 = find(max(userRings2));
                    for kjj = existingRings2
                        idx_this_ring = find(userRings2(:,kjj));
                        out_poly = ~inpolygon(idx_this_ring,userRings2(idx_this_ring,kjj),treeROI(:,1)./hpxS,treeROI(:,2)./pxS);
                        userRings2(idx_this_ring(out_poly),kjj) = 0;
                    end

                    % delete any rings that are all NaN now
                    inds2remove = [];
                    for kjj = existingRings2
                        if nansum(userRings2(:,kjj)) < 2
                            inds2remove = [inds2remove;kjj];
                        end
                    end
                    userRings2(:,inds2remove) = [];
                end

                % flip upside down to work with extension_rate function
                % (measure from top down)
                userRings(userRings==0) = NaN;
                userRings = layers-userRings;
                userRings(isnan(userRings)) = 0;

                userRings2(userRings2==0) = NaN;
                userRings2 = layers-userRings2;
                userRings2(isnan(userRings2)) = 0;

                if dimMode == 2

                    doingSeasonal = 0;

                    % First, annual ring widths

