                    currentLoadingTitle = 'Annual ring widths';
                    extension_rate_Xray
                    
                    % get colors between rings
                    if calcColorsIn.Value == 1
                        currentLoadingTitle = 'Annual ring colors';
                        colorsBetweenRings
                        colors_total = colorsTotal;
                    end

                    % add back in missing ring blanks
                    for iij = 1:length(missingPos)
                        userRings(:,missingPos(iij)+1:end+1) = userRings(:,missingPos(iij):end);
                        userRings(:,missingPos(iij)) = 0;
                    end

                    % add blanks into extension data
                    for iij = 1:length(missingPos)
                        extension(missingPos(iij)+1:end+1,:) = extension(missingPos(iij):end,:);
                        extension(missingPos(iij),:) = 0;
                    end

                    % add blanks into color data
