                    if strcmp(detectMode,'seasonal')

                        doingSeasonal = 1;

                        % remove missing ring blanks
                        missingPos = missingRings(missingRings>0);
                        missingPos = sort(missingPos,'ascend');

                        missingNeg = missingRings(missingRings<0);
                        missingNeg = sort(missingNeg,'descend');

                        %for iij = 1:length(missingPos)
                            userRings(:,missingPos) = [];
                        %end
                        %for iij = 1:length(missingNeg)
                            userRings2(:,-missingNeg) = [];
                        %end

                        % save to new variable
