                        % hold on to existing data
                        hold_rings1 = userRings;
                        hold_rings2 = userRings2;

                        % initialize new userRings
                        userRings = NaN(size(userRings,1),size(userRings,2)*3);
                        
                        % fill in, alternating from top to bottom of rings
                        userRings(:,1:2:size(hold_rings1,2)*2) = hold_rings1;
                        userRings(:,2:2:size(hold_rings2,2)*2) = hold_rings2;

                        % get extension and colors
                        currentLoadingTitle = 'Late-wood widths';
                        extension_rate_Xray
                        if calcColorsIn.Value == 1
                            currentLoadingTitle = 'Late-wood colors';
                            colorsBetweenRings
                        end

                        % pull out the late wood data (odds)
                        extension_late = extension(1:2:size(extension,1),:);

                        %colors_late = colorsTotal(1:2:end,:);
                        if calcColorsIn.Value == 1
                            colors_late = colorsTotal(1:2:end,:);
                        end

                        % add blanks into extension data
                        for iij = 1:length(missingNeg)
                            extension_late(-missingNeg(iij)+1:end+1,:) = extension_late(-missingNeg(iij):end,:);
                            extension_late(-missingNeg(iij),:) = 0;
                        end

                        % add blanks into color data
                        if calcColorsIn.Value == 1
                            %missingNeg = missingNeg-1;
                            for iij = 1:length(missingNeg)
                                colors_late(-missingNeg(iij)+1:end+1,:) = colors_late(-missingNeg(iij):end,:);
                                colors_late(-missingNeg(iij),:) = 0;
                            end
                        end
                        

                        % now, early wood

                        % initialize new userRings
                        userRings = NaN(size(userRings,1),size(userRings,2));
                        
                        % fill in, alternating from top to bottom of rings
                        userRings(:,1:2:size(hold_rings2,2)*2) = hold_rings2;
                        userRings(:,2:2:size(hold_rings1(:,2:end),2)*2) = hold_rings1(:,2:end);

                        % get extension and colors
                        currentLoadingTitle = 'Early-wood widths';
                        extension_rate_Xray
                        if calcColorsIn.Value == 1
                            currentLoadingTitle = 'Early-wood colors';
                            colorsBetweenRings
                        end

                        % pull out the early wood data (odds)
                        extension_early = extension(1:2:size(extension,1),:);
                        %colors_early = colorsTotal(1:2:end,:);
                        if calcColorsIn.Value == 1
                            colors_early = colorsTotal(1:2:end,:);
                        end

                        % add blanks into extension data
                        for iij = 1:length(missingPos)
                            extension_early(missingPos(iij)+1:end+1,:) = extension_early(missingPos(iij):end,:);
                            extension_early(missingPos(iij),:) = 0;
