                            for iij = 1:length(missingPos)
                                colors_early(missingPos(iij)+1:end+1,:) = colors_early(missingPos(iij):end,:);
                                colors_early(missingPos(iij),:) = 0;
                            end
                        end

                        % assign back annual extension to regular variable
                        % name for consistency with code below
                        extension = extension_annual;
                        % if calcColorsIn.Value == 1
                        %     colors_total = colors_annual;
                        % end

                    end

                elseif dimMode == 1

                    missingPos = missingRings(missingRings>0);
                    missingPos = sort(missingPos,'ascend');

                    ringMarks1D(missingPos,:) = [];

                    currentLoadingTitle = 'Annual ring widths';
                    extension_rate_Xray1D
                    if calcColorsIn.Value == 1
                        currentLoadingTitle = 'Annual ring colors';
                        colorsBetweenRings1D
                        colors_total = colorsTotal;
                    end

                    % add back in missing ring blanks
                    for iij = 1:length(missingPos)
                        ringMarks1D(missingPos(iij)+1:end+1,:) = ringMarks1D(missingPos(iij):end,:);
                        ringMarks1D(missingPos(iij),:) = 0;
                    end

                    % add blanks into extension data
                    for iij = 1:length(missingPos)
                        extension(missingPos(iij)+1:end+1) = extension(missingPos(iij):end);
                        extension(missingPos(iij)) = 0;
                    end

                    % add blanks into color data
                    if calcColorsIn.Value == 1
                        for iij = 1:length(missingPos)
                            colors_total(missingPos(iij)+1:end+1,:) = colors_total(missingPos(iij):end,:);
                            colors_total(missingPos(iij),:) = 0;
                        end
                    end

                    % Now, do seasonal if that mode is on
                    if strcmp(detectMode,'seasonal')

                        % remove missing ring blanks
                        missingPos = missingRings(missingRings>0);
