                        %colors_annual = colorsTotal;

                        % hold on to existing data
                        hold_rings1 = ringMarks1D;
                        hold_rings2 = ringMarks1D2;

                        % initialize new ringMarks1D
                        ringMarks1D = NaN(size(ringMarks1D,1),2);
                        
                        % fill in, alternating from top to bottom of rings
                        ringMarks1D(1:2:size(hold_rings1,1)*2,:) = hold_rings1;
                        ringMarks1D(2:2:size(hold_rings2,1)*2,:) = hold_rings2;

