                        q2 = quantile(extension_late(iii,checkNaNs),0.95);
                        extension_late(iii,extension_late(iii,checkNaNs)<q1 | extension_late(iii,checkNaNs)>q2) = NaN;
                    end
                    for iii = 1:length(extension_early(:,1))
