                colors_total(end-breaksRings+1,:) = [];
                if strcmp(detectMode,'seasonal')
                    colors_early(end-breaksRings+1,:) = [];
                    colors_late(end-breaksRings+1,:) = [];
                end
            end
            if ct
                density_total(end-breaksRings+1) = [];
                if strcmp(detectMode,'seasonal')
                    density_early(end-breaksRings+1) = [];
                    density_late(end-breaksRings+1) = [];
                end
            end

            % remove the core "skips"
