        if ct == 1

            % set up slab positions: sample core for general location within image
            samp = round(layers/2);
            filteredXcore(:,:) = imfilter(X(:,:,samp), h2, 'replicate');

            treeSamp = imbinarize((filteredXcore-min(min(filteredXcore)))/max(max(filteredXcore-min(min(filteredXcore)))).*255);

            [r,c] = find(treeSamp);

            [val,loc] = max(r);
            topMost = [c(loc),r(loc)];
            [val,loc] = min(r);
            bottomMost = [c(loc),r(loc)];
            [val,loc] = max(c);
            rightMost = [c(loc),r(loc)];
            [val,loc] = min(c);
            leftMost = [c(loc),r(loc)];

            center = [round((rightMost(1)+leftMost(1))/2),round((topMost(2)+bottomMost(2))/2)];

            slab = round(mean(center));
            slabPos = slab*hpxS;

            if areWeGoingBack == 1
                slabPos = returnSlabPos*hpxS;
                slab = returnSlabPos;
            end

        end

