        function aboutCalibrate_fun(src,event)

            set(calibrateProposedIn,'Visible','off')
            set(calibrateProposedOut,'Visible','off')
            set(filterIn,'Visible','off')
            set(filtParam1In,'Visible','off')
            set(filtParam2In,'Visible','off')
            set(lblParam1,'Visible','off')
            set(lblParam2,'Visible','off')
            set(lblFilterType,'Visible','off')
            set(lblDetectMethod,'Visible','off')
            set(detectMethodIn,'Visible','off')
            % set(searchDistIn,'Visible','off')
            % set(lblSearchDist,'Visible','off')
            set(sensitivityParam1In,'Visible','off')
            set(sensitivityParam2In,'Visible','off')
            set(sensitivityParam3In,'Visible','off')
            set(lblSensitivity1,'Visible','off')
            set(lblSensitivity2,'Visible','off')
            set(lblSensitivity3,'Visible','off')
            set(aboutCalibrateIn,'Visible','off')
            set(aboutCalibrateCancelIn,'Visible','on')

            about_text_label2 = sprintf(['Automatic ring detection works by filtering the core image ' ...
                'and tracing both left and right the "valley" of low (or high) density of the ' ...
                'identified ring. This process depends on how the image is filtered (blurred), ' ...
                'and there are many ways to do that. Here, you can choose two different ' ...
                'types of filters and adjust the parameters of the filter. The idea is to ' ...
                'adjust the setting until the proposed ring (the magenta dots) fit well to the ' ...
                'ring visible on the image. Note that this feature may not work well for all ' ...
                'cores and it should not be relied up blindly. Automatic detection is meant to ' ...
                'be a convenience to enable quicker analysis of nicely-ringed trees, but trees ' ...
                'with complicated growth ring patterns or low-resolution scans will likely need to be clicked ' ...
                'on manually.']);

            set(htextAbout2,'String',about_text_label2)

            about_text_wrapped2 = textwrap(htextAbout2,{htextAbout2.String});

            set(htextAbout2,'String',about_text_label2,'Visible','on','Units','pixels',...
                'Position',figscale*[650,300,400,300],'Units','normalized','HorizontalAlignment', 'left','BackgroundColor','none','ForegroundColor','w')

        end


        function adjustRingDetect_fun(src,event)

            if mult_rings == 0
            acceptRejectOff
            set(calibrateProposedIn,'Visible','off')
            set(calibrateProposedOut,'Visible','on')
            set(aboutCalibrateIn,'Visible','on')
            set(hideInterpIn,'Visible','off')
            set(showInterpIn,'Visible','off')

            if ct == 1
                set(ha2,'Units','Pixels','Position',figscale*[875,40,200,200],'Units','normalized')
            end

            ha4 = uiaxes(UserFig,'Units','Pixels','Position',figscale*[50,50,600,600],'Units','normalized','Color','none','xcolor','k','ycolor','k');
            set(ha4,'XTick',[],'YTick',[]);
            ha4.InteractionOptions.DatatipsSupported = 'off';

            xInds = round(xs(1)./hpxS):round(xs(2)./hpxS);
            yInds = round(ys(1)./pxS):round(ys(2)./pxS);
            xInds(xInds<1) = [];
            xInds(xInds>row) = [];
            yInds(yInds<1) = [];
            yInds(yInds>layers) = [];
            %corePlot = pcolor(ha,xInds.*hpxS,yInds.*pxS,slabDraw(yInds,xInds));
            img_filt = imfilter(mean(slabDraw(yInds,xInds,:),3),h1,'replicate');

            if ct
                corePlot4 = pcolor(ha4,xInds.*hpxS,yInds.*pxS,img_filt);
            else
                corePlot4 = imagesc(ha4,xInds.*hpxS,yInds.*pxS,img_filt);
            end
            if ct
                set(corePlot4,'EdgeColor','none')
                set(corePlot4,'EdgeColor','interp')
            end
            set(ha4,'PlotBoxAspectRatio',[1 1 1])
            set(ha4,'DataAspectRatio',[1 1 1])
            set(ha4,'Colormap',colormap('bone'))
            if ct
                set(ha4,'CLim',contra)
            else
                set(ha4,'CLim',[min(img_filt,[],'all'),max(img_filt,[],'all')]);
            end
            set(ha4,'YLim',currentYlim,'XLim',currentXlim)
            hold(ha4,'on')

            proposed_rings = ringDetection(x1,y1);
            for kjj = 1:size(proposed_rings,3)
                p_prop(kjj) = plot(ha4,proposed_rings(:,1,kjj).*hpxS,proposed_rings(:,2,kjj).*pxS,'y-','LineWidth',2);
                prop_text(kjj) = text(ha4,proposed_rings(end,1,kjj).*hpxS+hpxS*10,proposed_rings(end,2,kjj).*pxS,num2str(kjj),'Color','y','FontSize',textscale*12,'Clipping','on');
            end

            drawnow
            end

            % initialize core menu
            filterIn = uicontrol(UserFig,'Style','popupmenu',...
                'Position',figscale*[850,440,150,20],'Units','normalized',...
                'String',{'gaussian','streak'},'Value',1,...
                'Callback',@chooseFilter,'Visible','on');

            detectMethodIn = uicontrol(UserFig,'Style','popupmenu',...
                'Position',figscale*[850,470,150,20],'Units','normalized',...
                'String',{'gradient','darkest','seasonal'},'Value',find(strcmp(detectMode,{'gradient','darkest','seasonal'})),...
                'Callback',@chooseMethod,'Visible','on');

            filtParam1In = uislider(UserFig,'FontColor',themeColor1,...
                'Position',figscale*[700,400,300,20],'MajorTicks',[0.5:0.5:5],...
                'Limits', [0.1,5],'Value', filt_param1,'ValueChangedFcn', @filtParam1_Callback);

            filtParam2In = uislider(UserFig,'FontColor',themeColor1,...
                'Position',figscale*[700,335,300,20],'MajorTicks',[0.25:0.25:2.5],...
                'Limits', [0.1, 2.5],'Value', filt_param2,'ValueChangedFcn', @filtParam2_Callback);

            % searchDistIn = uislider(UserFig,'FontColor',themeColor1,...
            %     'Position',figscale*[700,270,300,20],...
            %     'Limits', [pxS/10, pxS],'Value', pxS/3,'ValueChangedFcn', @searchDist_Callback);

            sensitivityParam1In = uislider(UserFig,'FontColor',themeColor1,...
                'Position',figscale*[700,270,300,20],'MajorTicks',[0.1:0.1:1],...
                'Limits', [0.1, 1],'Value', 0.8,'ValueChangedFcn', @sensitivity1_Callback);
            
            sensitivityParam2In = uislider(UserFig,'FontColor',themeColor1,...
                'Position',figscale*[700,205,300,20],'MajorTicks',[0.1:0.1:1],...
                'Limits', [0.1, 1],'Value', 0.8,'ValueChangedFcn', @sensitivity2_Callback);

            sensitivityParam3In = uislider(UserFig,'FontColor',themeColor1,...
                'Position',figscale*[700,140,300,20],'MajorTicks',[0:10:100],...
                'Limits', [0, 100],'Value', 10,'ValueChangedFcn', @sensitivity3_Callback);

            lblParam1 = uicontrol(UserFig,'Style','text','String',sprintf('Filter width: %s mm',num2str(filtParam1In.Value)),'Position',figscale*[700,405,300,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            lblParam2 = uicontrol(UserFig,'Style','text','String',sprintf('Filter standard deviation: %s mm',num2str(filtParam2In.Value)),'Position',figscale*[700,340,300,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            % lblSearchDist = uicontrol(UserFig,'Style','text','String',sprintf('Max vertical change per pixel: %s mm',num2str(searchDistIn.Value)),'Position',figscale*[700,275,300,20],...
            %     'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            lblSensitivity1 = uicontrol(UserFig,'Style','text','String',sprintf('Horizontal sensitivity: %s',num2str(sensitivityParam1In.Value)),'Position',figscale*[700,275,300,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            lblSensitivity2 = uicontrol(UserFig,'Style','text','String',sprintf('Vertical sensitivity: %s',num2str(sensitivityParam2In.Value)),'Position',figscale*[700,210,300,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            lblSensitivity3 = uicontrol(UserFig,'Style','text','String',sprintf('Minimum ring width (%%FOV): %s',num2str(sensitivityParam3In.Value)),'Position',figscale*[700,145,300,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w');

            lblFilterType = uicontrol(UserFig,'Style','text','String','Filter type:','Position',figscale*[700,440,140,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w','HorizontalAlignment','right');

            lblDetectMethod = uicontrol(UserFig,'Style','text','String','Detection method:','Position',figscale*[700,470,140,20],...
                'FontSize',textscale*10,'FontName','Arial','Units','normalized','BackgroundColor','none','ForegroundColor','w','HorizontalAlignment','right');

        end

