        changingFiltType = 0;
        filterIn = [];
        function chooseFilter(src,event)

            filtParam1In.Value = filt_param1;
            filtParam2In.Value = filt_param2;

            % if filterIn.Value == 1
            %     h1 = fspecial('gaussian',round(filt_param1*((1./hpxS).*0.1)), ((1./hpxS).*0.1)*filt_param2);
            %     set(lblParam1,'String',sprintf('Filter width: %s mm',num2str(round(filtParam1In.Value*10)/10)))
            %     set(lblParam2,'String',sprintf('Filter standard deviation: %s mm',num2str(round(filtParam2In.Value*10)/10)))
            % elseif  filterIn.Value == 2
            %     h1 = fspecial('motion',round(filt_param1*((1./hpxS).*0.1)),filt_param2);
            %     set(lblParam1,'String',sprintf('Streak length: %s mm',num2str(round(filtParam1In.Value*10)/10)))
            %     set(lblParam2,'String',sprintf('Filter angle: %s°',num2str(round(filtParam2In.Value*10))))
            % end

            changingFiltType = 1;
            updateFilter
            changingFiltType = 0;
            if mult_rings == 0
                updateProposedRingsImage
            end
            editingProposedSettings=1;
            %updateProposedRings
            proposed_rings = ringDetection(x1,y1);
            replotMulti
            editingProposedSettings=0;

        end

        function chooseMethod(src,event)

            if detectMethodIn.Value == 1
                detectMode = 'gradient';
            elseif detectMethodIn.Value == 2
                detectMode = 'darkest';
            elseif detectMethodIn.Value == 3
                detectMode = 'seasonal';
            end

            if mult_rings == 0
                updateProposedRingsImage
            end
            editingProposedSettings=1;
            %updateProposedRings
            proposed_rings = ringDetection(x1,y1);
            replotMulti
            editingProposedSettings=0;

        end


        function updateFilter
            if filterIn.Value == 1
                h1 = fspecial('gaussian',round(filt_param1*((1./hpxS).*0.1)), ((1./hpxS).*0.1)*filt_param2);
                set(lblParam1,'String',sprintf('Filter width: %s mm',num2str(round(filtParam1In.Value*10)/10)))
                set(lblParam2,'String',sprintf('Filter standard deviation: %s mm',num2str(round(filtParam2In.Value*10)/10)))
                if changingFiltType == 1
                    filt_param2 = 0.3;
                    set(filtParam2In,'Limits',[0.1,2.5],'Value',filt_param2)
                end
            elseif  filterIn.Value == 2
                h1 = fspecial('motion',round(filt_param1*((1./hpxS).*0.1)),filt_param2);
                set(lblParam1,'String',sprintf('Streak length: %s mm',num2str(round(filtParam1In.Value*10)/10)))
                set(lblParam2,'String',sprintf('Filter angle: %s°',num2str(round(filtParam2In.Value*10))))
                if changingFiltType == 1
                    filt_param2 = 90;
                    set(filtParam2In,'Limits',[0,180],'Value',filt_param2)
                end
            end
        end

        filt_param1 = 2;
        filt_param2 = 0.3;
        h1 = fspecial('gaussian',round(filt_param1*((1./hpxS).*0.1)), ((1./hpxS).*0.1)*filt_param2);
        search_vertical_mm = 0.05;
        editingProposedSettings=0;

        function proposed_points=ringDetection(x,y)

            if editingProposedSettings == 0
                h1 = fspecial('gaussian',round(2*((1./hpxS).*0.1)), ((1./hpxS).*0.1)*0.3);
            end

            ys = get(ha,'YLim');
            xs = get(ha,'XLim');
            xInds = round(xs(1)./hpxS):round(xs(2)./hpxS);
            yInds = round(ys(1)./pxS):round(ys(2)./pxS);
            xInds(xInds<1) = [];
            xInds(xInds>row) = [];
            yInds(yInds<1) = [];
            yInds(yInds>layers) = [];
            %corePlot = pcolor(ha,xInds.*hpxS,yInds.*pxS,slabDraw(yInds,xInds));
            if ct
                img_filt0 = flipud(double(imfilter(mean(slabDraw(yInds,xInds,:),3),h1,'replicate')));
            else
                img_filt0 = double(imfilter(mean(slabDraw(yInds,xInds,:),3),h1,'replicate'));
            end

            if strcmp(detectMode,'gradient') || strcmp(detectMode,'seasonal')
                % apply gradient method
                [img_filt,Gdir] = imgradient(img_filt0);
                if ct
                    if strcmp(detectMode,'gradient') || topOfRing == 1
                        Gdir(Gdir<-90) = Gdir(Gdir<-90)+360;
                        Gdir = 1-((abs(270-(Gdir+180)))/180);
                        img_filt = -img_filt.*Gdir; % invert to find mins

                    elseif topOfRing == 0 % bottom of seasonal
                        Gdir(Gdir>90) = Gdir(Gdir>90)-360;
                        Gdir = 1-((abs(90-(Gdir+180)))/180);
                        img_filt = -img_filt.*Gdir;
                    end
                else
                    if strcmp(detectMode,'gradient') || topOfRing == 1
                        %img_filt = -img_filt.*sign(Gdir); % invert to find mins
                        Gdir(Gdir<-90) = Gdir(Gdir<-90)+360;
                        Gdir = 1-((abs(270-(Gdir+180)))/180);
                        img_filt = -img_filt.*Gdir; % invert to find mins

                    elseif topOfRing == 0 % bottom of seasonal
                        %img_filt = -img_filt.*-sign(Gdir); % mins will now be bottom of rings
                        Gdir(Gdir>90) = Gdir(Gdir>90)-360;
                        Gdir = 1-((abs(90-(Gdir+180)))/180);
                        img_filt = -img_filt.*Gdir;
                    end
                end
                img_filt = (min(min(img_filt0))-min(min(img_filt)))+img_filt; % make similar magnitude to original
            else
                img_filt = img_filt0;
            end

            img_min = min(min(img_filt));

            % max will be 60 degree angle
            max_ang = 60;
            mm_slope_tol = 1;
            h_pixels_slope = (mm_slope_tol/pxS)./(hpxS*tand(max_ang));
            % ^how many pixels vertical change across 1 mm

            search_offset = 0;

            search_vertical = round(search_vertical_mm/pxS); % number of pixels
            if search_vertical<1
                search_vertical = 1;
            end

            % find peaks

            % first, median filter
            medFiltLength0 = round(filt_param1*((1./hpxS).*0.1/2));
            medFiltLength = 2*floor(medFiltLength0/2)+1; % make an odd number
            halfMedFiltLength = (medFiltLength-1)/2;

            % correction of coordinates for CT
            if ct
                y = y-(round(y/pxS)-yInds(length(yInds)-find(round(y/pxS)==yInds))).*pxS;
            end

            % extract vertical slice
            thisSlice = img_filt(find(round(y/pxS)==yInds):end,find(round(x/hpxS)==xInds));

            thisSliceSmooth = NaN(size(thisSlice));
            % smooth slice:
            for kkj = halfMedFiltLength+1:length(thisSlice)-halfMedFiltLength
                thisSliceSmooth(kkj) = mean(thisSlice(kkj-halfMedFiltLength:kkj+halfMedFiltLength));
            end

            % find local minima
            [thesePks,theseLocs] = findpeaks(-thisSliceSmooth);
            [thesePksHigh,theseLocsHigh] = findpeaks(thisSliceSmooth);
            if length(thesePks) > 0
                if length(thesePksHigh) > length(thesePks) % more highs
                    pkHt = (thesePksHigh(2:end)+thesePksHigh(1:end-1))/2 - -thesePks;
                elseif length(thesePksHigh) < length(thesePks) % more low
                    pkHt = thesePksHigh(1) - -thesePks(1);
                    pkHt(2:length(thesePksHigh)) = (thesePksHigh(2:end)+thesePksHigh(1:end-1))/2 - -thesePks(2:end-1);
                    pkHt(end+1) = thesePksHigh(end) - -thesePks(end);
                elseif median(theseLocs>theseLocsHigh) % same number, highs first
                    pkHt = (thesePksHigh(2:end)+thesePksHigh(1:end-1))/2 - -thesePks(1:end-1);
                    pkHt(end+1) = thesePksHigh(end) - -thesePks(end);
                else % same number, lows first
                    pkHt = thesePksHigh(1) - -thesePks(1);
                    pkHt(2:length(thesePksHigh)) = (thesePksHigh(2:end)+thesePksHigh(1:end-1))/2 - -thesePks(2:end);
                end

                if editingProposedSettings == 0
                    new_peak_tol = 0.2;
                else
                    new_peak_tol = 1-sensitivityParam2In.Value;
                end

                full_range = max(thesePksHigh) - min(-thesePks);
                threshold_peak = full_range*new_peak_tol;
                theseLocs(pkHt<threshold_peak) = [];
            end

            firstPeak = 1;
            proposed_points = -99; % initiate
            count = 0;
            for kjj = 1:length(theseLocs)

                if firstPeak == 1
                    user_point = [round(x/hpxS),round(y/pxS)];
                    firstPeak = 0;
                else
                    count = count+1;
                    %min_search_range = round(round(y)+yInds(theseLocs(count)))-search_vertical : round(round(y)+yInds(theseLocs(count)))+search_vertical;
                    %[val,find_min] = min(img_filt(min_search_range,x))
                    user_point = [round(x/hpxS),round(find(round(y/pxS)==yInds)+yInds(theseLocs(count)))];
                end

                [this_min,min_loc] = min(img_filt(...
                    find(yInds==user_point(2))-search_vertical:find(yInds==user_point(2))+search_vertical,find(xInds==user_point(1))));
                abs_min_loc = find(yInds==user_point(2))-(search_vertical+1)+min_loc;

                valley_search_lims = 0.075; % mm MAKE ADJUSTABLE??
                valley_search_pxs = round(valley_search_lims/(pxS/10));

                if editingProposedSettings == 0
                    valley_height_tolerance = 0.2;
                else
                    valley_height_tolerance = 1-sensitivityParam1In.Value;
                end

                valley_lims = abs_min_loc-valley_search_pxs:abs_min_loc+valley_search_pxs;

                if max(valley_lims)>layers
                    valley_lims(valley_lims>layers) = [];
                end
                if min(valley_lims)<1
                    valley_lims(valley_lims<1) = [];
                end

                %ring_coordinates = [find(xInds==user_point(1)),abs_min_loc];

                ring_coordinates = [];
                if max(valley_lims)>1 && max(valley_lims)<=size(img_filt,1)
                    [these_peaks,peak_locs] = findpeaks(img_filt(valley_lims,find(xInds==user_point(1))));
                    lower_peaks = find(valley_lims(peak_locs)<abs_min_loc);
                    upper_peaks = find(valley_lims(peak_locs)>abs_min_loc);
                    search_midpoint = round(median(valley_lims));
                    [a,lower_peak_loc] = min(abs(search_midpoint-(valley_lims(1)-1+peak_locs(lower_peaks))));
                    peak = NaN(2,1);
                    if length(img_filt(valley_lims(1)-1+peak_locs(lower_peaks(lower_peak_loc)),find(xInds==user_point(1))))==1
                        peak(1) = img_filt(valley_lims(1)-1+peak_locs(lower_peaks(lower_peak_loc)),find(xInds==user_point(1)));
                    end
                    [a,upper_peak_loc] = min(abs(search_midpoint-(valley_lims(1)-1+peak_locs(upper_peaks))));
                    if length(img_filt(valley_lims(1)-1+peak_locs(upper_peaks(upper_peak_loc)),find(xInds==user_point(1)))) == 1
                        peak(2) = img_filt(valley_lims(1)-1+peak_locs(upper_peaks(upper_peak_loc)),find(xInds==user_point(1)));
                    end

                    orig_valley_height = mean(peak,'omitnan')-this_min;

                    conf_ring = 1;
                    counter = 1;
                    ring_coordinates = [find(xInds==user_point(1)),abs_min_loc];
                    this_x = find(xInds==user_point(1));
                    latest_y = abs_min_loc;
                    do_left = 1;
                    slopeSign = 1;

                    while conf_ring==1
                        if do_left==1
                            this_x = this_x-1;
                        else
                            this_x = this_x+1;
                        end
                        current_search = latest_y-search_vertical+search_offset:...
                            latest_y+search_vertical+search_offset;

                        if max(current_search)>size(img_filt,1)
                            current_search(current_search>size(img_filt,1)) = [];
                        end
                        if min(current_search)<1
                            current_search(current_search<1) = [];
                        end

                        [this_min,min_loc] = min(img_filt(current_search,this_x));

                        abs_min_loc = current_search(min_loc);

                        valley_lims = abs_min_loc-valley_search_pxs:abs_min_loc+valley_search_pxs;

                        if max(valley_lims)>size(img_filt,1)
                            valley_lims(valley_lims>size(img_filt,1)) = [];
                        end
                        if min(valley_lims)<1
                            valley_lims(valley_lims<1) = [];
                        end

                        if max(valley_lims)>1
                            [these_peaks,peak_locs] = findpeaks(img_filt(valley_lims,this_x));
                            lower_peaks = find(valley_lims(peak_locs)<abs_min_loc);
                            upper_peaks = find(valley_lims(peak_locs)>abs_min_loc);
                            search_midpoint = round(median(valley_lims));
                            peak = NaN(2,1);
                            [a,lower_peak_loc] = min(abs(search_midpoint-(valley_lims(1)-1+peak_locs(lower_peaks))));
                            if length(img_filt(valley_lims(1)-1+peak_locs(lower_peaks(lower_peak_loc)),this_x))
                                peak(1) = img_filt(valley_lims(1)-1+peak_locs(lower_peaks(lower_peak_loc)),this_x);
                            end
                            [a,upper_peak_loc] = min(abs(search_midpoint-(valley_lims(1)-1+peak_locs(upper_peaks))));
                            if length(img_filt(valley_lims(1)-1+peak_locs(upper_peaks(upper_peak_loc)),this_x))
                                peak(2) = img_filt(valley_lims(1)-1+peak_locs(upper_peaks(upper_peak_loc)),this_x);
                            end

                            this_valley_height = nanmean(peak)-this_min;

                            if this_valley_height>orig_valley_height*valley_height_tolerance && this_min > mean([contra(1),img_min]) %...
                                counter = counter+1;
                                latest_y = abs_min_loc;
                                ring_coordinates(counter,:) = [this_x,abs_min_loc];

                                % if counter>round(h_pixels_slope)
                                %     lengthfit = round(h_pixels_slope);
                                % else
                                %     lengthfit = counter;
                                % end
                                % if counter > 2
                                %     if do_left == 1
                                %         [x_check,idx] = sort(ring_coordinates(:,1),'descend');
                                %         y_check = ring_coordinates(idx,2);
                                %     elseif do_left == 0
                                %         [x_check,idx] = sort(ring_coordinates(:,1),'ascend');
                                %         y_check = ring_coordinates(idx,2);
                                %     end
                                %     b = regress(y_check(1:lengthfit),[...
                                %         ones(lengthfit,1),x_check(1:lengthfit)]);
                                %     if (b(2)*lengthfit)>mm_slope_tol*(lengthfit/h_pixels_slope)
                                %         search_offset = -1*slopeSign;
                                %     elseif (b(2)*lengthfit)<-mm_slope_tol*(lengthfit/h_pixels_slope)
                                %         search_offset = 1*slopeSign;
                                %     else
                                %         search_offset = 0;
                                %     end
                                % end

                            elseif do_left == 1
                                do_left = 0;
                                slopeSign = -1;
                                this_x = find(xInds==user_point(1));
                                latest_y = find(yInds==user_point(2));
                            elseif do_left == 0
                                conf_ring = 0;
                            end

                            if this_x == 1 || this_x == size(img_filt,2)
                                if do_left == 1
                                    do_left = 0;
                                    slopeSign = -1;
                                    this_x = find(xInds==user_point(1));
                                    latest_y = find(yInds==user_point(2));
                                elseif do_left == 0
                                    conf_ring = 0;
                                end
                            end

                            % don't use ring if hitting vertical limits
                            if max(current_search)>=size(img_filt,1) || min(current_search)<=1
                                if mult_rings == 0
                                    if do_left == 1
                                        do_left = 0;
                                        slopeSign = -1;
                                        this_x = find(xInds==user_point(1));
                                        latest_y = find(yInds==user_point(2));
                                    elseif do_left == 0
                                        conf_ring = 0;
                                    end
                                else % delete this ring
                                    conf_ring = 0;
                                    ring_coordinates = ring_coordinates(1,1);
                                end
                            end

                        elseif this_x == 1 || this_x == size(img_filt,2)
                            if do_left == 1
                                do_left = 0;
                                slopeSign = -1;
                                this_x = find(xInds==user_point(1));
                                latest_y = find(yInds==user_point(2));
                            elseif do_left == 0
                                conf_ring = 0;
                            end
                        end
                    end
                end
                trim_mm = 0.1;
                trim_pixels = round(trim_mm./hpxS);
                if length(ring_coordinates) > 1
                    [b idx] = sort(ring_coordinates(:,1));
                    ring_coordinates = ring_coordinates(idx,:);
                    if length(ring_coordinates(:,1))>(trim_pixels*2.5)
                        trim_inds = [1:trim_pixels,(length(ring_coordinates(:,1))-trim_pixels):length(ring_coordinates(:,1))];
                        ring_coordinates(trim_inds,:) = [];
                    end
                    these_proposed_points = [xInds(ring_coordinates(:,1))',yInds(ring_coordinates(:,2))'];
                    proposed_points(1:size(these_proposed_points,1),1:2,kjj) = these_proposed_points;
                end
                if mult_rings == 0
                    break
                end
            end
            proposed_points(proposed_points==-99) = NaN;
            proposed_points(proposed_points==0) = NaN;

            % correct for CT
            if ct
                proposed_points(:,2,:) = max(yInds)-proposed_points(:,2,:)+min(yInds);
            end
            
            % filter out short ones that are likely noise
            inds2remove = [];
            for kjj = 1:size(proposed_points,3)
                if length(treeROI) > 2
                    meanRingVert = nanmean(squeeze(proposed_points(:,2,kjj)));
                    x_min = min(treeROI(:,1)./hpxS)-1;
                    x_max = max(treeROI(:,1)./hpxS)+1;
                    line_x = [x_min; x_max];
                    line_y = [meanRingVert; meanRingVert];
                    [int_x,int_y] = polyxpoly(treeROI(:,1)./hpxS, treeROI(:,2)./pxS, line_x, line_y);
                    if length(int_x)>0
                        % The intersection points form a set of line segments.
                        % The width is the difference between the maximum and minimum x-coordinates of these points.
                        %intersection_x = intersection_shape.Vertices(:, 1);
                        this_width = max(int_x) - min(int_x);
                    else
                        this_width = range(xInds);
                    end
                else
                    this_width = range(xInds);
                end

                if editingProposedSettings == 0
                    minWidth = 0.1;
                else
                    minWidth = sensitivityParam3In.Value/100;
                end
                
                if sum(~isnan(squeeze(proposed_points(:,1,kjj)))) < minWidth*this_width
                    inds2remove = [inds2remove;kjj];
                end
            end
            proposed_points(:,:,inds2remove) = [];

            % crop to measurement area
            if length(treeROI) > 2
                for kjj = 1:size(proposed_points,3)
                    out_poly = ~inpolygon(squeeze(proposed_points(:,1,kjj)),squeeze(proposed_points(:,2,kjj)),treeROI(:,1)./hpxS,treeROI(:,2)./pxS);
                    proposed_points(out_poly,:,kjj) = NaN;
                end

                % delete any rings that are all NaN now
                inds2remove = [];
                for kjj = 1:size(proposed_points,3)
                    if sum(~isnan(proposed_points(:,1,kjj))) < 2
                        inds2remove = [inds2remove;kjj];
                    end
                end
                proposed_points(:,:,inds2remove) = [];
            end

            % check for and remove duplicates
            inds2remove = [];
            for kjj = 2:size(proposed_points,3)
                overlap_check = intersect(proposed_points(:,:,kjj),proposed_points(:,:,kjj-1),'rows');
                if length(overlap_check) > 0
                    inds2remove = [inds2remove;kjj];
                end
            end
            proposed_points(:,:,inds2remove) = [];
        end

        if ct == 1

            set(cropRingsIn,'Visible','off')
            set(outlineMeasurementsIn,'Visible','off')
            set(outlineMeasurementsOut,'Visible','off')
            set(mode1DIn,'Visible','off')

            if strcmp(numberYearsIn.Visible,'on')
                wasCalYr = 0;
            else
                wasCalYr = 1;
            end
            if strcmp(doSeasonalIn.Visible,'on')
                wasAnn = 1;
            else
                wasAnn = 0;
            end
            hideCTsettings

        end

