            set(unnumberYearsIn,'Visible','off')
            set(missingRingsApplyIn,'Visible','off')
            set(missingRingsSetIn,'Visible','off')
            set(missingRingsIn,'Visible','off')
            set(missingRingsTextIn,'Visible','off')
            set(lblClick2,'Visible','off')
