        function hideCTsettings(source,eventdata)

            set(adjustCtIn,'Visible','on')
            set(adjustCtOut,'Visible','off')
            set(ha2,'Units','Pixels','Position',figscale*[670,350,200,200],'Units','normalized')
            if wasAnn == 1
                set(doSeasonalIn,'Visible','on')
            else
                set(doAnnualIn,'Visible','on')
            end
            set(doneIn,'Visible','on')
            set(processIn,'Visible','on')

            set(projIn,'Visible','off')
            set(htext1,'Visible','off')
            set(htext2,'Visible','off')
            set(htext3,'Visible','off')
            set(htext4,'Visible','off')
            set(htext5,'Visible','off')
            set(htext6,'Visible','off')
            set(thickIn,'Visible','off')
            set(brightnessIn,'Visible','off')
            set(contrastIn,'Visible','off')
            set(positionIn,'Visible','off')
            set(lblPos,'Visible','off')
            set(lblThick,'Visible','off')
            set(lblBright,'Visible','off')
            set(lblContrast,'Visible','off')
            set(rotationIn,'Visible','off')
            set(lblRot,'Visible','off')

            set(startingYearTextIn,'Visible','on')
            set(topYearSetIn,'Visible','on')
            if wasCalYr == 0
                set(numberYearsIn,'Visible','on')
            else
                set(unnumberYearsIn,'Visible','on')
            end
            set(missingRingsApplyIn,'Visible','on')
            set(missingRingsSetIn,'Visible','on')
            set(missingRingsIn,'Visible','on')
            set(missingRingsTextIn,'Visible','on')
            set(lblClick2,'Visible','on')
            set(switchRingTypeIn,'Visible','on')
            set(calibrateScaleIn,'Visible','on')

        end

        while moveOn == 0
            pause(2)
        end
    end

    function findTree(corName,secName)

        thisSectionName = secName;
        thisTreeName = corName;

        if view_only == 0
            cFolderName = 'current_image';
        elseif view_only == 1
            cFolderName = 'current_image_view_only';
        end

        dirRow = 0;
        didwematch = 0;
        while didwematch==0
            dirRow = dirRow+1;
            if strcmp('',thisSectionName)
                isthismatch = strcmp(thisTreeName,treeDir.textdata{dirRow,1});
            else
                isthismatch = strcmp(thisTreeName,treeDir.textdata{dirRow,1})...
                    & strcmp(thisSectionName,treeDir.textdata{dirRow,2});
            end
            if isthismatch==1
                break
            end
        end
        serverChoice = [];
        if treeDir.data(dirRow-1,1) == 1
            serverChoice = 1;
            h_drive = 'tdecarlo19/public/hd1/';
        elseif treeDir.data(dirRow-1,1) == 2
            serverChoice = 2;
            h_drive = 'tdecarlo19/public/hd1/';
        elseif treeDir.data(dirRow-1,1) == 3
            serverChoice = 1;
            h_drive = 'tdecarlo19/public/hd1/';
        end

        flipCore = treeDir.data(dirRow-1,2);
        ct = treeDir.data(dirRow-1,12);

        try
            if serverChoice == 1
                cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password);
            elseif serverChoice == 2
                cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password);
            elseif serverChoice == 3
                cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
            end
        catch
            try
                connectTimes = [1,2,3,5,10,60,60*12]; % minutes
                connectionEstablished = 0;
                for ij = 1:length(connectTimes)
                    if connectionEstablished == 0
                        if connectTimes(ij) == 1
                            waitText = [' ',num2str(connectTimes(ij)),' minute.']
                        else
                            waitText = [' ',num2str(connectTimes(ij)),' minutes.']
                        end
                        set(lblOpeningError,'Units','Pixels','Visible','on','Position',figscale*[200,80,500,40],...
                            'String',{'Error connecting to server.';strcat('Trying again in',waitText)},...
                            'Units','normalized')
                        pause(connectTimes(ij)*60)
                        try
                            if serverChoice == 1
                                cache2 = sftp(ftp_ip2,ftp_user2,"Password",ftp_password)
                            elseif serverChoice == 2
                                cache2 = sftp(ftp_ip2,ftp_user3,"Password",ftp_password)
                            elseif serverChoice == 3
                                cache2 = sftp(ftp_ip1,ftp_user1,"Password",ftp_password);
                            end
                            connectionEstablished = 1;
                            set(lblOpeningError,'Units','Pixels','Visible','off',...
                                'Position',figscale*[200,150,500,20],'Units','normalized')
                        catch
                        end
                    end
                end
                if connectionEstablished == 0
                    zz = abjfl; % if we made it through end of loop, cause an error to display error code below
                end
            catch
                set(lblOpeningError,'Units','Pixels','Position',figscale*[200,80,500,40],'Visible','on',...
                    'String',{'Error connecting to server. (code 005)';'Please try again later.'},...
                    'Units','normalized')
                while 1==1
                    pause
                end
            end

        end


        if strcmp('',thisSectionName)
            server_path = strcat(h_drive,treeDir.textdata{dirRow,3},'/',...
                treeDir.textdata{dirRow,4},'/',thisTreeName);
        else
            server_path = strcat(h_drive,'/',treeDir.textdata{dirRow,3},'/',...
                treeDir.textdata{dirRow,4},'/',thisTreeName,'/',thisSectionName);
        end

        if serverChoice == 1 || serverChoice == 3
            server_path(double(server_path)==32) = 95; % converts spaces to _
        end

        cd(cache2,server_path)

        if exist(fullfile(selpath,'my_trees',cFolderName,'image'),'dir')
            rmdir(fullfile(selpath,'my_trees',cFolderName,'image'),'s')
        end
        if exist(fullfile(selpath,'my_trees',cFolderName,'dicoms'),'dir')
            rmdir(fullfile(selpath,'my_trees',cFolderName,'dicoms'),'s')
        end

        if saveCTdata == 1 && view_only == 0
            if ct == 1
                if serverChoice ~= 3
                    if strcmp('',thisSectionName)
                        mget22(cache2,'dicoms.zip',fullfile(selpath,'my_trees',thisTreeName));
                        fileOpen = fullfile(selpath,'my_trees',thisTreeName,'dicoms');
                    else
                        mget22(cache2,'dicoms.zip',fullfile(selpath,'my_trees',thisTreeName,thisSectionName));
                        fileOpen = fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'dicoms');
                    end
                else
                    if strcmp('',thisSectionName)
                        mget22(cache2,'dicomFolder',fullfile(selpath,'my_trees',thisTreeName));
                        movefile(fullfile(selpath,'my_trees',thisTreeName,'dicomFolder','dicoms.zip'),fullfile(selpath,'my_trees',thisTreeName))
                        rmdir(fullfile(selpath,'my_trees',thisTreeName,'dicomFolder'),'s')
                        fileOpen = fullfile(selpath,'my_trees',thisTreeName,'dicoms');
                    else
                        mget22(cache2,'dicomFolder',fullfile(selpath,'my_trees',thisTreeName,thisSectionName));
                        movefile(fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'dicomFolder','dicoms.zip'),fullfile(selpath,'my_trees',thisTreeName,thisSectionName))
                        rmdir(fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'dicomFolder'),'s')
                        fileOpen = fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'dicoms');
                    end
                end
            else
                if strcmp('',thisSectionName)
                    dirInit = dir(cache2);
                    for iii = 1:length(dirInit)
                        if length(strsplit(dirInit(iii).name,'.tiff'))==2
                            img_name = dirInit(iii).name;
                        end
                    end
                    mget22(cache2,img_name,fullfile(selpath,'my_trees',thisTreeName,'image'));
                    fileOpen = fullfile(selpath,'my_trees',thisTreeName,'image');
                else
                    dirInit = dir(cache2);
                    for iii = 1:length(dirInit)
                        if length(strsplit(dirInit(iii).name,'.tiff'))==2
                            img_name = dirInit(iii).name;
                        end
                    end
                    mget22(cache2,img_name,fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'image'));
                    fileOpen = fullfile(selpath,'my_trees',thisTreeName,thisSectionName,'image');
                end
            end
        else
            if ct == 1
                if serverChoice ~= 3
                    mget22(cache2,'dicoms.zip',fullfile(selpath,'my_trees',cFolderName));
                else
                    mget22(cache2,'dicomFolder',fullfile(selpath,'my_trees',cFolderName));
                    movefile(fullfile(selpath,'my_trees',cFolderName,'dicomFolder','dicoms.zip'),fullfile(selpath,'my_trees',cFolderName))
                    rmdir(fullfile(selpath,'my_trees',cFolderName,'dicomFolder'),'s')
                end
            else
                dirInit = dir(cache2);
                for iii = 1:length(dirInit)
                    if length(strsplit(dirInit(iii).name,'.tiff'))==2
                        img_name = dirInit(iii).name;
                    end
                end
                mget22(cache2,img_name,fullfile(selpath,'my_trees',cFolderName,'image'));
            end
        end

        if saveCTdata == 1 && view_only == 0
            if ct == 1
                if strcmp('',thisSectionName)
                    unzip(fullfile(selpath,'my_trees',thisTreeName,'dicoms.zip'),fullfile(selpath,'my_trees',thisTreeName,'dicoms'));
                    fid = fopen(fullfile(selpath,'my_trees',thisTreeName,'dicoms','CoreMetaData.csv'),'w');
                    fprintf(fid,'%s\n',corName);
                    fprintf(fid,'%s\n',secName);
                    try fclose(fid);
                    catch
                    end
                    try mget22(cache2,strcat(saveName,thisTreeName,'.mat'),fullfile(selpath,'my_trees',thisTreeName,'dicoms'))
                    catch
                    end
                else
