    function volumeDensity

        % Script to compute volume and mean density of a tree CT scan. Requires
        % that 'buildCore' and 'treeStandardCurve' have already been executed.

        % check for where the core has not been built yet
        unBuilt = [1:bottomCore-1, topCore+1:layers];

        % add on to existing core where it is not already built
        for k = 1:length(unBuilt)
            i = unBuilt(k);
            filteredXcore(:,:) = imfilter(X(:,:,i), h2,'replicate');
            thresh = multithresh(filteredXcore,1);
            if thresh > -800
                tree(:,:,i) = filteredXcore>thresh;
            else
                altThresh = multithresh(filteredXcore,3);
                if altThresh(2) > -800
                    tree(:,:,i) = filteredXcore>altThresh(2);
                elseif altThresh(3) > -800
                    tree(:,:,i) = filteredXcore>altThresh(3);
                end
            end
        end

        % now calculate volume and density

        pxT = sum(sum(sum(tree))); % total voxels in core

        volume = pxT*((hpxS/10)*(hpxS/10)*(pxS/10)); % volume in cm^3

        % mean whole-core density
        densityWholeCore = (mean(X(tree==1))-HU2dens(2))/HU2dens(1);

    end


    function extension_rate

        % initialize some storage matrices here, see their usage below
        if strcmp(detectMode,'seasonal')
            totRings = length(find(max(max(userRings>1)))>0);
        else
            totRings = length(find(max(max(userRings)))>0);
        end

        n_traces = 5e3;

        % make smoothed rings first
        [rowMesh ,colMesh] = meshgrid(1:row,1:col);
        LDBdata = zeros(row,col,totRings);
        ring_filt = zeros(size(LDBdata));

        % prog bar reset
        p1 = patch(ha3,[0 0 1 1],[0 1 1 0],[0.2 0.2 0.2]);

        for i4 = 1:totRings

            titleName = currentLoadingTitle;
            progressUpdate(i4/totRings);
            if max(max(userRings(:,:,i4)))>0
                [r,c] = find(userRings(:,:,i4));
                if isempty(r)
                    break
                end
                v = zeros(1,length(r));
                for j2 = 1:length(r)
                    v(j2) = userRings(r(j2),c(j2),i4);
                end
                warning('off','all');
                if length(round(griddata(r,c,v,rowMesh,colMesh)))>1
                    LDBdata(:,:,i4) = permute(round(griddata(r,c,v,rowMesh,colMesh)),[2,1,3]);
                end
                warning('on','all');
            end
            ring_filt(:,:,i4) = nanconv(LDBdata(:,:,i4), h3, 'nanout','edge');
        end

        totRings2 = length(find(max(max(~isnan(ring_filt))))>0);
        extension = NaN(totRings2-1,n_traces);

        % can use those later for plotting in 3d if desired
        pointsX = NaN(totRings2,n_traces);
        pointsY = NaN(totRings2,n_traces);

        % loop through all rings less one because can only measure rates between
        % consecutive rings
        for i = 1:totRings2-1

            % seed random points within this ring
            n_points = 0;
            counter = 0;
            max_top_ring = max(max(ring_filt(:,:,i)));
            [dx,dy] = gradient(ring_filt(:,:,i+1)*pxS/hpxS);
            v = ~isnan(ring_filt(:,:,i+1)) & ~isnan(dx) & ~isnan(dy);
            [r,c] = find(v);
            rand_idx = randperm(length(r));
            sampled_x = c(rand_idx);
            sampled_y = r(rand_idx);
            while n_points<n_traces && counter<length(sampled_y)
                counter = counter+1;
                new_x = sampled_x(counter);
                new_y = sampled_y(counter);
                if ~isnan(ring_filt(new_y,new_x,i+1))...
                        && tree(new_y,new_x,LDBdata(new_y,new_x,i+1)) == 1

                    this_path_z = ring_filt(new_y,new_x,i+1):0.1:max_top_ring;
                    z_relative = this_path_z-min(this_path_z);
                    this_path_x = new_x-z_relative.*dx(new_y,new_x);
                    this_path_y = new_y-z_relative.*dy(new_y,new_x);

                    to_remove = find(this_path_x<1 | this_path_x>col |...
                        this_path_y<1 | this_path_y>row);
                    this_path_x(to_remove) = [];
                    this_path_y(to_remove) = [];
                    this_path_z(to_remove) = [];

                    costFun = NaN(length(this_path_x),1);
                    for i2 = 1:length(this_path_x)
                        costFun(i2) = abs(min(min(this_path_z(i2)-ring_filt(...
                            round(this_path_y(i2)),round(this_path_x(i2)),i))));
                    end

                    [dif,layerTop]  = min(costFun);

                    if dif <=1 % successfully traced between rings

                        n_points = n_points+1;
                        pointsX(i,n_points) = new_x;
                        pointsY(i,n_points) = new_y;

                        extension(i,n_points) = sqrt(((this_path_x(layerTop)-new_x)*hpxS)^2 +...
                            ((this_path_y(layerTop)-new_y)*hpxS)^2 + ...
                            (pxS*(this_path_z(layerTop)-this_path_z(1)))^2);

                    end
                end
            end
        end

    end

    function get1Dintersections

        totRings3 = find(max(userRings));
        if length(line_segments)
            for i4 = totRings3
                [xi,yi] = polyxpoly(line_segments(:,1),line_segments(:,2),find(userRings(:,i4)).*hpxS,userRings(find(userRings(:,i4)),i4).*pxS);
                if length(xi)
                    ringMarks1D(i4,1:2) = [xi(1),yi(1)];
                end
            end
        end
    end

    function get1Dintersections2 % down bottom of rings

        totRings3 = find(max(userRings2));
        if length(line_segments)
            for i4 = totRings3
                [xi,yi] = polyxpoly(line_segments(:,1),line_segments(:,2),find(userRings2(:,i4)).*hpxS,userRings2(find(userRings2(:,i4)),i4).*pxS);
                if length(xi)
                    ringMarks1D2(i4,1:2) = [xi(1),yi(1)];
                end
            end
        end
    end

    function extension_rate_Xray1D

        % make sure we have the latest ring marks
        get1Dintersections % this updates ringMarks1D for where there are 2D-ring intersections

        totRings3 = find(max(userRings)); % which rings are from 2D
        totRings4 = find(ringMarks1D(:,1))'; % which rings are from 1D
        totRings5 = setdiff(totRings4,totRings3); % which rings are only 1D

        for i5 = totRings5
            d = pdist2(interp_segments,ringMarks1D(i5,:));
            [val,loc] = min(d);
            ringMarks1D(i5,1:2) = interp_segments(loc,:);
        end

        extension = NaN(size(ringMarks1D,1)-1,1);

        % calculate ring widths
        for i5 = 1:max(find(ringMarks1D(:,1)))-1
            extension(i5) = sqrt((ringMarks1D(i5,1)-ringMarks1D(i5+1,1))^2 + ...
                (ringMarks1D(i5,2)-ringMarks1D(i5+1,2))^2);
        end

        %extension = extension; % put as row vec

    end

    function extension_rate_Xray

        % initialize some storage matrices here, see their usage below
        totRings = length(find(max(userRings)>0 & ~isnan(max(userRings))));

        n_traces = 1e3;

        % make smoothed rings first
        LDBdata = zeros(col,totRings);
        ring_filt = NaN(size(LDBdata));
        h2d = sum(h3);
        h2mid = ceil(length(h3(:,1))/2);
        for i4 = 1:totRings
            titleName = currentLoadingTitle;
            progressUpdate(i4/totRings);

            if max(max(userRings(:,i4)))>0
                c = find(userRings(:,i4));
                if isempty(c)
                    break
                end
                this_ring_interp = interp1(c,userRings(c,i4),min(c):max(c));

                for i5 = min(c):max(c)
                    h2x = i5-h2mid:i5-h2mid+length(h2d)-1;
                    thisH2d = h2d;
                    thisH2d(h2x < min(c)) = [];
                    h2x(h2x < min(c)) = [];
                    thisH2d(h2x > max(c)) = [];
                    h2x(h2x > max(c)) = [];
                    h2x = h2x-min(c)+1;
                    thisH2d = thisH2d./sum(thisH2d);
                    ring_filt(i5,i4) = sum(this_ring_interp(h2x).*thisH2d);
                end
            end
        end
        LDBdata = ring_filt;

        %totRings2 = length(find(max(~isnan(ring_filt)))>0);
        totRings2 = totRings;
        extension = NaN(totRings-1,n_traces);

        % loop through all rings less one because can only measure rates between
        % consecutive rings
        for i = 1:totRings-1
            if max(~isnan(ring_filt(:,i)))>0

                % seed random points within this ring
                n_points = 0;
                counter = 0;
                max_top_ring = max(ring_filt(:,i));
                dx = gradient(ring_filt(:,i+1)*pxS/hpxS);
                c = find(userRings(:,i+1));
                while n_points<n_traces && counter<1e7
                    counter = counter+1;
                    if counter == 1e3
                        if n_points == 0
                            break
                        end
                    end
                    new_x = round(rand(1)*(range(c)-1)+min(c));
                    if abs(dx(new_x)) > 0

                        this_path_z = ring_filt(new_x,i+1):0.1:max_top_ring;
                        z_relative = this_path_z-min(this_path_z);
                        this_path_x = new_x-z_relative.*dx(new_x);

                        to_remove = find(this_path_x<1 | this_path_x>col);
                        this_path_x(to_remove) = [];
                        this_path_z(to_remove) = [];

                        costFun = NaN(length(this_path_x),1);
                        for i2 = 1:length(this_path_x)
                            costFun(i2) = abs(min(min(this_path_z(i2)-ring_filt(...
                                round(this_path_x(i2)),i))));
                        end

                        [dif,layerTop]  = min(costFun);

                        if dif <=1 % successfully traced between rings

                            n_points = n_points+1;

                            extension(i,n_points) = sqrt(((this_path_x(layerTop)-new_x)*hpxS)^2 +...
                                (pxS*(this_path_z(layerTop)-this_path_z(1)))^2);

                        end
                    end
                end
            end
        end

    end


processingGrowth = 0;

    function progressUpdate(fraction)

        if (strcmp(TreeTracerFormat,'mchips') || strcmp(TreeTracerFormat,'windows')) && processingGrowth == 1
            if doingDensCalib == 1
                title(ha3,[titleName,': ',num2str(round(fraction*100)),'%'],'Color','k')
