    function [z, a, b, alpha] = fitellipse(x, varargin)
        %FITELLIPSE   least squares fit of ellipse to 2D data
        %
        %   [Z, A, B, ALPHA] = FITELLIPSE(X)
        %       Fit an ellipse to the 2D points in the 2xN array X. The ellipse is
        %       returned in parametric form such that the equation of the ellipse
        %       parameterised by 0 <= theta < 2*pi is:
        %           X = Z + Q(ALPHA) * [A * cos(theta); B * sin(theta)]
        %       where Q(ALPHA) is the rotation matrix
        %           Q(ALPHA) = [cos(ALPHA), -sin(ALPHA);
        %                       sin(ALPHA), cos(ALPHA)]
        %
        %       Fitting is performed by nonlinear least squares, optimising the
        %       squared sum of orthogonal distances from the points to the fitted
        %       ellipse. The initial guess is calculated by a linear least squares
        %       routine, by default using the Bookstein constraint (see below)
        %
        %   [...]            = FITELLIPSE(X, 'linear')
        %       Fit an ellipse using linear least squares. The conic to be fitted
        %       is of the form
        %           x'Ax + b'x + c = 0
        %       and the algebraic error is minimised by least squares with the
        %       Bookstein constraint (lambda_1^2 + lambda_2^2 = 1, where
        %       lambda_i are the eigenvalues of A)
        %
        %   [...]            = FITELLIPSE(..., 'Property', 'value', ...)
        %       Specify property/value pairs to change problem parameters
        %          Property                  Values
        %          =================================
        %          'constraint'              {|'bookstein'|, 'trace'}
        %                                    For the linear fit, the following
        %                                    quadratic form is considered
        %                                    x'Ax + b'x + c = 0. Different
        %                                    constraints on the parameters yield
        %                                    different fits. Both 'bookstein' and
        %                                    'trace' are Euclidean-invariant
        %                                    constraints on the eigenvalues of A,
        %                                    meaning the fit will be invariant
        %                                    under Euclidean transformations
        %                                    'bookstein': lambda1^2 + lambda2^2 = 1
        %                                    'trace'    : lambda1 + lambda2     = 1
        %
        %           Nonlinear Fit Property   Values
        %           ===============================
        %           'maxits'                 positive integer, default 200
        %                                    Maximum number of iterations for the
        %                                    Gauss Newton step
        %
        %           'tol'                    positive real, default 1e-5
        %                                    Relative step size tolerance
        %   Example:
        %       % A set of points
        %       x = [1 2 5 7 9 6 3 8;
        %            7 6 8 7 5 7 2 4];
        %
        %       % Fit an ellipse using the Bookstein constraint
        %       [zb, ab, bb, alphab] = fitellipse(x, 'linear');
        %
        %       % Find the least squares geometric estimate
        %       [zg, ag, bg, alphag] = fitellipse(x);
        %
        %       % Plot the results
        %       plot(x(1,:), x(2,:), 'ro')
        %       hold on
        %       % plotellipse(zb, ab, bb, alphab, 'b--')
        %       % plotellipse(zg, ag, bg, alphag, 'k')
        %
        %   See also PLOTELLIPSE

        % Copyright Richard Brown, this code can be freely used and modified so
        % long as this line is retained
        error(nargchk(1, 5, nargin, 'struct'))

        % Default parameters
        params.fNonlinear = true;
        params.constraint = 'bookstein';
        params.maxits     = 200;
        params.tol        = 1e-5;

        % Parse inputs
        [x, params] = parseinputs(x, params, varargin{:});

        % Constraints are Euclidean-invariant, so improve conditioning by removing
        % centroid
        centroid = mean(x, 2);
        x        = x - repmat(centroid, 1, size(x, 2));

        % Obtain a linear estimate
        switch params.constraint
            % Bookstein constraint : lambda_1^2 + lambda_2^2 = 1
            case 'bookstein'
                [z, a, b, alpha] = fitbookstein(x);

                % 'trace' constraint, lambda1 + lambda2 = trace(A) = 1
            case 'trace'
                [z, a, b, alpha] = fitggk(x);
        end % switch

        % Minimise geometric error using nonlinear least squares if required
        if params.fNonlinear
            % Initial conditions
            z0     = z;
            a0     = a;
            b0     = b;
            alpha0 = alpha;

            % Apply the fit
            [z, a, b, alpha, fConverged] = ...
                fitnonlinear(x, z0, a0, b0, alpha0, params);

            % Return linear estimate if GN doesn't converge
            if ~fConverged
                warning('fitellipse:FailureToConverge', ...'
                    'Gauss-Newton did not converge, returning linear estimate');
                z = z0;
                a = a0;
                b = b0;
                alpha = alpha0;
            end
        end

        % Add the centroid back on
        z = z + centroid;

    end % fitellipse



    function [z, a, b, alpha] = fitbookstein(x)
        %FITBOOKSTEIN   Linear ellipse fit using bookstein constraint
        %   lambda_1^2 + lambda_2^2 = 1, where lambda_i are the eigenvalues of A

        % Convenience variables
        m  = size(x, 2);
        x1 = x(1, :)';
        x2 = x(2, :)';

        % Define the coefficient matrix B, such that we solve the system
        % B *[v; w] = 0, with the constraint norm(w) == 1
        B = [x1, x2, ones(m, 1), x1.^2, sqrt(2) * x1 .* x2, x2.^2];

        % To enforce the constraint, we need to take the QR decomposition
        [Q, R] = qr(B);

        % Decompose R into blocks
        R11 = R(1:3, 1:3);
        R12 = R(1:3, 4:6);
        R22 = R(4:6, 4:6);

        % Solve R22 * w = 0 subject to norm(w) == 1
        [U, S, V] = svd(R22);
        w = V(:, 3);

        % Solve for the remaining variables
        v = -R11 \ R12 * w;

        % Fill in the quadratic form
        A        = zeros(2);
        A(1)     = w(1);
        A([2 3]) = 1 / sqrt(2) * w(2);
        A(4)     = w(3);
        bv       = v(1:2);
        c        = v(3);

        % Find the parameters
        [z, a, b, alpha] = conic2parametric(A, bv, c);

    end % fitellipse



    function [z, a, b, alpha] = fitggk(x)
        % Linear least squares with the Euclidean-invariant constraint Trace(A) = 1

        % Convenience variables
        m  = size(x, 2);
        x1 = x(1, :)';
        x2 = x(2, :)';

        % Coefficient matrix
        B = [2 * x1 .* x2, x2.^2 - x1.^2, x1, x2, ones(m, 1)];

        v = B \ -x1.^2;

        % For clarity, fill in the quadratic form variables
        A        = zeros(2);
        A(1,1)   = 1 - v(2);
        A([2 3]) = v(1);
        A(2,2)   = v(2);
        bv       = v(3:4);
        c        = v(5);

        % find parameters
        [z, a, b, alpha] = conic2parametric(A, bv, c);

    end



    function [z, a, b, alpha, fConverged] = fitnonlinear(x, z0, a0, b0, alpha0, params)
        % Gauss-Newton least squares ellipse fit minimising geometric distance

        % Get initial rotation matrix
        Q0 = [cos(alpha0), -sin(alpha0); sin(alpha0) cos(alpha0)];
        m = size(x, 2);

        % Get initial phase estimates
        phi0 = angle( [1 i] * Q0' * (x - repmat(z0, 1, m)) )';
        u = [phi0; alpha0; a0; b0; z0];

        % Iterate using Gauss Newton
        fConverged = false;
        for nIts = 1:params.maxits
            % Find the function and Jacobian
            [f, J] = sys(u);

            % Solve for the step and update u
            h = -J \ f;
            u = u + h;

            % Check for convergence
            delta = norm(h, inf) / norm(u, inf);
            if delta < params.tol
                fConverged = true;
                break
            end
        end

        alpha = u(end-4);
        a     = u(end-3);
        b     = u(end-2);
        z     = u(end-1:end);


        function [f, J] = sys(u)
            % SYS : Define the system of nonlinear equations and Jacobian. Nested
            % function accesses X (but changeth it not)
            % from the FITELLIPSE workspace

            % Tolerance for whether it is a circle
            circTol = 1e-5;

            % Unpack parameters from u
            phi   = u(1:end-5);
            alpha = u(end-4);
            a     = u(end-3);
            b     = u(end-2);
            z     = u(end-1:end);

            % If it is a circle, the Jacobian will be singular, and the
            % Gauss-Newton step won't work.
            %TODO: This can be fixed by switching to a Levenberg-Marquardt
            %solver
            if abs(a - b) / (a + b) < circTol
                warning('fitellipse:CircleFound', ...
                    'Ellipse is near-circular - nonlinear fit may not succeed')
            end

            % Convenience trig variables
            c = cos(phi);
            s = sin(phi);
            ca = cos(alpha);
            sa = sin(alpha);

            % Rotation matrices
            Q    = [ca, -sa; sa, ca];
            Qdot = [-sa, -ca; ca, -sa];

            % Preallocate function and Jacobian variables
            f = zeros(2 * m, 1);
            J = zeros(2 * m, m + 5);
            for i = 1:m
                rows = (2*i-1):(2*i);
                % Equation system - vector difference between point on ellipse
                % and data point
                f((2*i-1):(2*i)) = x(:, i) - z - Q * [a * cos(phi(i)); b * sin(phi(i))];

                % Jacobian
                J(rows, i) = -Q * [-a * s(i); b * c(i)];
                J(rows, (end-4:end)) = ...
                    [-Qdot*[a*c(i); b*s(i)], -Q*[c(i); 0], -Q*[0; s(i)], [-1 0; 0 -1]];
            end
        end
    end % fitnonlinear



    function [z, a, b, alpha] = conic2parametric(A, bv, c)
        % Diagonalise A - find Q, D such at A = Q' * D * Q
        [Q, D] = eig(A);
        Q = Q';

        % If the determinant < 0, it's not an ellipse
        if prod(diag(D)) <= 0
            error('fitellipse:NotEllipse', 'Linear fit did not produce an ellipse');
        end

        % We have b_h' = 2 * t' * A + b'
        t = -0.5 * (A \ bv);

        c_h = t' * A * t + bv' * t + c;

        z = t;
        a = sqrt(-c_h / D(1,1));
        b = sqrt(-c_h / D(2,2));
        alpha = atan2(Q(1,2), Q(1,1));
    end % conic2parametric



    function [x, params] = parseinputs(x, params, varargin)
        % PARSEINPUTS put x in the correct form, and parse user parameters

        % CHECK x
        % Make sure x is 2xN where N > 3
        if size(x, 2) == 2
            x = x';
        end
        if size(x, 1) ~= 2
            error('fitellipse:InvalidDimension', ...
                'Input matrix must be two dimensional')
        end
        if size(x, 2) < 6
            error('fitellipse:InsufficientPoints', ...
                'At least 6 points required to compute fit')
        end


        % Determine whether we are solving for geometric (nonlinear) or algebraic
        % (linear) distance
        if ~isempty(varargin) && strncmpi(varargin{1}, 'linear', length(varargin{1}))
            params.fNonlinear = false;
            varargin(1)       = [];
        else
            params.fNonlinear = true;
        end

        % Parse property/value pairs
        if rem(length(varargin), 2) ~= 0
            error('fitellipse:InvalidInputArguments', ...
                'Additional arguments must take the form of Property/Value pairs')
        end

        % Cell array of valid property names
        properties = {'constraint', 'maxits', 'tol'};

        while length(varargin) ~= 0
            % Pop pair off varargin
            property      = varargin{1};
            value         = varargin{2};
            varargin(1:2) = [];

            % If the property has been supplied in a shortened form, lengthen it
            iProperty = find(strncmpi(property, properties, length(property)));
            if isempty(iProperty)
                error('fitellipse:UnknownProperty', 'Unknown Property');
            elseif length(iProperty) > 1
                error('fitellipse:AmbiguousProperty', ...
                    'Supplied shortened property name is ambiguous');
            end

            % Expand property to its full name
            property = properties{iProperty};

            % Check for irrelevant property
            if ~params.fNonlinear && ismember(property, {'maxits', 'tol'})
                warning('fitellipse:IrrelevantProperty', ...
                    'Supplied property has no effect on linear estimate, ignoring');
                continue
            end

            % Check supplied property value
            switch property
                case 'maxits'
                    if ~isnumeric(value) || value <= 0
                        error('fitcircle:InvalidMaxits', ...
                            'maxits must be an integer greater than 0')
                    end
                    params.maxits = value;
                case 'tol'
                    if ~isnumeric(value) || value <= 0
                        error('fitcircle:InvalidTol', ...
                            'tol must be a positive real number')
                    end
                    params.tol = value;
                case 'constraint'
                    switch lower(value)
                        case 'bookstein'
                            params.constraint = 'bookstein';
                        case 'trace'
                            params.constraint = 'trace';
                        otherwise
                            error('fitellipse:InvalidConstraint', ...
                                'Invalid constraint specified')
                    end
            end % switch property
        end % while

    end % parseinputs

    function c = nanconv(a, k, varargin)
        % NANCONV Convolution in 1D or 2D ignoring NaNs.
        %   C = NANCONV(A, K) convolves A and K, correcting for any NaN values
        %   in the input vector A. The result is the same size as A (as though you
        %   called 'conv' or 'conv2' with the 'same' shape).
        %
        %   C = NANCONV(A, K, 'param1', 'param2', ...) specifies one or more of the following:
        %     'edge'     - Apply edge correction to the output.
        %     'noedge'   - Do not apply edge correction to the output (default).
        %     'nanout'   - The result C should have NaNs in the same places as A.
        %     'nonanout' - The result C should have ignored NaNs removed (default).
        %                  Even with this option, C will have NaN values where the
        %                  number of consecutive NaNs is too large to ignore.
        %     '2d'       - Treat the input vectors as 2D matrices (default).
        %     '1d'       - Treat the input vectors as 1D vectors.
        %                  This option only matters if 'a' or 'k' is a row vector,
        %                  and the other is a column vector. Otherwise, this
        %                  option has no effect.
        %
        %   NANCONV works by running 'conv2' either two or three times. The first
        %   time is run on the original input signals A and K, except all the
        %   NaN values in A are replaced with zeros. The 'same' input argument is
        %   used so the output is the same size as A. The second convolution is
        %   done between a matrix the same size as A, except with zeros wherever
        %   there is a NaN value in A, and ones everywhere else. The output from
        %   the first convolution is normalized by the output from the second
        %   convolution. This corrects for missing (NaN) values in A, but it has
        %   the side effect of correcting for edge effects due to the assumption of
        %   zero padding during convolution. When the optional 'noedge' parameter
        %   is included, the convolution is run a third time, this time on a matrix
        %   of all ones the same size as A. The output from this third convolution
        %   is used to restore the edge effects. The 'noedge' parameter is enabled
        %   by default so that the output from 'nanconv' is identical to the output
        %   from 'conv2' when the input argument A has no NaN values.
        %
        % See also conv, conv2
        %
        % AUTHOR: Benjamin Kraus (bkraus@bu.edu, ben@benkraus.com)
        % Copyright (c) 2013, Benjamin Kraus
        % $Id: nanconv.m 4861 2013-05-27 03:16:22Z bkraus $

        % Process input arguments
        for arg = 1:nargin-2
            switch lower(varargin{arg})
                case 'edge'; edge = true; % Apply edge correction
                case 'noedge'; edge = false; % Do not apply edge correction
                case {'same','full','valid'}; shape = varargin{arg}; % Specify shape
                case 'nanout'; nanout = true; % Include original NaNs in the output.
                case 'nonanout'; nanout = false; % Do not include NaNs in the output.
                case {'2d','is2d'}; is1D = false; % Treat the input as 2D
                case {'1d','is1d'}; is1D = true; % Treat the input as 1D
            end
        end

        % Apply default options when necessary.
        if(exist('edge','var')~=1); edge = false; end
        if(exist('nanout','var')~=1); nanout = false; end
        if(exist('is1D','var')~=1); is1D = false; end
        if(exist('shape','var')~=1); shape = 'same';
        elseif(~strcmp(shape,'same'))
            error([mfilename ':NotImplemented'],'Shape ''%s'' not implemented',shape);
        end

        % Get the size of 'a' for use later.
        sza = size(a);

        % If 1D, then convert them both to columns.
        % This modification only matters if 'a' or 'k' is a row vector, and the
        % other is a column vector. Otherwise, this argument has no effect.
        if(is1D);
            if(~isvector(a) || ~isvector(k))
                error('MATLAB:conv:AorBNotVector','A and B must be vectors.');
            end
            a = a(:); k = k(:);
        end

        % Flat function for comparison.
        o = ones(size(a));

        % Flat function with NaNs for comparison.
        on = ones(size(a));

        % Find all the NaNs in the input.
        n = isnan(a);

        % Replace NaNs with zero, both in 'a' and 'on'.
        a(n) = 0;
        on(n) = 0;

        % Check that the filter does not have NaNs.
        if(any(isnan(k)));
            error([mfilename ':NaNinFilter'],'Filter (k) contains NaN values.');
        end

        % Calculate what a 'flat' function looks like after convolution.
        if(any(n(:)) || edge)
            flat = conv2(on,k,shape);
        else flat = o;
        end

        % The line above will automatically include a correction for edge effects,
        % so remove that correction if the user does not want it.
        if(any(n(:)) && ~edge); flat = flat./conv2(o,k,shape); end

        % Do the actual convolution
        c = conv2(a,k,shape)./flat;

        % If requested, replace output values with NaNs corresponding to input.
        if(nanout); c(n) = NaN; end

        % If 1D, convert back to the original shape.
        if(is1D && sza(1) == 1); c = c.'; end

    end

     function [STAT,BNDS] = inpoly2(varargin)
         %INPOLY2 compute "points-in-polygon" queries.
         %   [STAT] = INPOLY2(VERT,NODE,EDGE) returns the "inside/ou-
         %   tside" status for a set of vertices VERT and a polygon
         %   {NODE,EDGE} embedded in a two-dimensional plane. General
         %   non-convex and multiply-connected polygonal regions can
         %   be handled. VERT is an N-by-2 array of XY coordinates to
         %   be tested. STAT is an associated N-by-1 logical array,
         %   with STAT(II) = TRUE if VERT(II,:) is an interior point.
         %   The polygonal region is defined as a piecewise-straight-
         %   line-graph, where NODE is an M-by-2 array of polygon ve-
         %   rtices and EDGE is a P-by-2 array of edge indexing. Each
         %   row in EDGE represents an edge of the polygon, such that
         %   NODE(EDGE(KK,1),:) and NODE(EDGE(KK,2),:) are the coord-
         %   inates of the endpoints of the KK-TH edge. If the argum-
         %   ent EDGE is omitted it assumed that the vertices in NODE
         %   are connected in ascending order.
         %
         %   [STAT,BNDS] = INPOLY2(..., FTOL) also returns an N-by-1
         %   logical array BNDS, with BNDS(II) = TRUE if VERT(II,:)
         %   lies "on" a boundary segment, where FTOL is a floating-
         %   point tolerance for boundary comparisons. By default,
         %   FTOL = EPS ^ 0.85.
         %
         %   See also INPOLYGON

         %   This algorithm is based on a "crossing-number" test, co-
         %   unting the number of times a line extending from each
         %   point past the right-most region of the polygon interse-
         %   cts with the polygonal boundary. Points with odd counts
         %   are "inside". A simple implementation requires that each
         %   edge intersection be checked for each point, leading to
         %   O(N*M) complexity...
         %
         %   This implementation seeks to improve these bounds:
         %
         % * Sorting the query points by y-value and determining can-
         %   didate edge intersection sets via binary-search. Given a
         %   configuration with N test points, M edges and an average
         %   point-edge "overlap" of H, the overall complexity scales
         %   like O(M*H + M*LOG(N) + N*LOG(N)), where O(N*LOG(N))
         %   operations are required for sorting, O(M*LOG(N)) operat-
         %   ions required for the set of binary-searches, and O(M*H)
         %   operations required for the intersection tests, where H
         %   is typically small on average, such that H << N.
         %
         % * Carefully checking points against the bounding-box asso-
         %   ciated with each polygon edge. This minimises the number
         %   of calls to the (relatively) expensive edge intersection
         %   test.

         %   Darren Engwirda : 2017 --
         %   Email           : d.engwirda@gmail.com
         %   Last updated    : 19/12/2020

         %---------------------------------------------- extract args
         node = []; edge = []; vert = [];

         fTOL = eps ^ .85;

         if (nargin>=+1), vert = varargin{1}; end
         if (nargin>=+2), node = varargin{2}; end
         if (nargin>=+3), edge = varargin{3}; end
         if (nargin>=+4), fTOL = varargin{4}; end

         %---------------------------------------------- default args
         nnod = size(node,1) ;
         nvrt = size(vert,1) ;

         if (isempty(edge))
             edge = [(1:nnod-1)',(2:nnod)'; nnod,1];
         end

         %---------------------------------------------- basic checks
         if ( ~isnumeric(node) || ...
                 ~isnumeric(edge) || ...
                 ~isnumeric(vert) || ...
                 ~isnumeric(fTOL) )
             error('inpoly2:incorrectInputClass' , ...
                 'Incorrect input class.') ;
         end

         %---------------------------------------------- basic checks
         if (ndims(node) ~= +2 || ...
                 ndims(edge) ~= +2 || ...
                 ndims(vert) ~= +2 || ...
                 numel(fTOL) ~= +1 )
             error('inpoly2:incorrectDimensions' , ...
                 'Incorrect input dimensions.');
         end
         if (size(node,2)~= +2 || ...
                 size(edge,2)~= +2 || ...
                 size(vert,2)~= +2 )
             error('inpoly2:incorrectDimensions' , ...
                 'Incorrect input dimensions.');
         end

         %---------------------------------------------- basic checks
         if (min([edge(:)]) < +1 || ...
                 max([edge(:)]) > nnod)
             error('inpoly2:invalidInputs', ...
                 'Invalid EDGE input array.') ;
         end

         STAT = false(size(vert,1),1) ;
         BNDS = false(size(vert,1),1) ;

         %----------------------------------- prune points using bbox
         nmin = min(node,[],1);
         nmax = max(node,[],1);
         ddxy = nmax - nmin ;

         lbar = sum(ddxy) / 2.;

         veps = fTOL * lbar ;

         mask = ...
             vert(:,1) >= min (node(:,1)) - veps & ...
             vert(:,1) <= max (node(:,1)) + veps & ...
             vert(:,2) >= min (node(:,2)) - veps & ...
             vert(:,2) <= max (node(:,2)) + veps ;

         vert = vert(mask, :) ;

         if (isempty(vert)), return; end

         %-------------- flip to ensure the y-axis is the "long" axis
         vmin = min(vert,[],1);
         vmax = max(vert,[],1);
         ddxy = vmax - vmin ;

         if (ddxy(1) > ddxy(2))
             vert = vert(:,[2,1]) ;
             node = node(:,[2,1]) ;
         end

         %----------------------------------- sort points via y-value
         swap = ...
             node(edge(:,2),2) ...
             < node(edge(:,1),2) ;

         edge(swap,[1,2]) = ...
             edge(swap,[2,1]) ;

         [~,ivec] = ...
             sort(vert(:,+2)) ;
         vert = vert (ivec,:) ;

         if (exist( ...
                 'OCTAVE_VERSION','builtin')  > +0)

             if (exist('inpoly2_oct','file') == +3)

                 %-- delegate to the compiled version of the code if it's
                 %-- available

                 [stat,bnds] = ...
                     inpoly2_oct( ...
                     vert,node,edge,fTOL,lbar) ;

             else

                 %-- otherwise, just call the native m-code version

                 [stat,bnds] = ...
                     inpoly2_mat( ...
                     vert,node,edge,fTOL,lbar) ;

             end

         else

             %-- MATLAB's JIT is generally smart enough these days to
             %-- run this efficiently

             [stat,bnds] = ...
                 inpoly2_mat( ...
                 vert,node,edge,fTOL,lbar) ;

         end

         stat(ivec) = stat ;
         bnds(ivec) = bnds ;

         STAT(mask) = stat ;
         BNDS(mask) = bnds ;

     end


     function [stat,bnds] = ...
             inpoly2_mat(vert,node,edge,fTOL,lbar)
         %INPOLY2_MAT the local m-code version of the crossing-number
         %test. Loop over edges; do a binary-search for the first ve-
         %rtex that intersects with the edge y-range; do crossing-nu-
         %mber comparisons; break when the local y-range is exceeded.

         %   Darren Engwirda : 2017 --
         %   Email           : d.engwirda@gmail.com
         %   Last updated    : 19/12/2020

         feps = fTOL * lbar ^ +1 ;
         veps = fTOL * lbar ^ +1 ;

         nvrt = size (vert,1) ;
         nnod = size (node,1) ;
         nedg = size (edge,1) ;

         stat = false(nvrt,1) ;
         bnds = false(nvrt,1) ;

         %----------------------------------- loop over polygon edges
         for epos = +1 : size(edge,1)

             inod = edge(epos,1) ;
             jnod = edge(epos,2) ;

             %------------------------------- calc. edge bounding-box
             yone = node(inod,2) ;
             ytwo = node(jnod,2) ;
             xone = node(inod,1) ;
             xtwo = node(jnod,1) ;

             xmin = min(xone,xtwo) ;
             xmax = max(xone,xtwo) ;

             xmin = xmin - veps;
             xmax = xmax + veps;
             ymin = yone - veps;
             ymax = ytwo + veps;

             ydel = ytwo - yone;
             xdel = xtwo - xone;

             edel = abs(xdel) + ydel ;

             %------------------------------- find top VERT(:,2)<YONE
             ilow = +1; iupp = nvrt;

             while (ilow < iupp - 1)    % binary search
                 imid = ilow ...
                     + floor((iupp-ilow) / 2);

                 if (vert(imid,2) < ymin)
                     ilow = imid ;
                 else
                     iupp = imid ;
                 end
             end

             if (vert(ilow,2) >= ymin)
                 ilow = ilow - 1 ;
             end

             %------------------------------- calc. edge-intersection
             for jpos = ilow+1 : nvrt

                 if (bnds(jpos)), continue ; end

                 xpos = vert(jpos,1) ;
                 ypos = vert(jpos,2) ;

                 if (ypos <= ymax)
                     if (xpos >= xmin)
                         if (xpos <= xmax)

                             %------------------- compute crossing number
                             mul1 = ...
                                 ydel * (xpos - xone) ;
                             mul2 = ...
                                 xdel * (ypos - yone) ;

                             if ((feps * edel) >= ...
                                     abs(mul2 - mul1) )

                                 %------------------- BNDS -- approx. on edge
                                 bnds(jpos)= true ;
                                 stat(jpos)= true ;

                             elseif (ypos == yone ...
                                     &&  xpos == xone )

                                 %------------------- BNDS -- match about ONE
                                 bnds(jpos)= true ;
                                 stat(jpos)= true ;

                             elseif (ypos == ytwo ...
                                     &&  xpos == xtwo )

                                 %------------------- BNDS -- match about TWO
                                 bnds(jpos)= true ;
                                 stat(jpos)= true ;

                             elseif (mul1 < mul2)

                                 if (ypos >= yone ...
                                         && ypos <  ytwo)

                                     %------------------- advance crossing number
                                     stat(jpos) = ...
                                         ~stat (jpos) ;

                                 end

                             end

                         end
                     else

                         if (ypos >= yone ...
                                 && ypos <  ytwo)

                             %------------------- advance crossing number
                             stat(jpos) = ...
                                 ~stat (jpos) ;

                         end

                     end
                 else

                     break ;            % done -- due to the sort

                 end

             end

         end

     end

     function updatebreaksNumbering

         breaksRingsCumSum = zeros(length(1:max(find(max(userRings)))),1);
         if length(breaksRings) >= 0 && length(breaksRingsCumSum) > 0
             breaksRingsCumSum(breaksRings) = 1;
             breaksRingsCumSum = cumsum(breaksRingsCumSum);
             breaksRingsCumSum(end+1) = breaksRingsCumSum(end);
         end

     end

    function makeLiPD(this_bib,this_cite,travelTotal,travelTotal_std,inputTopYear,this_year,this_month)

        % save in LiPD format
        if length(this_bib)>3
            if any(strcmp(saveFileName,dataOwners),2) % only allow LiPD for core owner(s)
                %if makeLiPDIn.Value == 1 || makeLiPDIn2.Value == 1 % if set to create LiPD
                    try
                        bibtexEntry = this_bib;

                        % Regular expression to capture key-value pairs
                        % This pattern looks for 'key = {value}' or 'key = value' structures
                        pattern = '\s*(?<key>\w+)\s*=\s*\{?(?<value>[^}]+)\}?';

                        % Use regexp to find all matches and return them as a structure array
                        matches = regexp(bibtexEntry, pattern, 'names');

                        pattern2 = '\s*pages\s*=\s*\{?(?<value>[^}]+)\}?';
                        matches2 = regexp(bibtexEntry, pattern2, 'names');

                        temptab = struct2table(matches);
                        if length(matches2) && length(find(strcmp(temptab{:,1},'pages')))==0
                            matches(length(matches)+1).key = 'pages';
                            matches(length(matches)).value = matches2.value;
                        end

                        bibtab = struct2table(matches);

                        % initialize
                        citation_doi = 'no doi found';
                        citation_title = 'no title found';
                        citation_author = 'no author found';
                        citation_journal = 'no journal found';
                        citation_volume = 'no volume found';
                        citation_number = 'no number found';
                        citation_pages = 'no pages found';
                        citation_year = 'no year found';

                        doi_idx = find(strcmp(bibtab{:,1},'DOI'));
                        if length(doi_idx)
                            citation_doi = bibtab{doi_idx,2};
                        end
                        title_idx = find(strcmp(bibtab{:,1},'title'));
                        if length(title_idx)
                            citation_title = bibtab{title_idx,2};
                        end
                        author_idx = find(strcmp(bibtab{:,1},'author'));
                        if length(author_idx)
                            citation_author = bibtab{author_idx,2};
                        end
                        journal_idx = find(strcmp(bibtab{:,1},'journal'));
                        if length(journal_idx)
                            citation_journal = bibtab{journal_idx,2};
                        end
                        volume_idx = find(strcmp(bibtab{:,1},'volume'));
                        if length(volume_idx)
                            citation_volume = bibtab{volume_idx,2};
                        end
                        number_idx = find(strcmp(bibtab{:,1},'number'));
                        if length(number_idx)
                            citation_number = bibtab{number_idx,2};
                        end
                        page_idx = find(strcmp(bibtab{:,1},'pages'));
                        if length(page_idx)
                            citation_pages = bibtab{page_idx,2};
                        end
                        year_idx = find(strcmp(bibtab{:,1},'year'));
                        if length(year_idx)
                            citation_year = bibtab{year_idx,2};
                        end

                        lipd = struct;
                        measurementTable = struct;
                        year = struct;
                        year.description = 'calendar year CE';
                        year.primaryAgeColumn = 1;
                        year.proxy = [];
                        year.QCnotes = [];
                        year.samplingResolution = 'annual';
                        year.genus = treeDir.textdata{dirRow,5};
                        year.units = 'year CE';
                        year.variableName = 'year';
                        year.uncertainty = [];
                        year.uncertaintyUnits = '';
                        year.number = 1;
                        year.values = inputTopYear+1 - (length(travelTotal)-(length(travelTotal):-1:1)+1)';
                        year.missingValue = 'NaN';
                        year.hasMaxValue = nanmax(year.values);
                        year.hasMinValue = nanmin(year.values);
                        year.hasMeanValue = nanmean(year.values);
                        year.hasMedianValue = nanmedian(year.values);
                        year.TSid = strcat(treeName,'.year');
                        measurementTable.year = year;
                        treeRingWidth = struct;
                        treeRingWidth.description = 'tree ring width';
                        treeRingWidth.primaryAgeColumn = 0;
                        treeRingWidth.proxy = [];
                        treeRingWidth.QCnotes = [];
                        treeRingWidth.samplingResolution = 'annual';
                        treeRingWidth.genus = treeDir.textdata{dirRow,5};
                        treeRingWidth.units = 'mm per year';
                        treeRingWidth.variableName = 'ringWidth';
                        treeRingWidth.uncertainty = travelTotal_std(length(travelTotal):-1:1);
                        treeRingWidth.uncertaintyUnits = 'mm per yr';
                        treeRingWidth.number = 2;
                        treeRingWidth.values = travelTotal(length(travelTotal):-1:1);
                        treeRingWidth.missingValue = 'NaN';
                        treeRingWidth.hasMaxValue = nanmax(treeRingWidth.values);
                        treeRingWidth.hasMinValue = nanmin(treeRingWidth.values);
                        treeRingWidth.hasMeanValue = nanmean(treeRingWidth.values);
                        treeRingWidth.hasMedianValue = nanmedian(treeRingWidth.values);
                        treeRingWidth.TSid = strcat(treeName,'.treeRingWidth');
                        measurementTable.treeRingWidth = treeRingWidth;
                        treeRingWidthUncertainty = struct;
                        treeRingWidthUncertainty.description = 'annual ring width standard deviation';
                        treeRingWidthUncertainty.primaryAgeColumn = 0;
                        treeRingWidthUncertainty.proxy = [];
                        treeRingWidthUncertainty.QCnotes = [];
                        treeRingWidthUncertainty.samplingResolution = 'annual';
                        treeRingWidthUncertainty.genus = treeDir.textdata{dirRow,5};
                        treeRingWidthUncertainty.units = 'mm per year';
                        treeRingWidthUncertainty.variableName = 'ringWidthStandardDeviation';
                        treeRingWidthUncertainty.uncertainty = [];
                        treeRingWidthUncertainty.uncertaintyUnits = 'mm per yr';
                        treeRingWidthUncertainty.number = 3;
                        treeRingWidthUncertainty.values = travelTotal_std(length(travelTotal):-1:1);
                        treeRingWidthUncertainty.missingValue = 'NaN';
                        treeRingWidthUncertainty.hasMaxValue = nanmax(treeRingWidthUncertainty.values);
                        treeRingWidthUncertainty.hasMinValue = nanmin(treeRingWidthUncertainty.values);
                        treeRingWidthUncertainty.hasMeanValue = nanmean(treeRingWidthUncertainty.values);
                        treeRingWidthUncertainty.hasMedianValue = nanmedian(treeRingWidthUncertainty.values);
                        treeRingWidthUncertainty.TSid = strcat(treeName,'.treeRingWidthUncertainty');
                        measurementTable.treeRingWidthUncertainty = treeRingWidthUncertainty;
                        paleoData = struct;
                        paleoData.measurementTable{1} = measurementTable;
                        lipd.paleoData{1} = paleoData;
                        lipd.archiveType = 'Tree';
                        lipd.collectionYear = strcat(num2str(this_year),'-',this_month);
                        lipd.createdBy = ['TreeTracer user: ',saveFileName];
                        lipd.datasetId = treeName;
                        lipd.dataSetName = treeName;
                        lipd.datasetVersion = '1.0';
                        lipd.maxYear = this_year;
                        lipd.minYear = this_year-length(travelTotal);
                        lipd.notes = treeDir.textdata{dirRow,7};
                        lipd.originalDataUrl = this_cite;
                        pub = struct;
                        pub.altDataURL = '';
                        citationAuthor = struct('name',citation_author(1));
                        pub.author = citationAuthor;
                        %pub.author = citation_author(1);
                        pub.citation = this_bib;
                        pub.doi = this_cite;
                        pub.doiData = citation_doi{1};
                        numAuth = strsplit(citation_author{1},' and');
                        pub.firstAuthor = numAuth{1};
                        pub.title = citation_title{1};
                        pub.journal = citation_journal{1};
                        pub.pages = citation_pages{1};
                        pub.volume = citation_volume{1};
                        pub.number = citation_number{1};
                        pub.pubYear = citation_year{1};
                        pub.year = str2num(citation_year{1});
                        lipd.pub{1} = pub;
                        geo = struct;
                        geo.location = [];
                        geo.notes = [];
                        geo.siteName = treeDir.textdata{dirRow,3};
                        geo.latitude = treeDir.data(dirRow+1,3);
                        geo.meanLat = geo.latitude;
                        geo.longitude = treeDir.data(dirRow+1,4);
                        geo.meanLon = geo.longitude;
                        geo.elevation = treeDir.data(dirRow+1,5);
                        geo.meanElev = geo.elevation;
                        lipd.geo = geo;
                        changelog = 'NA';
                        lipd.changelog = changelog;
                        lipd.lipdVersion = 1.3;
                        addpath(fullfile('lipd_utilities'))
                        addpath(fullfile('lipd_utilities','jsonlab-1.0RC1'))
                        addpath(fullfile('lipd_utilities','jsonlab-1.0RC1','jsonlab'))
                        if ~exist(fullfile(selpath,'my_trees','datasets',currentRegion,treeName,sectionName),'dir')
                            mkdir(fullfile(selpath,'my_trees','datasets',currentRegion,treeName,sectionName))
                        end
                        writeLiPDFile(lipd,fullfile(selpath,'my_trees','datasets',currentRegion,treeName,sectionName))
                    catch
                    end
                %end
            end
        end

    end



